	('1bed3763-df4a-44ba-87d9-bca717b2b8d3', 'pr43622532', 'batdongsan', 'https://batdongsan.com.vn/cho-thue-shophouse-nha-pho-thuong-mai-thu-thiem-lakeview-phuong-an-khanh-tp-ho-chi-minh/cho-du-p-q-2-pr43622532', 'For Rent: Shophouse in Lakeview Thủ Thiêm, 75 million/month', 'Lakeview Thủ Thiêm, p.An Khánh, Hồ Chí Minh', 'lakeview th thim pan khnh h ch minh', 'other', 75000000, '75 triệu/tháng', '360 m²', 'This shophouse located in the new center of Lakeview Thủ Thiêm (D''Verano) is available for rent at 75 million VND per month. With a size of 360m², it is situated at a prime location near major roads and infrastructure developments, making it perfect for business operations. Contact for more information.', '{"Bright and airy corridor with natural light","Breathtaking indoor-outdoor flow with expansive views"}', '{Parking,Security,CCTV,Elevator,"Large Windows","Hardwood Floors","Indoor Plants","Natural Light","Polished Marble Flooring","Sliding Glass Doors","Outdoor Access"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43622532/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43622532/1.jpg}', 'Trần Đức Thịnh', '0934 846 ***', NULL, '{"cozy": 4, "urban": 6, "colors": ["Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 1, "styles": ["Spacious", "Modern", "Luxurious"], "elegant": 8, "colorful": 2, "spacious": 9, "luxurious": 8, "activities": ["Relaxing", "Entertaining"], "minimalist": 7, "natural_light": 9, "image_analyses": [{"amenities": ["Elevator", "Large Windows", "Hardwood Floors", "Indoor Plants"], "image_index": 0, "vibe_scores": {"cozy": 5, "urban": 6, "modern": 8, "elegant": 7, "spacious": 7, "luxurious": 7, "minimalist": 6, "natural_light": 8}, "image_highlight": "Bright and airy corridor with natural light", "detailed_analysis": "This elegant corridor features expansive large windows that flood the space with natural light, creating an uplifting atmosphere. The hardwood flooring adds warmth and sophistication, while the modern elevator access enhances convenience. The minimalist decor and indoor plants contribute to a serene ambiance, making it a perfect transition area that evokes a sense of calm and relaxation. The flow of the space is open and inviting, ideal for a leisurely stroll or a moment of tranquility.", "suggested_amenities": ["Natural Light", "Indoor Plants"], "suggested_activities": ["Relaxing"]}, {"amenities": ["Large Windows", "Polished Marble Flooring", "Sliding Glass Doors"], "image_index": 1, "vibe_scores": {"cozy": 2, "urban": 6, "modern": 8, "elegant": 8, "spacious": 10, "luxurious": 9, "minimalist": 7, "natural_light": 10}, "image_highlight": "Breathtaking indoor-outdoor flow with expansive views", "detailed_analysis": "This expansive space features sleek polished marble flooring that radiates luxury and sophistication, complemented by large sliding glass doors that invite an abundance of natural light. The open layout enhances the flow, creating an inviting atmosphere ideal for hosting gatherings or simply unwinding. The seamless transition to the outdoors provides a refreshing connection to nature, making it perfect for entertaining or enjoying quiet moments. The minimalist design and elegant tones create a calming yet upscale environment, setting the stage for a premium lifestyle experience.", "suggested_amenities": ["Natural Light", "Outdoor Access"], "suggested_activities": ["Relaxing", "Entertaining"]}]}', '2026-04-21 00:06:57.929+00', '2026-06-24 15:31:44.469+00', '2026-06-24 03:00:10.307+00', true, '2026-04-21 00:06:59.810216+00', '2026-06-24 03:00:10.323249+00', NULL, NULL, '4+ Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
