	('6de544a8-3db6-43ff-bd4f-63bc3e73f3db', 'nt131472214', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-10-tp-ho-chi-minh/131472214.htm#px=sr-stickyad-[po-1][pl-top]', 'Beautiful 2 Bedroom Apartment for Rent at Hà Đô Centrosa Garden, District 10', '200, 12, Ward 12, District 10, Ho Chi Minh City', '200 12 ward 12 district 10 ho chi minh city', 'ho_chi_minh', 29000000, '29 million/month', '100 m²', 'This stunning 2-bedroom apartment located in the prestigious Hà Đô Centrosa Garden offers a spacious 100 m² of living space, perfect for families or professionals. The apartment features a beautiful southwest view, allowing for ample natural light throughout the day. It includes two bedrooms, two bathrooms, and a versatile layout that can accommodate a home office. The apartment is fully furnished with essential amenities such as a TV, refrigerator, washing machine, microwave, induction stove, and three air conditioners. The large balcony provides a fantastic city view, enhancing your living experience. Located in District 10, this apartment is conveniently situated near major districts, making commuting a breeze. The complex offers a range of facilities including a swimming pool, gym, parks, and supermarkets, ensuring a comfortable lifestyle.', '{"Bright open living space with city views","Culinary creativity hub with modern appliances","Elegant dining area for social gatherings","Stylish home office with curated decor and organization","Dedicated workspace for productivity and focus"}', '{"Air Conditioning",Refrigerator,"Washing Machine",Microwave,"Induction Stove","Swimming Pool",Gym,Parks,Supermarkets}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131472214/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131472214/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131472214/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131472214/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131472214/4.jpg}', 'Cao Thành Đạt', NULL, NULL, '{"colors": [], "styles": [], "activities": [], "image_analyses": [{"image_index": 0, "image_highlight": "Bright open living space with city views", "suggested_amenities": ["Large Windows", "Air Conditioning"]}, {"image_index": 1, "image_highlight": "Culinary creativity hub with modern appliances", "suggested_amenities": ["Kitchen Appliances", "Dining Set"]}, {"image_index": 2, "image_highlight": "Elegant dining area for social gatherings", "suggested_amenities": ["Dining Table", "Air Conditioning Unit"]}, {"image_index": 3, "image_highlight": "Stylish home office with curated decor and organization", "suggested_amenities": ["Wall-mounted shelving", "Wooden desk"]}, {"image_index": 4, "image_highlight": "Dedicated workspace for productivity and focus", "suggested_amenities": ["Desk", "Floor Lamp"]}]}', '2026-03-28 05:02:12.365+00', '2026-06-24 15:31:44.469+00', '2026-06-18 03:00:04.429+00', true, '2026-03-28 05:02:12.412421+00', '2026-06-18 03:00:04.448452+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
