	('8697e4c6-6e2d-41fa-a05e-a3d062f4dfa7', 'pr45647460', 'batdongsan', 'https://batdongsan.com.vn/cho-thue-can-ho-chung-cu-xa-duong-xa-vinhomes-ocean-park-gia-lam/quy-chinh-chu-cho-tot-nhat-cap-nhat-hom-nay-pr45647460', 'Affordable Apartments for Rent at Vinhomes Ocean Park', 'Vinhomes Ocean Park, Gia Lâm, Hà Nội', 'vinhomes ocean park gia lm h ni', 'hanoi', 5500000, '5,5 triệu/tháng', '27', 'Discover the best rental options at Vinhomes Ocean Park with affordable prices starting from 5.5 million VND for studio apartments. These units come fully furnished and are ready for immediate occupancy. The apartments are located in a vibrant community with access to various amenities, making it an ideal choice for those seeking a comfortable living environment.', '{"Stylish ceiling fan with warm light fixtures","Stylish dining table with elegant chairs","Textured accent wall with stylish vertical lines","Large mirror reflecting light and space","Large window with a view of greenery outside"}', '{"ceiling fan",TV,plants,"decorative sculptures",Balcony,"Smart TV",sofa,"dining table",chairs,television,"plant decor",Television,bed,"accent wall",nightstand,plant,"air conditioning","Air conditioning",Nightstand,"coffee table","large window",mirror,Sofa,"Coffee table",Plant,"Storage unit","Smart home features"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45647460/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45647460/1.jpg}', 'Ngọc Khánh', '0862 225 ***', NULL, '{"cozy": 7, "urban": 7, "colors": ["Warm", "Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 2, "styles": ["Modern", "Minimalist", "Cozy"], "elegant": 7, "colorful": 4, "spacious": 6, "luxurious": 6, "activities": ["Relaxing", "Entertaining", "Reading"], "minimalist": 8, "natural_light": 8, "image_analyses": [{"amenities": ["ceiling fan", "TV", "plants", "decorative sculptures"], "image