	('01c41cec-bab7-41fc-b96f-883ece9e959f', 'nt131557689', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-thanh-pho-thu-duc-tp-ho-chi-minh/131557689.htm#px=sr-stickyad-[po-1][pl-top]', 'Spacious and Bright Mini Apartment in Tranquil Phú Hữu', '41, Đường Gò Cát, Phường Phú Hữu (Quận 9 cũ), Thành phố Thủ Đức, Tp Hồ Chí Minh', '41 ng g ct phng ph hu qun 9 c thnh ph th c tp h ch minh', 'ho_chi_minh', 3500000, '3,5 triệu/tháng', '30 m²', 'Welcome to your new sanctuary in the heart of Phú Hữu! This spacious 30 m² mini apartment is designed for comfort and tranquility, perfect for those seeking a peaceful retreat. Bathed in natural light, the space features large windows that invite the outdoors in, creating a bright and airy atmosphere. The minimalist design is complemented by clean lines and a neutral color palette, making it easy to personalize with your own decor. Imagine sipping your morning coffee by the window or unwinding after a long day in this serene environment. With a private bathroom and a quiet neighborhood, you can enjoy the luxury of privacy and relaxation. Ideal for individuals or couples, this apartment is not just a place to live, but a lifestyle choice that embraces comfort and simplicity.', '{"Stylish entrance with modern wooden slats","Bright and airy open space with natural light","Premium living space feature"}', '{"Air Conditioning",WiFi,"Private Bathroom","Natural Light","Modern Fixtures","Storage Cabinets","Lighting Fixtures"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131557689/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131557689/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131557689/2.jpg}', 'Phan Anh', '035528***', NULL, '{"cozy": 6, "urban": 5, "colors": ["Warm", "Cool", "Bright", "Refined"], "modern": 6, "rustic": 4, "styles": ["Modern", "Cozy", "Spacious"], "elegant": 6, "colorful": 5, "spacious": 6, "luxurious": 5, "activities": ["Relaxing", "Living"], "minimalist": 5, "natural_light": 7, "image_analyses": [{"image_index": 0, "image_highlight": "Stylish entrance with modern wooden slats", "suggested_amenities": ["Outdoor seating", "Decorative plants"]}, {"image_index": 1, "image_highlight": "Bright and airy open space with natural light", "suggested_amenities": ["Natural Light", "Open Floor Plan"]}, {"image_index": 2, "image_highlight": "Premium living space feature", "suggested_amenities": ["Air Conditioning", "Natural Light", "Modern Fixtures", "Storage Cabinets", "Lighting Fixtures"]}]}', '2026-04-14 01:01:50.671+00', '2026-06-24 15:31:44.469+00', '2026-06-21 03:00:04.181+00', true, '2026-04-14 01:01:53.218946+00', '2026-06-21 03:00:04.24489+00', NULL, NULL, 'Studio', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('91c90ed0-80ae-434a-a69b-49d1ae65789d', 'nt122615208', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-10-tp-ho-chi-minh/122615208.htm#px=sr-stickyad-[po-1][pl-top]', '1 Bedroom Apartment for Rent in Hà Đô Centrosa Garden, District 10, Ho Chi Minh City', '200, 12, Ward 12, District 10, Ho Chi Minh City', '200 12 ward 12 district 10 ho chi minh city', 'ho_chi_minh', 17500000, '17.5 million/month', '61 m²', 'This stunning 1-bedroom apartment in Hà Đô Centrosa Garden offers a spacious 61 m² living area, perfect for individuals or couples looking for a comfortable home in the heart of Ho Chi Minh City. The apartment is available for rent at 17.5 million VND per month, providing excellent value for its size and location. Residents can enjoy a range of amenities including a swimming pool, gym, children''s playground, and BBQ area. The complex also features convenient shops and restaurants, ensuring that everything you need is just a short walk away. With its modern design and prime location in District 10, this apartment is an ideal choice for those seeking a vibrant urban lifestyle.', '{"Inviting entertainment space with Netflix access","Modern kitchen island with bar seating","Serene sleeping environment with elegant decor","Natural light enhancing serene sleeping environment","Sleek kitchen island with stylish bar seating"}', '{"Swimming Pool",Gym,"Children''s Playground","BBQ Area","Convenience Stores",Restaurants,"Air Conditioning","Natural Light","Modern Fixtures","Storage Cabinets","Lighting Fixtures"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt122615208/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt122615208/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt122615208/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt12261