	('5f9e7509-5b52-490e-be32-73679f06e63e', 'nt130866728', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-7-tp-ho-chi-minh/130866728.htm#px=sr-stickyad-[po-1][pl-top]', 'Chic Urban Retreat in Q7 Boulevard with Abundant Natural Light', 'Nguyễn Lương Bằng, Phường Phú Mỹ, Quận 7, Tp Hồ Chí Minh', 'nguyn lng bng phng ph m qun 7 tp h ch minh', 'ho_chi_minh', 13000000, '13 triệu/tháng', '50 m²', 'Welcome to your chic urban retreat in the heart of Q7 Boulevard, where modern design meets comfort. This stylish 2-bedroom apartment boasts a generous 50 m² of living space, flooded with natural light that creates a warm and inviting atmosphere. The open layout seamlessly connects the living area to the kitchen, making it perfect for hosting friends or enjoying a quiet evening at home. The contemporary furnishings are complemented by a soothing color palette, featuring soft neutrals and pops of color that enhance the space''s vibrancy. Imagine sipping your morning coffee on the balcony, basking in the sunlight, or unwinding after a long day in your cozy living room. With fully furnished interiors, you can move in and start living your best life immediately. The apartment''s thoughtful design supports your daily rituals, whether it''s remote work or entertaining guests. Experience the perfect blend of style and functionality in this urban oasis.', '{"Light blue accent wall with decorative shelves","Sleek kitchen with integrated appliances and plants","Round sink on a sleek countertop with storage","Black dining table with stylish beige chairs","LG washing machine with transparent door design"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Parking,Pool,Gym,Elevator,"Security Camera","Smart TV","Decorative Shelves","Coffee Table",Sofa,"integrated appliances",shelves,plants,Dishwasher,Refrigerator,sink,countertop,"storage cabinet",toilet,mirror,"Heated floors","Smart mirror",refrigerator,"decorative shelves","dining table",sofa,"LG washing machine","plumbing connections","In-unit laundry","Storage solutions"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130866728/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130866728/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130866728/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130866728/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130866728/4.jpg}', 'Tuấn Nguyễn', '084891 ***', NULL, '{"cozy": 6, "urban": 7, "colors": ["Warm", "Neutral", "Cool", "Refined"], "modern": 8, "rustic": 2, "styles": ["Minimalist", "Modern", "Elegant"], "elegant": 7, "colorful": 4, "spacious": 6, "amenities": ["TV", "shelves", "air conditioning", "sofa", "coffee table", "kitchen cabinets", "stove", "sink", "decorative plants", "countertop", "mirror", "toilet", "Dining table", "Chairs", "Refrigerator", "Sofa", "Decorative plants", "LG washing machine", "water pipes", "window blinds"], "luxurious": 6, "activities": ["Relaxing", "Entertaining", "Cooking"], "minimalist": 9, "natural_light": 6, "image_analyses": [{"amenities": ["Air Conditioning", "Smart TV", "Decorative Shelves", "Coffee Table", "Sofa"], "image_index": 0, "vibe_scores": {"cozy": 7, "urban": 8, "modern": 8, "elegant": 7, "spacious": 7, "luxurious": 6, "minimalist": 9, "natural_light": 6}, "image_highlight": "Light blue accent wall with decorative shelves", "detailed_analysis": "The image showcases a modern living room with a light blue accent wall and wooden shelves. A mounted TV is framed by a marble panel, enhancing the contemporary feel. The room features a cozy sofa with colorful cushions and a round coffee table. Natural light is subtly reflected off the glossy floor, contributing to a bright atmosphere. The overall design is minimalist yet invitin