	('ef5cbb11-0db6-4965-8aa8-274c00fa8c9f', 'nt131632581', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-1-tp-ho-chi-minh/131632581.htm#px=sr-stickyad-[po-1][pl-top]', 'Elegant Riverside Retreat: A Fully Furnished 2-Bedroom Haven with City and River Views', 'Tôn Đức Thắng, Phường Bến Nghé, Quận 1, Tp Hồ Chí Minh', 'tn c thng phng bn ngh qun 1 tp h ch minh', 'ho_chi_minh', 26000000, '26 triệu/tháng', '72 m²', 'Discover a sophisticated urban sanctuary in the heart of Vinhomes Golden River BaSon. This elegant 2-bedroom apartment, spanning 72m², offers a refined living experience with breathtaking views of the river and the vibrant Bitexco city skyline. Step into a space where every detail has been carefully curated, featuring high-end, full furnishings that exude modern luxury and comfort. The open-plan living area is bathed in natural light, creating an inviting atmosphere perfect for both relaxation and entertaining. Imagine starting your day with a cup of coffee, gazing at the serene river, or unwinding in the evening as the city lights twinkle below. The two spacious bedrooms provide private havens, each designed with comfort in mind, while the two well-appointed bathrooms offer convenience and style. This apartment is not just a place to live; it''s a lifestyle choice, offering immediate occupancy for those seeking a seamless transition into a premium urban dwelling. The design aesthetic blends contemporary lines with warm textures, creating a harmonious and welcoming environment that feels both grand and intimate.', '{"Floor-to-ceiling windows with panoramic city views","Chic kitchen area for culinary creativity","Tranquil retreat with expansive city views","Luxurious spa-like shower experience","Serene retreat with elegant decor and ample natural light"}', '{"Fully Furnished","River View","City View","Air Conditioning","Natural Light","Modern Fixtures","Storage Cabinets","Lighting Fixtures"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131632581/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131632581/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131632581/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131632581/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131632581/4.jpg}', 'CTy TNHH BĐS Phương Mỹ Home', '090747***', NULL, '{"cozy": 6, "urban": 5, "colors": ["Warm", "Cool", "Bright", "Refined"], "modern": 6, "rustic": 4, "styles": ["Modern", "Cozy", "Spacious"], "elegant": 6, "colorful": 5, "spacious": 6, "luxurious": 5, "activities": ["Relaxing", "Living"], "minimalist": 5, "natural_light": 7, "image_analyses": [{"image_index": 0, "image_highlight": "Floor-to-ceiling windows with panoramic city views", "suggested_amenities": ["Large Screen TV", "Dining Table"]}, {"image_index": 1, "image_highlight": "Chic kitchen area for culinary creativity", "suggested_amenities": ["Modern Kitchen", "Sofa"]}, {"image_index": 2, "image_highlight": "Tranquil retreat with expansive city views", "suggested_amenities": ["Large Screen TV", "Premium Mattress"]}, {"image_index": 3, "image_highlight": "Luxurious spa-like shower experience", "suggested_amenities": ["Luxury Bathroom", "Elegant Shower"]}, {"image_index": 4, "image_highlight": "Serene retreat with elegant decor and ample natural light", "suggested_amenities": ["Luxury Bedroom", "Comfortable Bedding"]}]}', '2026-04-15 00:31:28.322+00', '2026-06-24 15:31:44.469+00', '2026-06-18 03:00:11.926+00', true, '2026-04-15 00:31:31.454562+00', '2026-06-18 03:00:11.943167+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
