rage/v1/object/public/external-property-images/nhatot-nt131077260/4.jpg}', 'Phùng Minh Quyên', NULL, NULL, '{"colors": [], "styles": [], "activities": [], "image_analyses": [{"image_index": 0, "image_highlight": "Bright balcony access with urban views", "suggested_amenities": ["Air Conditioning", "Large Windows"]}, {"image_index": 1, "image_highlight": "Functional kitchen area with modern finishes", "suggested_amenities": ["Modern Kitchen", "Kitchen Appliances"]}, {"image_index": 2, "image_highlight": "Efficient workspace with integrated storage solutions", "suggested_amenities": ["Workspace", "Storage Cabinets"]}, {"image_index": 3, "image_highlight": "Sleek modern bathroom with spacious shower", "suggested_amenities": ["Shower", "Bathroom Sink"]}, {"image_index": 4, "image_highlight": "Dedicated workspace for productivity and focus", "suggested_amenities": ["Desk", "Wardrobe"]}]}', '2026-03-28 08:31:45.696+00', '2026-06-24 15:31:44.469+00', '2026-06-15 03:00:21.831+00', true, '2026-03-28 08:31:45.7138+00', '2026-06-15 03:00:21.817752+00', NULL, NULL, 'Studio', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
