-images/nhatot-nt131792324/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131792324/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131792324/4.jpg}', 'Dang Nhat Bao Anh', '076500 ***', NULL, '{"cozy": 7, "urban": 6, "colors": ["Warm", "Neutral", "Cool", "Bright"], "modern": 8, "rustic": 2, "styles": ["Minimalist", "Modern", "Cozy"], "elegant": 5, "colorful": 3, "spacious": 6, "amenities": ["bed", "bedding", "pillows", "window", "floor", "refrigerator", "desk", "chair", "wardrobe", "fridge", "balcony", "ergonomic chair"], "luxurious": 4, "activities": ["Reading", "Relaxing", "Working"], "minimalist": 9, "natural_light": 8, "image_analyses": [{"amenities": ["bed", "bedding", "decorative pillows", "window"], "image_index": 0, "vibe_scores": {"cozy": 7, "urban": 5, "modern": 8, "elegant": 3, "spacious": 5, "luxurious": 4, "minimalist": 9, "natural_light": 6}, "image_highlight": "soft blue bedding with matching decorative pillows", "detailed_analysis": "The image showcases a bedroom featuring a neatly made bed with soft blue bedding and matching decorative pillows. The minimalist design is complemented by a light-colored wall and a window that allows natural light to fill the space. The overall ambiance is cozy and inviting, making it suitable for relaxation or reading. The room is functional with essential furniture, creating a serene atmosphere.", "suggested_amenities": ["Air Conditioning", "Wi-Fi"], "suggested_activities": ["Reading", "Relaxing"]}, {"amenities": ["refrigerator", "desk", "chair", "wardrobe", "balcony"], "image_index": 1, "vibe_scores": {"cozy": 7, "urban": 7, "modern": 8, "elegant": 5, "spacious": 6, "luxurious": 4, "minimalist": 9, "natural_light": 8}, "image_highlight": "large window with balcony access and greenery view", "detailed_analysis": "The image showcases a bright room featuring a large window that opens to a balcony, allowing for ample natural light and a view of greenery. A modern desk and ergonomic chair are positioned nearby, along with a compact refrigerator. The minimalist design is complemented by light-colored walls and flooring, creating a fresh and inviting atmosphere.", "suggested_amenities": ["Air conditioning", "Refrigerator"], "suggested_activities": ["Working", "Reading", "Relaxing"]}, {"amenities": ["desk", "chair", "refrigerator"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 8, "modern": 7, "elegant": 5, "spacious": 6, "luxurious": 4, "minimalist": 8, "natural_light": 7}, "image_highlight": "study desk with ergonomic chair and refrigerator", "detailed_analysis": "The image showcases a well-lit room featuring a study desk paired with an ergonomic chair, ideal for working or studying. A compact refrigerator is positioned nearby, adding convenience for snacks or drinks. The minimalist design is complemented by soft colors, enhancing the cozy atmosphere of the space. The large window allows natural light to flood the room, creating an inviting environment. Overall, the layout is practical and functional, making it suitable for various activities.", "suggested_amenities": ["Wi-Fi", "Air conditioning"], "suggested_activities": ["Working", "Reading", "Relaxing"]}, {"amenities": ["study desk", "ergonomic chair", "refrigerator", "wardrobe"], "image_index": 3, "vibe_scores": {"cozy": 6, "urban": 6, "modern": 7, "elegant": 5, "spacious": 5, "luxurious": 4, "minimalist": 8, "natural_light": 8}, "image_highlight": "white wardrobe and study desk against light walls", "detailed_analysis": "The image showcases a bright room with a white wardrobe and a study desk. The ergonomic chair is positioned at the desk, providing a comfortable workspace. Light-colored walls enhance the natural light coming from the large window, which leads to the balcony. The refrigerator is conveniently placed nearby, making it easy to access. Overall, the room has a clean and minimalist aesthetic, ideal for both work and relaxation.", "suggested_amenities": ["Wi-Fi", "Laundry facilities"], "suggested_activities": ["Working", "Reading", "Relaxing"]}, {"amenities": ["study desk", "ergonomic chair", "refrigerator", "wardrobe"], "image_index": 4, "vibe_scores": {"cozy": 7, "urban": 6, "modern": 8, "elegant": 7, "spacious": 6, "luxurious": 5, "minimalist": 9, "natural_light": 9}, "image_highlight": "large white wardrobe with sleek design", "detailed_analysis": "The image showcases a well-lit room featuring a large white wardrobe with a sleek design, providing ample storage. The study desk and ergonomic chair are positioned for comfort, while the large window allows natural light to flood the space. The overall minimalist aesthetic is enhanced by the light walls and modern furnishings, creating a serene environment suitable for work or relaxation.", "suggested_amenities": ["Air conditioning", "Wi-Fi"], "suggested_activities": ["Working", "Reading", "Relaxing"]}]}', '2026-04-26 00:34:56.301+00', '2026-06-24 15:31:44.469+00', '2026-06-09 03:00:11.972+00', true, '2026-04-26 00:35:02.665935+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'complete', false, NULL),
