	('257e0d25-ad4c-4015-91fe-16ddbfd0f94f', 'nt131781957', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-7-tp-ho-chi-minh/131781957.htm#px=sr-stickyad-[po-1][pl-top]', 'Charming Scenic Valley Retreat with Expansive Views', 'Nguyễn Văn Linh, Phường Tân Phú, Quận 7, Tp Hồ Chí Minh', 'nguyn vn linh phng tn ph qun 7 tp h ch minh', 'ho_chi_minh', 16000000, '16 triệu/tháng', '77 m²', 'Welcome to your charming retreat at Scenic Valley, where modern living meets serene comfort. This beautifully designed apartment features an open layout that invites natural light to dance across the spacious 77 m², creating a warm and inviting atmosphere. With two cozy bedrooms and two well-appointed bathrooms, this space is perfect for both relaxation and entertaining. Imagine sipping your morning coffee on the expansive balcony, enjoying the stunning views of the surrounding area. The full furnishings add a touch of elegance, while the thoughtful design ensures that every corner feels like home. Residents enjoy access to a stunning swimming pool and a state-of-the-art gym, making it easy to maintain an active lifestyle. Located in the vibrant Phú Mỹ Hưng area, you are just moments away from international schools, shopping centers, and the beautiful parks that define this community. Experience the perfect blend of comfort and convenience in this delightful apartment.', '{"Sleek modern lighting with elegant design elements","Culinary creativity hub with modern finishes","Sophisticated dining area for entertaining guests","Stylish minimalist bedroom design with smart storage","Elegant minimalist design with smart storage solutions"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Parking,Pool,Gym,Elevator,"Security Camera",Sofa,"Coffee Table","Area Rug","Ceiling Lights","Wall Lighting","Storage Unit","Air Conditioning Unit","Modern Lighting","Comfortable Seating",Refrigerator,"Kitchen Sink",Stove,Oven,Dishwasher,Cabinets,Countertops,"Kitchen Hood","Modern Kitchen Appliances","Granite Countertops","Dining Table",Chairs,Microwave,"Kitchen Cabinets",Hood,"Marble Countertops","Recessed Lighting",Wardrobe,Bed,Nightstand,Lighting,"Queen Bed",Dresser,Curtains,"Wood Flooring"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131781957/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131781957/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131781957/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131781957/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131781957/4.jpg}', 'Em Hằng', '091730 ***', NULL, '{"cozy": 5, "urban": 6, "colors": ["Neutral", "Cool", "Refined"], "modern": 8, "rustic": 1, "styles": ["Minimalist", "Modern", "Elegant"], "elegant": 8, "colorful": 2, "spacious": 6, "luxurious": 6, "activities": ["Entertaining guests", "Relaxing with family", "Cooking gourmet meals", "Hosting intimate dinner parties", "Dining"], "minimalist": 9, "natural_light": 5, "image_analyses": [{"amenities": ["Sofa", "Coffee Table", "Area Rug", "Ceiling Lights", "Wall Lighting", "Storage Unit", "Air Conditioning Unit"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 6, "modern": 8, "elegant": 9, "spacious": 8, "luxurious": 7, "minimalist": 9, "natural_light": 5}, "image_highlight": "Sleek modern lighting with elegant design elements", "detailed_analysis": "This living space features a sleek, modern aesthetic with a harmonious blend of neutral tones and elegant lighting. The spacious layout invites relaxation, with a plush sofa and stylish coffee table creating an inviting area for social gatherings. The glossy tile flooring enhances the brightness, while the unique ceiling lights add a touch of contemporary flair. Ample storage and a streamlined design contribute to a clutter-free environment, making it a stylish yet functional retreat.", "suggested_amenities": ["Modern Lighting", "Comfortable Seating"], "suggested_activities": ["Entertaining guests", "Relaxing with family"]}, {"amenities": ["Refrigerator", "Kitchen Sink", "Stove", "Oven", "Dishwasher", "Cabinets", "Countertops", "Kitchen Hood"], "image_index": 1, "vibe_scores": {"cozy": 3, "urban": 4, "modern": 8, "elegant": 8, "spacious": 6, "luxurious": 7, "minimalist": 9, "natural_light": 5}, "image_highlight": "Culinary creativity hub with modern finishes", "detailed_analysis": "This kitchen space radiates modern sophistication with its sleek cabinets and elegant granite countertops. The open layout allows for seamless cooking and entertaining, while the high-end appliances promise efficiency and style. The clean lines and minimalist design create a calming atmosphere, making it an ideal setting for culinary creativity. The natural light enhances the inviting feel, encouraging both casual meals and gourmet cooking experiences. The integration of smart storage solutions ensures an organized space, elevating the cooking experience.", "suggested_amenities": ["Modern Kitchen Appliances", "Granite Countertops"], "suggested_activities": ["Cooking gourmet meals", "Hosting intimate dinner parties"]}, {"amenities": ["Dining Table", "Chairs", "Refrigerator", "Stove", "Microwave", "Kitchen Cabinets", "Hood", "Marble Countertops", "Air Conditioning Unit", "Recessed Lighting"], "image_index": 2, "vibe_scores": {"cozy": 5, "urban": 6, "modern": 8, "elegant": 8, "spacious": 6, "luxurious": 7, "minimalist": 9, "natural_light": 7}, "image_highlight": "Sophisticated dining area for entertaining guests", "detailed_analysis": "This sleek kitchen-dining area boasts a sophisticated design with a modern dining table surrounded by stylish chairs, perfect for hosting dinner parties or family meals. The elegant marble countertops add an element of luxury, while the well-integrated appliances create a seamless cooking experience. Recessed lighting enhances the ambiance, spotlighting the contemporary fixtures and cabinetry. The open layout encourages movement and social interaction, making it both functional and inviting.", "suggested_amenities": ["Dining Table", "Marble Countertops"], "suggested_activities": ["Dining", "Entertaining"]}, {"amenities": ["Air Conditioning", "Wardrobe", "Bed", "Nightstand", "Lighting"], "image_index": 3, "vibe_scores": {"cozy": 4, "urban": 7, "modern": 8, "elegant": 6, "spacious": 6, "luxurious": 5, "minimalist": 9, "natural_light": 3}, "image_highlight": "Stylish minimalist bedroom design with smart storage", "detailed_analysis": "This modern bedroom embodies a stylish minimalist design, characterized by clean lines and a calming color palette. The integrated wardrobe offers ample storage, enhancing functionality without sacrificing aesthetics. Soft lighting and a sleek nightstand invite relaxation, creating an ideal environment for rest or reading. The spacious layout promotes a sense of tranquility while maximizing usability, making it a perfect retreat for urban dwellers seeking peace amidst a bustling lifestyle.", "suggested_amenities": ["Wardrobe", "Nightstand"], "suggested_activities": ["Resting", "Reading"]}, {"amenities": ["Queen Bed", "Nightstand", "Dresser", "Curtains", "Recessed Lighting", "Wood Flooring"], "image_index": 4, "vibe_scores": {"cozy": 5, "urban": 5, "modern": 8, "elegant": 7, "spacious": 4, "luxurious": 6, "minimalist": 9, "natural_light": 3}, "image_highlight": "Elegant minimalist design with smart storage solutions", "detailed_analysis": "This minimalist bedroom features a clean, modern aesthetic with a low-profile queen bed and integrated storage solutions, enhancing the sense of space. The wood flooring adds warmth, while the elegant recessed lighting and rich curtains create a cozy atmosphere. The light color palette promotes tranquility, making it an ideal sanctuary for relaxation or restful nights. The streamlined design not only maximizes functionality but also provides an inviting backdrop for personal expression.", "suggested_amenities": ["Nightstand", "Dresser"], "suggested_activities": ["Relaxing", "Reading"]}]}', '2026-04-13 01:05:44.397+00', '2026-06-24 15:31:44.469+00', '2026-06-19 03:00:14.148+00', true, '2026-04-13 01:05:47.152623+00', '2026-06-19 03:00:14.18598+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
