	('a436da82-ec67-4a48-8617-6ab8c7341bd6', 'nt130499645', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-thanh-pho-thu-duc-tp-ho-chi-minh/130499645.htm#px=sr-stickyad-[po-1][pl-top]', 'FOR RENT RICCA APARTMENT, DISTRICT 9 - 1 BEDROOM + 1 DESIGN, BASIC FURNITURE, CURTAINS', 'D7, Phường Phú Hữu (Quận 9 cũ), Thành phố Thủ Đức, Tp Hồ Chí Minh', 'd7 phng ph hu qun 9 c thnh ph th c tp h ch minh', 'ho_chi_minh', 6000000, '6 triệu/tháng', '56 m²', 'Discover this charming 1-bedroom plus apartment for rent at Ricca, located on Go Cat Street, Phu Huu Ward, District 9 (now Thành phố Thủ Đức). This unit offers a comfortable living space of 56 m² and is available for 6 million VND per month. The apartment comes with basic developer-provided furniture, including kitchen cabinets (upper and lower), and curtains, ensuring a ready-to-move-in experience. Residents will enjoy a range of complimentary amenities, such as an indoor swimming pool, a multi-functional gym, a children''s play area, and a pedestrian street. The Ricca project, delivered in 2021 by Tân Phú, is a well-regarded development in the area. This is an excellent opportunity for individuals or small families seeking a modern and convenient lifestyle in Thành phố Thủ Đức. Contact us today to schedule a viewing!', '{"Floor-to-ceiling windows for breathtaking views","Open-concept living space with expansive views","Abundant natural light streaming in","Sleek minimalist kitchen for culinary inspiration","Inviting balcony with expansive urban views"}', '{"Chung cư (Apartment building)","Sổ hồng riêng (Private pink book/legal document)","1 phòng ngủ (1 bedroom)","1 phòng vệ sinh (1 bathroom)","Nội thất CĐT (Developer''s basic furniture)","Tủ bếp Trên-dưới (Upper and lower kitchen cabinets)","Rèm (Curtains)","Hồ bơi trong nhà (Indoor swimming pool)","Phòng Gym đa chức năng (Multi-functional gym)","Khu vui chơi giải trí cho trẻ em (Children''s entertainment area)","Phố đi bộ (Pedestrian street)","Large Windows",Balcony,"Air Conditioning","WiFi Router","Modern Lighting","Floor-to-ceiling windows","Natural light","Spacious layout","Large Window","Wooden Flooring","Heating System","Kitchen Cabinets","Kitchen Sink",Countertop,Stove,"Open floor plan","Tile flooring"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130499645/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130499645/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130499645/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130499645/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130499645/4.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130499645/5.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130499645/6.jpg}', 'Trần Chung', '094808 ***', NULL, '{"cozy": 4, "urban": 6, "colors": ["Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 1, "styles": ["Minimalist", "Modern", "Spacious"], "elegant": 6, "colorful": 2, "spacious": 7, "luxurious": 5, "activities": ["Relaxing", "Working", "Entertaining guests", "Relaxing with a view", "Reading"], "minimalist": 9, "natural_light": 7, "image_analyses": [{"amenities": ["Large Windows", "Balcony", "Air Conditioning", "WiFi Router", "Modern Lighting"], "image_index": 0, "vibe_scores": {"cozy": 4, "urban": 6, "modern": 8, "elegant": 7, "spacious": 7, "luxurious": 5, "minimalist": 9, "natural_light": 10}, "image_highlight": "Floor-to-ceiling windows for breathtaking views", "detailed_analysis": "This space features expansive floor-to-ceiling windows that invite abundant natural light, creating a vibrant and uplifting atmosphere. The minimalist design accentuates the spaciousness, while the sleek tiles add a modern touch. The balcony offers a perfect spot for enjoying panoramic views and outdoor relaxation. The atmosphere is both contemporary and serene, ideal for unwinding or engaging in productive work. This room''s flow promotes easy movement, making it a versatile space for various activities.", "suggested_amenities": ["Large Windows", "Balcony"], "suggested_activities": ["Relaxing", "Working"]}, {"amenities": ["Floor-to-ceiling windows", "Balcony", "Natural light", "Spacious layout"], "image_index": 1, "vibe_scores": {"cozy": 4, "urban": 6, "modern": 8, "elegant": 6, "spacious": 7, "luxurious": 5, "minimalist": 9, "natural_light": 9}, "image_highlight": "Open-concept living space with expansive views", "detailed_analysis": "This open-concept living space features floor-to-ceiling windows that flood the room with natural light, creating an airy and inviting atmosphere. The minimalist design emphasizes spaciousness, enhancing the sense of freedom and potential for personalization. With a balcony that offers expansive views, this area becomes an ideal backdrop for entertaining or unwinding. The modern aesthetic is further complemented by sleek flooring and a neutral color palette, making it a versatile canvas for any renter''s style.", "suggested_amenities": ["Floor-to-ceiling windows", "Balcony"], "suggested_activities": ["Entertaining guests", "Relaxing with a view"]}, {"amenities": ["Large Window", "Wooden Flooring", "Heating System"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 3, "modern": 8, "elegant": 5, "spacious": 5, "luxurious": 4, "minimalist": 9, "natural_light": 7}, "image_highlight": "Abundant natural light streaming in", "detailed_analysis": "This minimalist space features warm wooden flooring that creates a welcoming atmosphere. The large window allows for abundant natural light, enhancing the room''s vibrancy and creating an energizing environment. The clean lines and neutral color palette contribute to a serene ambiance, perfect for focused activities or quiet reflection. The layout is thoughtfully designed to maximize comfort and flow, making it an ideal setting for personal time or cozy gatherings.", "suggested_amenities": ["Large Window", "Heating System"], "suggested_activities": ["Reading", "Meditation"]}, {"amenities": ["Kitchen Cabinets", "Kitchen Sink", "Countertop", "Stove"], "image_index": 3, "vibe_scores": {"cozy": 4, "urban": 6, "modern": 8, "elegant": 7, "spacious": 7, "luxurious": 6, "minimalist": 9, "natural_light": 5}, "image_highlight": "Sleek minimalist kitchen for culinary inspiration", "detailed_analysis": "This modern kitchen showcases a sleek, minimalist design with pristine white cabinetry and a dark countertop that creates a striking contrast. The layout promotes functionality, making it ideal for meal preparation and culinary creativity. Ample storage in the cabinets ensures everything is neatly organized, while the understated decor contributes to a clean and inviting atmosphere. The space is well-lit, enhancing the mood for cooking and entertaining, making it a perfect culinary hub for aspiring chefs.", "suggested_amenities": ["Kitchen Cabinets", "Countertop"], "suggested_activities": ["Cooking", "Meal prep"]}, {"amenities": ["Floor-to-ceiling windows", "Balcony", "Natural light", "Open floor plan", "Tile flooring"], "image_index": 4, "vibe_scores": {"cozy": 4, "urban": 8, "modern": 8, "elegant": 6, "spacious": 7, "luxurious": 5, "minimalist": 9, "natural_light": 6}, "image_highlight": "Inviting balcony with expansive urban views", "detailed_analysis": "This elegantly designed space features a seamless flow from the main living area to the balcony, creating an inviting atmosphere ideal for relaxation and enjoyment. The floor-to-ceiling windows flood the room with natural light, enhancing the minimalist aesthetic and providing stunning urban views. The open floor plan allows for versatility in furniture arrangement, making it perfect for both casual living and entertaining. The clean lines and neutral palette promote tranquility, making this space a serene retreat in the heart of the city.", "suggested_amenities": ["Balcony", "Floor-to-ceiling windows"], "suggested_activities": ["Relaxing with a book", "Enjoying morning coffee"]}]}', '2026-04-07 14:01:43.37+00', '2026-06-24 15:31:44.469+00', '2026-06-10 03:00:05.896+00', true, '2026-04-07 14:01:43.366199+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('37e828bc-2ab2-4e2a-9203-126e13b7ebbd', 'nt131513243', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-4-tp-ho-chi-minh/131513243.htm', 'Luxury 3-Bedroom Apartment for Rent in Copac Contrexim, District 4, Ho Chi Minh City', '12 Ton Dan, Ward 13, District 4, Ho Chi Minh City', '12 ton dan ward 13 district 4 ho chi minh city', 'ho_chi_minh', 22000000, '22 million/month', '120 m²', 'This stunning 3-bedroom apartment located in the prestigious Copac Contrexim complex in District 4, Ho Chi Minh City, offers a spacious living area of 120 m². The apartment features high-end furnishings and is designed to provide a luxurious living experience. With three well-appointed bedrooms and two bathrooms, it is perfect for families or professionals seeking comfort and style. The apartment is situated in a vibrant neighborhood, close to amenities and public transport, making it an ideal choice for urban living. The rental price is 22 million VND per month, and the owner is open to negotiations. Don''t miss the opportunity to live in this beautiful apartment that is ready for you to move in immediately.', '{"Bright, open living area with modern finishes","Spa-inspired walk-in shower with modern fixtures","Dedicated workspace for productivity and focus","Dedicated workspace with ample storage options","Versatile space for social gatherings or relaxation"}', '{"High-end furnishings","Private ownership certificate","Air Conditioning","Natural Light","Modern Fixtures","Storage Cabinets","Lighting Fixtures"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131513243/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131513243/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131513243/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131513243/3.jpg,https://