	('2e734cd1-e58d-4529-92df-56cee58b9c74', 'pr45371587', 'batdongsan', 'https://batdongsan.com.vn/cho-thue-can-ho-chung-cu-vinhome-grand-park-quan-9/cho-thue-2-290-can-ho-vin-q9-day-du-tu-stu-1-2-3pn-gan-vincom-gan-vinschool-co-gym-free-o-lien-pr45371587', '2,290 Apartments for Rent in Vin Q9, Fully Equipped from Studio to 1-2-3 Bedrooms, Near Vincom, Vinschool, Free Gym, Ready to Move In', 'Vinhomes Grand Park, Quận 9, Hồ Chí Minh', 'vinhomes grand park qun 9 h ch minh', 'ho_chi_minh', 6000000, '6 triệu/tháng', '69', 'Nhat Thanh Land Co., Ltd specializes in renting apartments at Vinhomes Grand Park Q9. We provide a price list for various apartment types currently available for rent to our valued customers. These apartments are fully equipped, ranging from studio units to 1, 2, and 3-bedroom configurations. They are conveniently located near Vincom and Vinschool, and residents can enjoy a free gym. All units are ready for immediate occupancy.', '{"Sleek modern kitchen with integrated appliances","Culinary creativity hub with integrated appliances","Breathtaking city view from expansive windows","Inviting lounge area with chic decor","Bright and airy entertainment space with smart technology"}', '{Gym,Refrigerator,Stove,Microwave,"Kitchen Sink",Television,"Kitchen Cabinets","Dining Table",Chairs,"Integrated Kitchen Appliances","Dining Area",Oven,Dishwasher,Sofa,"Lighting Fixtures","Wall Artwork","Integrated Appliances","Large Windows",Balcony,"Outdoor Pool",Garden,"City View","Large Screen TV","Coffee Table","Indoor Plant","Lighting Fixture","Kitchen Island","Storage Cabinets","Smart TV","Large windows","Air Conditioning"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45371587/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45371587/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45371587/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45371587/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45371587/4.png}', 'Công ty TNHH Nhất Thanh Land', '0938 123 ***', NULL, '{"cozy": 5, "urban": 8, "colors": ["Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 2, "styles": ["Modern", "Luxurious", "Elegant"], "elegant": 8, "colorful": 4, "spacious": 7, "luxurious": 8, "activities": ["Cooking gourmet meals", "Entertaining guests", "Cooking", "Dining", "Relaxing"], "minimalist": 7, "natural_light": 8, "image_analyses": [{"amenities": ["Refrigerator", "Stove", "Microwave", "Kitchen Sink", "Television", "Kitchen Cabinets", "Dining Table", "Chairs"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 8, "modern": 8, "elegant": 7, "spacious": 7, "luxurious": 7, "minimalist": 9, "natural_light": 6}, "image_highlight": "Sleek modern kitchen with integrated appliances", "detailed_analysis": "This sleek modern kitchen seamlessly integrates functionality and style, boasting polished cabinets and high-end appliances. The open layout fosters an inviting atmosphere, ideal for cooking and entertaining. Natural light pours in from the windows, enhancing the airy feel. The contemporary dining area complements the kitchen, making it a perfect spot for meals or casual gatherings. Unique elements like the aquarium add a touch of tranquility, creating a vibrant yet soothing culinary experience.", "suggested_amenities": ["Integrated Kitchen Appliances", "Dining Area"], "suggested_activities": ["Cooking gourmet meals", "Entertaining guests"]}, {"amenities": ["Refrigerator", "Oven", "Stove", "Dishwasher", "Dining Table", "Sofa", "Lighting Fixtures", "Wall Artwork"], "image_index": 1, "vibe_scores": {"cozy": 4, "urban": 7, "modern": 8, "elegant": 8, "spacious": 6, "luxurious": 7, "minimalist": 9, "natural_light": 5}, "image_highlight": "Culinary creativity hub with integrated appliances", "detailed_analysis": "This contemporary kitchen and living area seamlessly blend functionality and style. The sleek cabinetry and integrated appliances create a cohesive culinary space, while the elegant dining table invites shared meals and gatherings. Warm lighting enhances the modern aesthetic, contributing to a welcoming atmosphere. The layout promotes interaction between cooking and dining, making it perfect for entertaining. Overall, this space embodies a chic, urban lifestyle with its minimalist design and premium finishes.", "suggested_amenities": ["Integrated Appliances", "Dining Table"], "suggested_activities": ["Cooking", "Dining"]}, {"amenities": ["Large Windows", "Balcony", "Outdoor Pool", "Garden", "City View"], "image_index": 2, "vibe_scores": {"cozy": 4, "urban": 8, "modern": 8, "elegant": 6, "spacious": 7, "luxurious": 9, "minimalist": 5, "natural_light": 9}, "image_highlight": "Breathtaking city view from expansive windows", "detailed_analysis": "This image captures a stunning view from expansive windows, creating an inviting atmosphere that feels both urban and serene. The large windows allow natural light to flood the space, enhancing the sense of openness and connection to the outdoors. The vibrant greenery of the outdoor pool area contrasts beautifully with the city skyline, promoting a sense of tranquility. The overall design appears sleek and modern, with a layout that encourages relaxation and enjoyment of the picturesque view, making it an ideal space for unwinding after a busy day.", "suggested_amenities": ["Large Windows", "Outdoor Pool"], "suggested_activities": ["Relaxing", "Enjoying the view"]}, {"amenities": ["Large Screen TV", "Sofa", "Coffee Table", "Indoor Plant", "Lighting Fixture", "Kitchen Island", "Storage Cabinets"], "image_index": 3, "vibe_scores": {"cozy": 7, "urban": 7, "modern": 9, "elegant": 9, "spacious": 6, "luxurious": 8, "minimalist": 9, "natural_light": 8}, "image_highlight": "Inviting lounge area with chic decor", "detailed_analysis": "This stylish lounge area radiates warmth and sophistication with its chic decor and inviting sofa, perfect for social gatherings or quiet relaxation. The large screen TV serves as a focal point for entertainment, while the modern lighting fixtures enhance the ambiance. An indoor plant adds a touch of greenery, creating a refreshing atmosphere. The layout encourages seamless interaction, making it an ideal space for both entertaining guests and enjoying personal downtime in a minimalist yet luxurious environment.", "suggested_amenities": ["Large Screen TV", "Sofa"], "suggested_activities": ["Entertaining guests", "Relaxing with a book"]}, {"amenities": ["Smart TV", "Large windows", "Air Conditioning", "Sofa", "Coffee Table"], "image_index": 4, "vibe_scores": {"cozy": 6, "urban": 9, "modern": 8, "elegant": 9, "spacious": 7, "luxurious": 9, "minimalist": 4, "natural_light": 10}, "image_highlight": "Bright and airy entertainment space with smart technology", "detailed_analysis": "This vibrant entertainment space boasts large windows that flood the room with natural light, creating an inviting and airy atmosphere. The modern decor is complemented by comfortable seating, including a stylish sofa, perfect for gatherings. With a smart TV and ample space for socializing, this area transforms into a lively hub for entertainment. The sleek design and sophisticated color palette add a touch of elegance, making it an ideal backdrop for memorable moments with friends and family.", "suggested_amenities": ["Smart TV", "Sofa"], "suggested_activities": ["Hosting movie nights", "Relaxing with friends"]}]}', '2026-04-07 13:00:51.792+00', '2026-06-24 15:31:44.469+00', '2026-06-17 03:00:07.03+00', true, '2026-04-07 13:00:51.895266+00', '2026-06-17 03:00:07.028492+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
