	('4a5457e2-0888-41b2-b647-81b93f81b6aa', 'nt131316680', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-go-vap-tp-ho-chi-minh/131316680.htm#px=sr-stickyad-[po-1][pl-top]', 'Charming Riverside Retreat with Expansive Balcony Views', '616, Đường Nguyễn Oanh, Phường 17, Quận Gò Vấp, Tp Hồ Chí Minh', '616 ng nguyn oanh phng 17 qun g vp tp h ch minh', 'ho_chi_minh', 3600000, '3,6 triệu/tháng', '45 m²', 'Step into a charming riverside retreat that offers a unique blend of comfort and style. This spacious 1-bedroom apartment features an expansive 5-meter balcony that invites you to unwind while soaking in stunning views of the river and city skyline. The open layout creates a bright and airy atmosphere, perfect for morning coffee rituals or hosting friends for an evening of relaxation. With premium furnishings and a design that emphasizes natural light, this space feels like a luxurious getaway right at home. The modern amenities, including a shared washing machine and dryer, ensure convenience without compromising on style. Ideal for young professionals or anyone seeking a tranquil yet vibrant living experience in the heart of Quận Gò Vấp.', '{"Bright and airy open-concept living space","Functional workspace with natural light","Chic dining nook with stylish decor accents","Natural light-filled sanctuary for restful sleep"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine","Security Camera","Kitchen Sink",Refrigerator,"Dining Table",Chairs,Bed,Wardrobe,"Wall Art","Large Windows",Desk,Chair,Bookshelf,Plants,"Wall Shelves","Wall-mounted Shelves","Comfortable Bed"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131316680/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131316680/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131316680/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131316680/3.jpg}', 'Phòng trọ giá tốt', '091311 ***', NULL, '{"cozy": 7, "urban": 5, "colors": ["Warm", "Neutral", "Cool", "Bright"], "modern": 7, "rustic": 2, "styles": ["Minimalist", "Modern", "Cozy"], "elegant": 5, "colorful": 5, "spacious": 6, "luxurious": 5, "activities": ["Relaxing", "Entertaining", "Working", "Reading", "Cooking"], "minimalist": 8, "natural_light": 8, "image_analyses": [{"amenities": ["Kitchen Sink", "Refrigerator", "Dining Table", "Chairs", "Bed", "Wardrobe", "Wall Art", "Large Windows"], "image_index": 0, "vibe_scores": {"cozy": 7, "urban": 6, "modern": 8, "elegant": 5, "spacious": 7, "luxurious": 5, "minimalist": 9, "natural_light": 8}, "image_highlight": "Bright and airy open-concept living space", "detailed_analysis": "This bright and airy space features an open-concept layout that seamlessly combines living, dining, and sleeping areas. The modern kitchen includes a sleek sink and refrigerator, while the wooden dining table offers a cozy spot for meals. Large windows flood the room with natural light, enhancing the tranquil atmosphere. Decor elements such as wall art and a carefully arranged plant add touches of personality. The wooden textures and soft color palette create a soothing environment, making it ideal for relaxation or social gatherings.", "suggested_amenities": ["Dining Table", "Large Windows"], "suggested_activities": ["Relaxing", "Entertaining"]}, {"amenities": ["Desk", "Chair", "Bookshelf", "Refrigerator", "Bed", "Wall Art", "Plants"], "image_index": 1, "vibe_scores": {"cozy": 6, "urban": 5, "modern": 7, "elegant": 5, "spacious": 5, "luxurious": 4, "minimalist": 8, "natural_light": 8}, "image_highlight": "Functional workspace with natural light", "detailed_analysis": "This space presents a bright and inviting atmosphere, enhanced by natural light streaming through multiple windows. The minimalist design features a cozy bed adorned with floral bedding, complemented by a practical desk area perfect for work or study. A small bookshelf adds both functionality and charm, while potted plants contribute a touch of nature. The layout promotes a smooth flow, making it easy to transition from relaxation to productivity. Overall, this room offers a harmonious balance of comfort and practicality, ideal for modern living.", "suggested_amenities": ["Desk", "Bookshelf"], "suggested_activities": ["Working", "Reading"]}, {"amenities": ["Dining Table", "Kitchen Sink", "Wall Shelves"], "image_index": 2, "vibe_scores": {"cozy": 7, "urban": 5, "modern": 6, "elegant": 4, "spacious": 5, "luxurious": 4, "minimalist": 8, "natural_light": 6}, "image_highlight": "Chic dining nook with stylish decor accents", "detailed_analysis": "This image showcases a chic dining nook, perfectly designed for intimate meals or casual gatherings. The light wood dining table paired with matching chairs invites a sense of warmth and comfort. The sleek kitchen sink and herringbone backsplash add a modern touch, enhancing the overall aesthetic. Large windows allow natural light to flood the space, creating an uplifting atmosphere. Wall shelves provide practical storage while allowing for decorative touches. The minimalist design promotes easy organization and uncluttered living, making it a welcoming hub for culinary creativity and social interactions.", "suggested_amenities": ["Dining Table", "Kitchen Sink"], "suggested_activities": ["Entertaining", "Cooking"]}, {"amenities": ["Refrigerator", "Bed", "Wardrobe", "Wall-mounted Shelves"], "image_index": 3, "vibe_scores": {"cozy": 6, "urban": 5, "modern": 7, "elegant": 5, "spacious": 6, "luxurious": 5, "minimalist": 8, "natural_light": 9}, "image_highlight": "Natural light-filled sanctuary for restful sleep", "detailed_analysis": "This serene bedroom blends minimalism with modern comfort, featuring a spacious layout illuminated by abundant natural light. The soothing color palette, highlighted by floral bedding, creates a calming atmosphere ideal for unwinding. The functional wardrobe and wall-mounted shelves provide ample storage, while the layout encourages relaxation and restful nights. A seamless flow from the sleeping area to the outdoor views enhances the overall tranquility of the space, making it a rejuvenating retreat.", "suggested_amenities": ["Comfortable Bed", "Wardrobe"], "suggested_activities": ["Relaxing"]}]}', '2026-04-20 01:32:15.702+00', '2026-06-24 15:31:44.469+00', '2026-06-11 03:00:08.837+00', true, '2026-04-20 01:32:21.05961+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
