	('90a08443-d2ad-4d9a-9b07-351b84109428', 'nt131318899', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-4-tp-ho-chi-minh/131318899.htm', 'Beautiful Riva Park Apartment with River View in District 4', '504 Nguyen Tat Thanh, Ward 18, District 4, Ho Chi Minh City', '504 nguyen tat thanh ward 18 district 4 ho chi minh city', 'ho_chi_minh', 16000000, '16 million/month', '80 m²', 'This stunning apartment in Riva Park, District 4, offers a spacious 80 m² layout featuring 2 bedrooms and 2 bathrooms. Located on the 15th floor, it boasts breathtaking views of the river and direct sightlines to District 1, ensuring a refreshing breeze year-round. The apartment is beautifully designed with a bright and airy atmosphere, perfect for families or professionals seeking comfort and convenience. Residents can enjoy a range of amenities including a swimming pool, gym, and 24/7 security. With easy access to the city center, this apartment is ideal for those looking to experience the vibrant lifestyle of Ho Chi Minh City.', '{"Breathtaking city skyline view at night","Inviting personal sanctuary with soft lighting","Stunning sunset views over the urban landscape","Culinary creativity hub with modern finishes","Efficient storage solutions for organized living"}', '{"Fully furnished","Air Conditioning",Gym,"Swimming Pool",Supermarket,"24/7 Security"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131318899/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131318899/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131318899/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131318899/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131318899/4.jpg}', 'Uyên Nguyễn Huỳnh Tú', NULL, 'Modern, Natural_light', '{"style": "Modern", "colors": ["Neutral", "Bright"], "styles": ["Modern"], "amenities": ["Fully furnished", "Air Conditioning", "Gym", "Swimming Pool", "Supermarket", "24/7 Security"], "activities": ["Relaxing", "Entertaining"], "vibe_scores": {"cozy": 7, "urban": 8, "modern": 9, "elegant": 7, "spacious": 8, "luxurious": 6, "minimalist": 8, "natural_light": 9}, "image_analyses": [{"image_index": 0, "image_highlight": "Breathtaking city skyline view at night", "suggested_amenities": ["Large Windows", "Balcony"]}, {"image_index": 1, "image_highlight": "Inviting personal sanctuary with soft lighting", "suggested_amenities": ["Bed", "Bookshelf"]}, {"image_index": 2, "image_highlight": "Stunning sunset views over the urban landscape", "suggested_amenities": ["Large Windows", "City Skyline View"]}, {"image_index": 3, "image_highlight": "Culinary creativity hub with modern finishes", "suggested_amenities": ["Modern Kitchen Appliances", "Granite Countertops"]}, {"image_index": 4, "image_highlight": "Efficient storage solutions for organized living", "suggested_amenities": ["Storage Cabinet", "Decorative Shelving"]}]}', '2026-03-20 10:32:07.598+00', '2026-06-24 15:31:44.469+00', '2026-06-21 03:00:15.691+00', true, '2026-03-20 10:32:07.734568+00', '2026-06-21 03:00:15.724022+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('a0ddfb77-c516-49eb-936f-3b425b7bde14', 'nt131968972', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-3-tp-ho-chi-minh/131968972.htm', 'Charming Fully Furnished 1-Bedroom Retreat in the Heart of District 3', 'Đường Lý Chính Thắng, Phường Võ Thị Sáu, Quận 3, Tp Hồ Chí Minh', 'ng l chnh thng phng v th su qun 3 tp h ch minh', 'ho_chi_minh', 6500000, '6,5 triệu/tháng', '45 m²', 'Step into a charming sanctuary nestled in the vibrant heart of District 3, where modern living meets comfort. This fully furnished 1-bedroom apartment is designed to envelop you in warmth and style. The open layout invites natural light to dance across the sleek surfaces, highlighting the tasteful decor and premium furnishings. Imagine sipping your morning coffee on a cozy sofa, basking in the sunlight that filters through the large windows. The space is perfect for remote work, with a dedicated area that inspires productivity while maintaining a relaxed atmosphere. The kitchen, equipped with modern appliances, is ideal for whipping up meals or entertaining friends. With a focus on high-quality finishes and thoughtful design, this apartment offers a serene retreat from the bustling city life, making it a perfect home for those seeking both convenience and tranquility.', '{"Spacious layout with two beds and a TV unit","Stylish round table with a city view","Compact kitchen area with modern appliances","Elegant wooden accents and large window","Minimalist kitchen design with sleek cabinetry"}', '{"Air Conditioning","Washing Machine","Security Camera",Elevator,"High-Speed Internet"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131968972/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131968972/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131968972/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/obje