	('90c4be34-1b3b-4b4f-93c7-640984402b5b', 'nt131665383', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-hai-ba-trung-ha-noi/131665383.htm', 'Fully Furnished 1-Bedroom Apartment for Rent in Alley 61 Lac Trung, Hai Ba Trung - Move In Immediately!', '23 ngõ 61 Lạc Trung, Phường Vĩnh Tuy, Quận Hai Bà Trưng, Hà Nội', '23 ng 61 lc trung phng vnh tuy qun hai b trng h ni', 'hanoi', 6500000, '6,5 triệu/tháng', '35 m²', 'This charming 1-bedroom serviced apartment, located in a quiet and secure alley at 61 Lac Trung, Hai Ba Trung, is available for immediate occupancy. Spanning 35 m², this apartment comes fully furnished with all the essentials, allowing you to simply bring your suitcase and settle in. The interior boasts a comfortable bed with mattress, a wardrobe, a sofa, a dressing table, air conditioning, a water heater, a refrigerator, and an induction cooker. The building prioritizes safety with a fully equipped fire protection system. Residents will appreciate the peaceful environment and good security in the area. Additional costs include electricity at 4k/kWh, water at 100k/person, and a service fee of 200k/person covering Wi-Fi and laundry (washing and drying). This is an excellent opportunity for individuals or couples seeking a convenient and comfortable living space in a desirable Hanoi district.', '{"Abundant natural light from large windows","Culinary creativity hub with modern appliances","Open layout for seamless living and entertaining"}', '{"Air Conditioning","Water Heater",Refrigerator,"Induction Cooker",Bed,Mattress,Wardrobe,Sofa,"Dressing Table","Fire Protection System",WiFi,"Washing Machine","Drying Machine"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131665383/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131665383/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131665383/2.jpg}', 'Hoàng Thủ Thiêm', '096300***', NULL, '{"colors": [], "styles": [], "activities": [], "image_analyses": [{"image_index": 0, "image_highlight": "Abundant natural light from large windows", "suggested_amenities": ["Air Conditioning", "Large Windows"]}, {"image_index": 1, "image_highlight": "Culinary creativity hub with modern appliances", "suggested_amenities": ["Kitchen Appliances", "Dining Table"]}, {"image_index": 2, "image_highlight": "Open layout for seamless living and entertaining", "suggested_amenities": ["Sofa", "Coffee Table"]}]}', '2026-04-07 16:02:40.953+00', '2026-06-24 15:31:44.469+00', '2026-06-12 03:00:05.153+00', true, '2026-04-07 16:02:41.026192+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('5967a588-771f-4c77-ab8a-bd0dbe0602bb', 'nt131358000', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-3-tp-ho-chi-minh/131358000.htm', 'Luxury Studio Apartment in the Heart of District 3, Ho Chi Minh City', 'Hai Ba Trung Street, Vo Thi Sau Ward, District 3, Ho Chi Minh City', 'hai ba trung street vo thi sau ward district 3 ho chi minh city', 'ho_chi_minh', 7500000, '7.5 triệu/tháng', '35 m²', 'This luxurious studio apartment is located in the vibrant heart of District 3, Ho Chi Minh City, just a stone''s throw away from the scenic Hoang Sa riverbank. The apartment boasts a modern design with a spacious and airy layout, ensuring a comfortable living experience. It comes fully furnished, allowing you to move in immediately without any hassle. The studio features a private setup, providing a cozy and intimate atmosphere perfect for relaxation. With its prime location, you''ll have easy access to local amenities, dining options, and entertainment venues. Whether you''re a busy professional or a student, this apartment offers the ideal blend of comfort and convenience.', '{"Bright natural light flooding the bedroom space","Culinary creativity hub with modern finishes","Seamless indoor-outdoor living with balcony","Seamless indoor-outdoor connection with balcony","Charming open-plan layout with rustic brick accent"}', '{"Fully Furnished","Air Conditioning",WiFi}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131358000/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131358000/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131358000/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131358000/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131358000/4.jpg}', 'Tien Hoang', NULL,