	('b962786e-e865-4169-a576-e1e86c140e6e', 'nt131948246', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-tan-binh-tp-ho-chi-minh/131948246.htm', 'Bright and Airy 2-Bedroom Apartment in Vibrant Tân Bình', 'Đường Hoàng Bật Đạt, Phường 15, Quận Tân Bình, Tp Hồ Chí Minh', 'ng hong bt t phng 15 qun tn bnh tp h ch minh', 'ho_chi_minh', 8500000, '8,5 triệu/tháng', '70 m²', 'Step into this bright and airy 2-bedroom apartment located in the lively district of Tân Bình. With a generous 70 m² of space, this home is designed for comfort and ease, featuring two well-appointed bedrooms and two bathrooms, making it perfect for small families or professionals seeking a serene retreat. The open layout allows for natural light to flood the living areas, creating a warm and inviting atmosphere. The modern decor combines soft neutral tones with vibrant accents, providing a fresh and stylish backdrop for your daily life. Imagine sipping your morning coffee on a sunny day or hosting friends in the spacious living area, where the layout encourages effortless flow. Equipped with two air conditioning units, you can enjoy a cool and comfortable environment year-round. This apartment is not just a place to live; it''s a lifestyle choice that embodies convenience and comfort in one of the city''s most desirable neighborhoods.', '{"large window allowing abundant natural light","sleek white tiles with subtle gray veining","built-in wooden wardrobe with clean lines","open doorway leading to a small balcony","freestanding bathtub with sleek modern design"}', '{"Air Conditioning",WiFi}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131948246/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131948246/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131948246/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131948246/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131948246/4.jpg}', 'Hà Mi', '093594***', NULL, '{"cozy": 5, "urban": 5, "colors": [], "modern": 8, "rustic": 1, "styles": [], "elegant": 7, "colorful": 2, "spacious": 6, "amenities": ["large window", "smooth tiled flooring", "recessed lighting", "kitchenette", "multiple doorways", "built-in wardrobe", "sleek tiles", "white tiles", "bathtub", "toilet", "sink", "shower", "mirror"], "luxurious": 6, "activities": [], "minimalist": 9, "natural_light": 7, "image_analyses": [{"cozy": 4, "urban": 5, "modern": 8, "rustic": 1, "elegant": 7, "colorful": 2, "spacious": 7, "amenities": ["large window", "smooth tiled flooring", "recessed lighting"], "luxurious": 6, "minimalist": 9, "image_index": 0, "natural_light": 8, "image_highlight": "large window allowing abundant natural light", "detailed_analysis": "The image showcases a bright room with a large window that allows ample natural light to fill the space. The walls are painted white, enhancing the modern and minimalist aesthetic. The smooth, glossy tiled flooring reflects the light, creating a sense of openness. Recessed lighting fixtures in the ceiling contribute to the contemporary feel. The overall layout appears versatile, suitable for various activities such as working or relaxing.", "suggested_amenities": ["Balcony", "Air Conditioning"], "suggested_activities": ["Working", "Reading", "Relaxing"]}, {"cozy": 5, "urban": 7, "modern": 8, "rustic": 1, "elegant": 6, "colorful": 2, "spacious": 7, "amenities": ["kitchenette", "recessed lighting", "multiple doorways"], "luxurious": 6, "minimalist": 9, "image_index": 1, "natural_light": 8, "image_highlight": "sleek white tiles with subtle gray veining", "detailed_analysis": "The image showcases a minimalist layout with sleek white tiles featuring subtle gray veining. The recessed lighting adds a modern touch, creating a bright and inviting atmosphere. The kitchenette is visible in the background, suggesting functionality for cooking. Multiple doorways indicate access to other rooms, enhancing the apartment''s layout. Overall, the space feels open and airy, ideal for various activities.", "suggested_amenities": ["Dishwasher", "Air Conditioning"], "suggested_activities": ["Working", "Relaxing"]}, {"cozy": 5, "urban": 4, "modern": 8, "rustic": 1, "elegant": 7, "colorful": 2, "spacious": 7, "amenities": ["large window", "built-in wardrobe", "sleek tiles"], "luxurious": 6, "minimalist": 9, "image_index": 2, "natural_light": 9, "image_highlight": "built-in wooden wardrobe with clean lines", "detailed_analysis": "The image showcases a bright room featuring a large window that invites natural light, enhancing the minimalist aesthetic. A built-in wooden wardrobe with clean lines adds functionality and style, while the glossy white tiles reflect light, creating an open and airy feel. The overall design is modern and uncluttered, making it suitable for various activities like working or relaxing.", "suggested_amenities": ["Air Conditioning", "High-Speed Internet"], "suggested_activities": ["Working", "Reading", "Relaxing"]}, {"cozy": 5, "urban": 7, "modern": 8, "rustic": 1, "elegant": 6, "colorful": 2, "spacious": 6, "amenities": ["built-in wardrobe", "large window", "white tiles"], "luxurious": 4, "minimalist": 9, "image_index": 3, "natural_light": 5, "image_highlight": "open doorway leading to a small balcony", "detailed_analysis": "The image features a room with a large open doorway that leads to a small balcony, enhancing the connection to the outside. The walls are painted white, contributing to a bright atmosphere, while the sleek white tiles on the floor reflect light, making the space feel airy. The minimalistic design is complemented by the built-in wardrobe, which adds functionality without cluttering the space.", "suggested_amenities": ["Balcony", "Air Conditioning"], "suggested_activities": ["Reading", "Relaxing"]}, {"cozy": 6, "urban": 3, "modern": 8, "rustic": 1, "elegant": 7, "colorful": 2, "spacious": 5, "amenities": ["bathtub", "toilet", "sink", "shower", "mirror"], "luxurious": 7, "minimalist": 9, "image_index": 4, "natural_light": 4, "image_highlight": "freestanding bathtub with sleek modern design", "detailed_analysis": "The bathroom features a freestanding bathtub alongside a modern toilet and sink. The walls are adorned with light-colored tiles, enhancing the spacious feel. A large mirror above the sink adds depth, while the sleek design of the fixtures contributes to a contemporary aesthetic. Natural light filters in through a narrow window, providing a bright atmosphere. The overall layout is practical, combining functionality with a stylish appearance.", "suggested_amenities": ["Heated towel rack", "Vanity storage"], "suggested_activities": ["Relaxing", "Reading"]}]}', '2026-04-26 00:34:45.846+00', '2026-06-24 15:31:44.469+00', '2026-06-10 03:00:04.512+00', true, '2026-04-26 00:34:48.269649+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'complete', false, NULL),
