	('f92aac01-ad46-4d64-a419-e398a11652b6', 'nt131975529', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-phu-nhuan-tp-ho-chi-minh/131975529.htm#px=sr-stickyad-[po-1][pl-top]', 'Charming Urban Retreat in the Heart of Phú Nhuận', '86, Đường Thích Quảng Đức, Phường 5, Quận Phú Nhuận, Tp Hồ Chí Minh', '86 ng thch qung c phng 5 qun ph nhun tp h ch minh', 'ho_chi_minh', 7900000, '7,9 triệu/tháng', '35 m²', 'Step into this charming urban retreat, where modern design meets cozy comfort in the vibrant heart of Phú Nhuận. This beautifully furnished 2-bedroom apartment is bathed in natural light, creating a warm and inviting atmosphere perfect for relaxation and entertaining. The open layout seamlessly connects the living area to a stylish kitchen, ideal for hosting friends or enjoying a quiet morning coffee. With tasteful decor, soft color palettes, and rich textures, every corner of this space feels like home. The well-equipped kitchen features essential appliances, while the spacious bedrooms provide a serene escape from the hustle and bustle of city life. Enjoy the convenience of nearby amenities, including local markets, cafes, and parks, all within walking distance. This apartment is not just a place to live; it''s a lifestyle choice that embraces comfort, community, and the joy of urban living.', '{"Compact kitchen with sleek wooden cabinetry and counter","Bright natural light from large windows enhances space","Open layout connecting kitchen and two bedrooms","Cozy bedroom with minimalist decor and natural light","Efficient layout with easy access to rooms and kitchen"}', '{"Air Conditioning",WiFi,"Washing Machine",Elevator,"Security Camera","Natural Light","Modern Fixtures","Storage Cabinets","Lighting Fixtures",Bed,Wardrobe,Desk,Chair,Artwork,Workspace,"Kitchen Sink",Cabinets,Refrigerator,Stove,"Natural Light from Windows","Kitchen Appliances","Modern Design"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131975529/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131975529/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131975529/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131975529/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131975529/4.jpg}', 'Lê Công Tính', '037679 ***', NULL, '{"cozy": 6, "urban": 6, "colors": ["Warm", "Neutral", "Cool", "Bright", "Refined"], "modern": 6, "rustic": 3, "styles": ["Modern", "Cozy", "Minimalist"], "elegant": 6, "colorful": 4, "spacious": 5, "luxurious": 5, "activities": ["Working", "Relaxing", "Cooking", "Entertaining"], "minimalist": 6, "natural_light": 7, "image_analyses": [{"image_index": 0, "image_highlight": "Compact kitchen with sleek wooden cabinetry and counter", "suggested_amenities": ["Stainless steel appliances", "Breakfast bar"]}, {"image_index": 1, "image_highlight": "Bright natural light from large windows enhances space", "suggested_amenities": ["Window treatments", "Air conditioning"]}, {"image_index": 2, "image_highlight": "Open layout connecting kitchen and two bedrooms", "suggested_amenities": ["Open shelving", "Room dividers"]}, {"image_index": 3, "image_highlight": "Cozy bedroom with minimalist decor and natural light", "suggested_amenities": ["Built-in wardrobe", "Desk space"]}, {"image_index": 4, "image_highlight": "Efficient layout with easy access to rooms and kitchen", "suggested_amenities": ["Smart home features", "Soundproofing"]}]}', '2026-04-23 01:02:03.739+00', '2026-06-24 15:31:44.469+00', '2026-06-10 03:00:09.702+00', true, '2026-04-23 01:02:07.00213+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
