	('2d7ae615-66bd-45cc-83cb-ec38c092fbf0', 'nt131649184', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-dong-da-ha-noi/131649184.htm', 'Beautiful Collective Apartment for Rent in Chua Lang', 'Đường Chùa Láng, Phường Láng Thượng, Quận Đống Đa, Hà Nội', 'ng cha lng phng lng thng qun ng a h ni', 'hanoi', 10000000, '10 triệu/tháng', '80 m²', 'Discover this beautifully renovated collective apartment for rent in Chùa Láng, Đống Đa, Hà Nội. This spacious 80m² unit is located on the 4th floor of a 5-story building, offering a comfortable living space that feels like a brand new apartment. The layout includes 2-3 bedrooms, a large living room, a dedicated altar room, a kitchen with dining area, and one bathroom. The apartment is bright and clean, featuring wooden floors throughout. It comes fully furnished with essential appliances and furniture, including two air conditioners, water heaters, a refrigerator, washing machine, bed, wardrobe, sofa, kitchen cabinets, stove, and dining table, making it ready for immediate occupancy. Electricity and water are charged at residential rates. Conveniently, there is parking available for motorbikes and cars nearby. This property is ideal for families or groups of working women seeking a long-term rental. The price is negotiable, with a minimum contract of one year and a payment structure of 3 months deposit and 1 month rent. Contact for more details and a video tour.', '{"Open layout with modern lighting and wooden floors","Inviting open space for relaxation and gatherings","Elegant display cabinet for curated decor","Seamless flow into open living area","Natural light floods the warm wooden space"}', '{"Fully furnished","3 bedrooms","1 bathroom","Air conditioning","Water heater",Refrigerator,"Washing machine",Bed,Wardrobe,Sofa,"Kitchen cabinets",Stove,"Dining table","Wooden floors","Corner unit","Private pink book (legal document)","Car parking nearby","Motorbike parking nearby","Air Conditioning","Wall Clock","Lighting Fixtures","Wood Flooring","Storage Cabinet","Window Treatments","TV Stand","Wooden Flooring",Shelves,"Kitchen Cabinets",Bookshelf,"Display Cabinet","Large Window","Elegant display cabinet","Wooden flooring",Curtains,"Recessed lighting","Wall art","Bed Frame","Large Windows"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131649184/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131649184/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131649184/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131649184/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131649184/4.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131649184/5.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131649184/6.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131649184/7.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131649184/8.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131649184/9.jpg}', 'Bui Tung', '091677***', NULL, '{"cozy": 7, "urban": 5, "colors": ["Warm", "Neutral", "Cool", "Refined"], "modern": 6, "rustic": 3, "styles": ["Cozy", "Spacious", "Modern"], "elegant": 6, "colorful": 3, "spacious": 7, "luxurious": 5, "activities": ["Relaxing", "Entertaining", "Entertaining guests", "Relaxing with family", "Reading"], "minimalist": 6, "natural_light": 6, "image_analyses": [{"amenities": ["Air Conditioning", "Wall Clock", "Lighting Fixtures", "Sofa", "Wood Flooring", "Storage Cabinet", "Window Treatments"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 5, "modern": 7, "elegant": 4, "spacious": 6, "luxurious": 5, "minimalist": 8, "natural_light": 7}, "image_highlight": "Open layout with modern lighting and wooden floors", "detailed_analysis": "This inviting space showcases an open layout, perfect for both relaxation and social gatherings. The warm wooden flooring contrasts beautifully with modern lighting fixtures, creating an atmosphere that feels both cozy and sophisticated. The air conditioning unit ensures comfort, while the wall clock adds a practical touch. Ample natural light streams in through the windows, enhancing the overall brightness and appeal of the room. A clever use of storage solutions maintains a clean aesthetic, making it ideal for effortless living.", "suggested_amenities": ["Air Conditioning", "Lighting Fixtures"], "suggested_activities": ["Relaxing", "Entertaining"]}, {"amenities": ["Sofa", "TV Stand", "Wooden Flooring", "Shelves", "Kitchen Cabinets"], "image_index": 1, "vibe_scores": {"cozy": 7, "urban": 7, "modern": 5, "elegant": 5, "spacious": 6, "luxurious": 4, "minimalist": 6, "natural_light": 5}, "image_highlight": "Inviting open space for relaxation and gatherings", "detailed_analysis": "This inviting living area features a blend of cozy wooden flooring and modern design elements, creating a warm atmosphere perfect for relaxation or social gatherings. A stylish TV stand and shelves provide functional storage while maintaining aesthetic appeal. The open layout encourages seamless flow between spaces, maximizing natural light from the nearby windows. The neutral tones are complemented by the rich wood accents, enhancing the overall calm and welcoming vibe, making it an ideal setting for both entertaining guests and unwinding with loved ones.", "suggested_amenities": ["Sofa", "TV Stand"], "suggested_activities": ["Entertaining guests", "Relaxing with family"]}, {"amenities": ["Bookshelf", "Display Cabinet", "Large Window", "Wood Flooring", "Lighting Fixtures"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 4, "modern": 7, "elegant": 7, "spacious": 8, "luxurious": 5, "minimalist": 4, "natural_light": 6}, "image_highlight": "Elegant display cabinet for curated decor", "detailed_analysis": "This entryway exudes an elegant charm, highlighted by the beautifully crafted display cabinet and a well-stocked bookshelf. The warm wood flooring creates a cozy ambiance, while the large window invites natural light, enhancing the inviting atmosphere. The space flows seamlessly into adjacent rooms, making it practical for both relaxation and productivity. Thoughtful lighting fixtures add a modern touch, ensuring the area is well-lit and welcoming. This entryway serves as a perfect introduction to the rest of the home, setting a sophisticated tone.", "suggested_amenities": ["Display Cabinet", "Bookshelf"], "suggested_activities": ["Reading", "Showcasing collectibles"]}, {"amenities": ["Elegant display cabinet", "Wooden flooring", "Curtains", "Recessed lighting", "Wall art"], "image_index": 3, "vibe_scores": {"cozy": 8, "urban": 5, "modern": 7, "elegant": 7, "spacious": 7, "luxurious": 6, "minimalist": 5, "natural_light": 6}, "image_highlight": "Seamless flow into open living area", "detailed_analysis": "This inviting space features a seamless transition into the open living area, accentuated by elegant display cabinets and warm wooden flooring that creates a cozy yet modern atmosphere. The recessed lighting enhances the room''s brightness, making it perfect for hosting gatherings. The soft curtains add an element of comfort while allowing for privacy. The overall design fosters a sense of connection and flow, making it an ideal setting for social interactions and relaxation.", "suggested_amenities": ["Elegant display cabinet", "Recessed lighting"], "suggested_activities": ["Hosting gatherings", "Relaxing with guests"]}, {"amenities": ["Wooden Flooring", "Storage Cabinet", "Bed Frame", "Curtains", "Large Windows"], "image_index": 4, "vibe_scores": {"cozy": 8, "urban": 5, "modern": 5, "elegant": 6, "spacious": 6, "luxurious": 4, "minimalist": 6, "natural_light": 7}, "image_highlight": "Natural light floods the warm wooden space", "detailed_analysis": "This serene bedroom exudes warmth and comfort with its rich wooden flooring and cabinetry. Natural light pours in through the large windows, creating a welcoming atmosphere perfect for relaxation or morning routines. The minimalistic design, characterized by the simple bed frame and functional storage cabinet, promotes a clutter-free environment, enhancing focus and tranquility. The soft color palette and subtle decor elements contribute to a soothing ambiance, making it an ideal retreat for restful sleep or quiet contemplation.", "suggested_amenities": ["Large Windows", "Storage Cabinet"], "suggested_activities": ["Morning yoga sessions", "Relaxing reading nook"]}]}', '2026-04-07 15:02:00.793+00', '2026-06-24 15:31:44.469+00', '2026-06-23 03:00:14.539+00', true, '2026-04-07 15:02:00.904919+00', '2026-06-23 03:00:14.513814+00', NULL, NULL, '3 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
