	('c9e302be-001d-4532-8247-626cf6e4f337', 'nt131729647', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-thanh-pho-thu-duc-tp-ho-chi-minh/131729647.htm#px=sr-stickyad-[po-1][pl-top]', 'Charming Mini Apartment with Modern Design in Tranquil Thủ Đức', '23/33A, Đường số 27, Phường Hiệp Bình Chánh, Thành phố Thủ Đức, Tp Hồ Chí Minh', '2333a ng s 27 phng hip bnh chnh thnh ph th c tp h ch minh', 'ho_chi_minh', 5300000, '5,3 triệu/tháng', '30 m²', 'Step into this charming mini apartment that perfectly balances modern design with a cozy atmosphere. The space is bathed in natural light, creating a warm and inviting environment ideal for relaxation after a long day. With a contemporary aesthetic, the apartment features a spacious living area that flows seamlessly into a well-equipped kitchen, making it perfect for hosting friends or enjoying a quiet morning coffee. The thoughtful layout includes a comfortable bedroom that promises restful nights, while the full furnishings—complete with a bed, wardrobe, air conditioning, and even a washing machine—allow you to move in with just your suitcase. Nestled in a tranquil neighborhood, this apartment offers a peaceful retreat while still being conveniently located near essential amenities. Experience the perfect blend of comfort and style in this delightful living space.', '{"Natural light flooding through expansive windows","Efficient kitchen layout for culinary creativity","Inviting natural light with serene garden views","Functional shower area with sleek design","Efficient space for essential daily routines"}', '{"Air Conditioning","Washing Machine","Full Furniture","Natural Light",Security,"Wooden Partition","Large Windows",Curtains,"Floor Tiles","Cozy Bed","Kitchen Cabinets","Kitchen Sink",Refrigerator,"Counter Space","Wooden Bed Frame",Shower,Mirror,Toilet,Sink,"Modern Bathroom","Bathroom Sink","Modern Toilet",Window}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131729647/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131729647/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131729647/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131729647/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131729647/4.jpg}', 'Home27', '090922 ***', NULL, '{"cozy": 4, "urban": 5, "colors": ["Neutral", "Cool", "Bright"], "modern": 7, "rustic": 2, "styles": ["Modern", "Minimalist"], "elegant": 5, "colorful": 2, "spacious": 5, "luxurious": 5, "activities": ["Relaxing", "Cooking", "Entertaining"], "minimalist": 7, "natural_light": 7, "image_analyses": [{"amenities": ["Wooden Partition", "Large Windows", "Curtains", "Floor Tiles"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 5, "modern": 8, "elegant": 7, "spacious": 6, "luxurious": 7, "minimalist": 8, "natural_light": 9}, "image_highlight": "Natural light flooding through expansive windows", "detailed_analysis": "This space features an innovative wooden partition that adds a touch of modern elegance while providing a sense of privacy. The large windows invite abundant natural light, creating an uplifting atmosphere. The clean lines and minimalist aesthetic, combined with neutral tones, enhance the serene feel of the room. The use of floor tiles contributes to a fresh and contemporary vibe, making it an ideal sanctuary for relaxation and rejuvenation.", "suggested_amenities": ["Natural Light", "Cozy Bed"], "suggested_activities": ["Relaxing"]}, {"amenities": ["Kitchen Cabinets", "Kitchen Sink", "Refrigerator", "Counter Space"], "image_index": 1, "vibe_scores": {"cozy": 3, "urban": 4, "modern": 5, "elegant": 3, "spacious": 4, "luxurious": 4, "minimalist": 6, "natural_light": 5}, "image_highlight": "Efficient kitchen layout for culinary creativity", "detailed_analysis": "This kitchen space features a practical layout with efficient cabinetry and a clean design. The warm wooden cabinets offer a touch of sophistication, while the ample counter space invites culinary creativity. The natural light streaming through the window enhances the inviting atmosphere, making it a perfect spot for both cooking and casual entertaining. The neutral tile flooring complements the modern aesthetic, ensuring the space feels open and functional. Overall, it creates an environment that balances utility with style.", "suggested_amenities": ["Kitchen Cabinets", "Refrigerator"], "suggested_activities": ["Cooking", "Entertaining"]}, {"amenities": ["Large Windows", "Curtains", "Wooden Bed Frame"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 4, "modern": 8, "elegant": 7, "spacious": 6, "luxurious": 5, "minimalist": 7, "natural_light": 9}, "image_highlight": "Inviting natural light with serene garden views", "detailed_analysis": "This bedroom exudes a tranquil atmosphere, accentuated by large windows that invite abundant natural light, creating an uplifting environment. The wooden bed frame adds a touch of warmth, while the soft drapes offer both style and privacy. The layout feels open and airy, enhancing the spaciousness of the room. The connection to the outside greenery through the windows fosters a sense of calm and serenity, making it an ideal location for relaxation or peaceful reading sessions.", "suggested_amenities": ["Large Windows", "Wooden Bed Frame"], "suggested_activities": ["Relaxing"]}, {"amenities": ["Shower", "Mirror", "Toilet", "Sink"], "image_index": 3, "vibe_scores": {"cozy": 2, "urban": 4, "modern": 6, "elegant": 5, "spacious": 4, "luxurious": 3, "minimalist": 7, "natural_light": 5}, "image_highlight": "Functional shower area with sleek design", "detailed_analysis": "This bathroom showcases a sleek, modern design with clean lines and minimalistic aesthetics. The compact layout features a functional shower area, a stylish sink, and a contemporary toilet. The muted color palette, accented by horizontal stripes, creates a sophisticated atmosphere. Natural light filters in through a small window, enhancing the sense of space and freshness. This room epitomizes efficiency and comfort, making it a perfect retreat for daily rejuvenation.", "suggested_amenities": ["Modern Bathroom", "Shower"], "suggested_activities": ["Relaxing"]}, {"amenities": ["Bathroom Sink", "Modern Toilet", "Mirror", "Window"], "image_index": 4, "vibe_scores": {"cozy": 3, "urban": 7, "modern": 8, "elegant": 5, "spacious": 5, "luxurious": 4, "minimalist": 9, "natural_light": 6}, "image_highlight": "Efficient space for essential daily routines", "detailed_analysis": "This bathroom exemplifies modern efficiency with its minimalist design and clean lines. The contemporary fixtures, including a sleek bathroom sink and a modern toilet, enhance functionality while maintaining a stylish aesthetic. The large mirror reflects light, creating a sense of openness, while the window brings in natural illumination, making the space feel fresh and inviting. The overall layout is compact yet practical, offering a seamless experience for daily routines.", "suggested_amenities": ["Modern Toilet", "Bathroom Sink"], "suggested_activities": ["Relaxing"]}]}', '2026-04-20 01:39:17.749+00', '2026-06-24 15:31:44.469+00', '2026-06-24 03:00:06.033+00', true, '2026-04-20 01:39:20.382707+00', '2026-06-24 03:00:06.049205+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
