es": [], "activities": [], "image_analyses": [{"image_index": 0, "image_highlight": "Vibrant illuminated fountain in tranquil garden setting", "suggested_amenities": ["Fountain", "Outdoor Lighting"]}, {"image_index": 1, "image_highlight": "Bright indoor space with balcony access", "suggested_amenities": ["Indoor Plants", "Air Conditioning"]}, {"image_index": 2, "image_highlight": "Entertainment hub with stylish TV and seating", "suggested_amenities": ["Television", "Sofa"]}, {"image_index": 3, "image_highlight": "Bright window with urban city views", "suggested_amenities": ["Wardrobe", "Nightstand"]}, {"image_index": 4, "image_highlight": "Efficient kitchen for culinary creativity", "suggested_amenities": ["Modern Refrigerator", "Stylish Kitchen Cabinets"]}]}', '2026-03-22 11:32:18.738+00', '2026-06-24 15:31:44.469+00', '2026-06-15 03:00:04.877+00', true, '2026-03-22 11:32:18.761102+00', '2026-06-15 03:00:04.868135+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
