	('45ba5a3b-24c2-434d-b6d9-e9c71054723b', 'nt132011584', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-7-tp-ho-chi-minh/132011584.htm#px=sr-stickyad-[po-1][pl-top]', 'Chic Urban Retreat in Docklands with Full Amenities', 'Nguyễn Thị Thập, Phường Tân Phú, Quận 7, Tp Hồ Chí Minh', 'nguyn th thp phng tn ph qun 7 tp h ch minh', 'ho_chi_minh', 27000000, '27 triệu/tháng', '116 m²', 'Step into a chic urban retreat that embodies modern living in the heart of Docklands. This spacious 116 m² apartment features a harmonious blend of contemporary design and luxurious comfort. With three beautifully appointed bedrooms, each bathed in natural light, the space invites you to unwind and relax. The open-plan living area is perfect for hosting friends or enjoying quiet evenings, while the high-end furnishings add a touch of elegance. Imagine sipping your morning coffee on the balcony, surrounded by vibrant city views, or working from home in a stylish environment that inspires creativity. The neutral color palette, accented with warm textures, creates a soothing atmosphere that feels both inviting and sophisticated. This apartment is not just a place to live; it''s a lifestyle choice that enhances your daily rituals.', '{"Gray built-in shelves with stylish bags displayed","Oval mirror with integrated lighting above the desk","Wall-mounted television with sleek black finish","Soft pink headboard with decorative pillows arranged","Bedside lamp with textured base and soft glow"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Parking,Pool,Gym,Elevator,"Security Camera",bed,nightstand,shelves,artwork,"window blinds","Air conditioning","Wall art",Mirror,Desk,Television,"Built-in shelves","built-in shelves","oval mirror",desk,"Smart TV","Built-in storage",lamp,bookshelf,"Bed linens","bedside lamp",window,"wall-mounted television",Artwork}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132011584/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132011584/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132011584/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132011584/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132011584/4.jpg}', 'Nguyễn Phương Anh', '093768 ***', NULL, '{"cozy": 7, "urban": 6, "colors": ["Warm", "Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 2, "styles": ["Minimalist", "Modern", "Elegant"], "elegant": 8, "colorful": 4, "spacious": 5, "amenities": ["bed", "nightstand", "artwork", "shelves", "window blinds", "mirror", "desk", "TV", "air conditioning", "wall-mounted TV", "storage unit", "lamp", "window"], "luxurious": 6, "activities": ["Reading", "Relaxing", "Working"], "minimalist": 9, "natural_light": 7, "image_analyses": [{"amenities": ["bed", "nightstand", "shelves", "artwork", "window blinds"], "image_index": 0, "vibe_scores": {"cozy": 7, "urban": 5, "modern": 8, "elegant": 7, "spacious": 4, "luxurious": 5, "minimalist": 9, "natural_light": 6}, "image_highlight": "Gray built-in shelves with stylish bags displayed", "detailed_analysis": "The image showcases a modern bedroom with a gray color palette. A neatly made bed is positioned against the wall, complemented by a nightstand holding a lamp and decorative items. Built-in shelves display stylish bags, adding a touch of elegance and organization. The room benefits from natural light through a window with striped blinds, enhancing the minimalist aesthetic. The overall design reflects contemporary living with thoughtful storage solutions.", "suggested_amenities": ["Air conditioning", "Wall art"], "suggested_activities": ["Reading", "Relaxing"]}, {"amenities": ["Mirror", "Desk", "Television", "Built-in shelves"], "image_index": 1, "vibe_scores": {"cozy": 7, "urban": 6, "modern": 8, "elegant": 8, "spacious": 5, "luxurious": 6, "minimalist": 9, "natural_light": 7}, "image_highlight": "Oval mirror with integrated lighting above the desk", "detailed_analysis": "The image showcases a modern bedroom with a sleek oval mirror featuring integrated lighting above a minimalist desk. A wall-mounted television is positioned across from the bed, enhancing the room''s functionality. Natural light filters through striped window blinds, creating a bright ambiance. The subtle color palette and clean lines contribute to a cozy yet modern aesthetic, making it suitable for various activities like working or relaxing.", "suggested_amenities": ["Desk", "Air Conditioning"], "suggested_activities": ["Working", "Reading", "Relaxing"]}, {"amenities": ["built-in shelves", "oval mirror", "desk"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 7, "modern": 8, "elegant": 8, "spacious": 5, "luxurious": 7, "minimalist": 9, "natural_light": 6}, "image_highlight": "Wall-mounted television with sleek black finish", "detailed_analysis": "The image features a wall-mounted television that complements the modern aesthetic of the room. The sleek black finish of the TV contrasts with the light-colored walls, enhancing the minimalist design. Nearby, built-in shelves display decorative items, adding a touch of personalization. The overall layout promotes a functional yet stylish living space, suitable for both relaxation and productivity.", "suggested_amenities": ["Smart TV", "Built-in storage"], "suggested_activities": ["Working", "Relaxing"]}, {"amenities": ["bed", "nightstand", "lamp", "artwork", "bookshelf"], "image_index": 3, "vibe_scores": {"cozy": 7, "urban": 7, "modern": 8, "elegant": 7, "spacious": 6, "luxurious": 6, "minimalist": 9, "natural_light": 8}, "image_highlight": "Soft pink headboard with decorative pillows arranged", "detailed_analysis": "The image showcases a bedroom featuring a soft pink headboard with decorative pillows. A nightstand with a lamp sits beside the bed, contributing to a cozy atmosphere. A framed landscape artwork adorns the wall above the bed, adding visual interest. The room is well-lit with natural light streaming through the window, enhancing the warm tones of the furnishings. Built-in shelves display books and decorative items, maintaining a clean and minimalist aesthetic.", "suggested_amenities": ["Air conditioning", "Bed linens"], "suggested_activities": ["Relaxing", "Reading"]}, {"amenities": ["bed", "bedside lamp", "window", "wall-mounted television"], "image_index": 4, "vibe_scores": {"cozy": 7, "urban": 7, "modern": 8, "elegant": 8, "spacious": 5, "luxurious": 6, "minimalist": 9, "natural_light": 6}, "image_highlight": "Bedside lamp with textured base and soft glow", "detailed_analysis": "The image showcases a cozy bedroom with a neatly made bed and a bedside lamp that emits a soft glow. The soft pink headboard complements the neutral tones of the room. A large window with striped blinds allows natural light to filter in, enhancing the inviting atmosphere. A piece of artwork hangs on the wall, adding a touch of personality to the minimalist decor, while the wall-mounted television offers entertainment options.", "suggested_amenities": ["Air Conditioning", "Artwork"], "suggested_activities": ["Reading", "Relaxing"]}]}', '2026-04-25 00:38:45.068+00', '2026-06-24 15:31:44.469+00', '2026-06-12 03:00:09.862+00', true, '2026-04-25 00:38:47.938208+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '3 Bedrooms', 0, 'alive', NULL, NULL, 0, 'complete', false, NULL),
	('077cdbcc-8956-4f50-a611-323a3cc0f857', 'aHR0cHM6Ly93d3cubmhhdG90LmNvbS90aHVlLWNhbi1oby1jaHVuZy1jdS1xdWFuLTEtdHAtaG8tY2hpLW1pbmgvMTEwNDUxNzA3', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-1-tp-ho-chi-minh/110451707.htm', 'Luxurious 2-Bedroom Apartment in Vinhomes Golden River BaSon with Modern Furnishings', 'đường Tôn Đức Thắng, Phường Bến Nghé, Quận 1, Tp Hồ Chí Minh', 'ng tn c thng phng bn ngh qun 1 tp h ch minh', 'other', 26000000, '26 triệu/tháng', '80 m²', 'Discover sophisticated urban living in this exquisite 2-bedroom apartment at Vinhomes Golden River BaSon. This residence offers a seamless blend of comfort and style, featuring full, modern furnishings as depicted in the photos. Alternatively, the apartment can be rented unfurnished to suit your personal taste. Enjoy expansive, airy views from this prime location in District 1. The interiors are meticulously maintained with new furnishings, ensuring a fresh and inviting atmosphere. This is an ideal home for those seeking a premium lifestyle in one of Ho Chi Minh City''s most prestigious developments. Contact us today for more details and to arrange a viewing.', '{Modern,Neutral,Relaxing}', '{}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-aHR0cHM6Ly93d3cubmhhdG90LmNvbS90a-1fd8de7571b526e8/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-aHR0cHM6Ly93d3cubmhhdG90LmNvbS90a-1fd8de7571b526e8/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-aHR0cHM6Ly93d3cubmhhdG90LmNvbS90a-1fd8de7571b526e8/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-aHR0cHM6Ly93d3cubmhhdG90LmNvbS90a-1fd8de7571b526e8/3.jpg}', 'Chí Nhân', '+84366666486', 'Modern', '{"colors": ["Neutral"], "styles": ["Modern"], "amenities": [], "activities": ["Relaxing"], "image_analyses": [{"image_index": 0, "image_highlight"