	('90b4d80d-e470-4956-a943-8678cdc38408', 'nt126107194', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-thanh-pho-thu-duc-tp-ho-chi-minh/126107194.htm#px=sr-stickyad-[po-1][pl-top]', 'Chic Urban Retreat in Masteri Thao Dien with Pool Views', 'Xa Lộ Hà Nội, Phường Thảo Điền, Thành phố Thủ Đức, Tp Hồ Chí Minh', 'xa l h ni phng tho in thnh ph th c tp h ch minh', 'ho_chi_minh', 16000000, '16 triệu/tháng', '74 m²', 'Step into a chic urban retreat at Masteri Thao Dien, where modern design meets comfort. This stylish 2-bedroom apartment boasts a spacious 74 m² layout, perfect for both relaxation and entertaining. The open-plan living area is flooded with natural light, creating a warm and inviting atmosphere. With high-end furnishings and a tasteful color palette, the space feels both luxurious and homely. Imagine sipping your morning coffee on the balcony, enjoying serene views of the pool, or hosting friends in the elegantly designed living room. The apartment features premium amenities, ensuring a convenient lifestyle. Whether you''re working from home or unwinding after a long day, this apartment offers the perfect backdrop for your daily rituals. Experience the vibrant lifestyle of Thao Dien, with its trendy cafes and shops just a stone''s throw away.', '{"Inviting minimalist bedroom with artistic flair","Breathtaking urban view from large windows","Contemporary dining area for social gatherings"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Pool,Gym,Elevator,"Security Camera",Wardrobe,"Queen Bed",Artwork,Nightstand,TV,"Coffee Table",Sofa,"Large Windows","Comfortable Sofa","Dining Table","Dining Chairs","Wall-mounted TV","Decorative Plant","Art Piece",Curtains,"Recessed Lighting"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt126107194/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt126107194/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt126107194/2.jpg}', 'Nguyễn Phương Uyên', '093123 ***', NULL, '{"cozy": 6, "urban": 7, "colors": ["Warm", "Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 2, "styles": ["Minimalist", "Modern", "Elegant"], "elegant": 7, "colorful": 4, "spacious": 6, "luxurious": 6, "activities": ["Relaxing", "Reading", "Entertaining"], "minimalist": 9, "natural_light": 7, "image_analyses": [{"amenities": ["Air Conditioning", "Wardrobe", "Queen Bed", "Artwork", "Nightstand"], "image_index": 0, "vibe_scores": {"cozy": 7, "urban": 5, "modern": 8, "elegant": 7, "spacious": 5, "luxurious": 6, "minimalist": 9, "natural_light": 6}, "image_highlight": "Inviting minimalist bedroom with artistic flair", "detailed_analysis": "This minimalist bedroom exudes a serene ambiance with its clean lines and neutral palette. The cozy queen bed, adorned with soft linens, invites restful slumber, while the art piece adds a splash of color and personality. Ample storage is provided by the built-in wardrobe, ensuring a clutter-free space. Natural light, enhanced by the soft curtains, creates a warm atmosphere, making it an ideal retreat for relaxation or quiet reading. The overall design seamlessly blends comfort and style, perfect for urban living.", "suggested_amenities": ["Air Conditioning", "Wardrobe"], "suggested_activities": ["Relaxing", "Reading"]}, {"amenities": ["Air Conditioning", "TV", "Coffee Table", "Sofa", "Large Windows"], "image_index": 1, "vibe_scores": {"cozy": 6, "urban": 7, "modern": 8, "elegant": 6, "spacious": 7, "luxurious": 5, "minimalist": 9, "natural_light": 8}, "image_highlight": "Breathtaking urban view from large windows", "detailed_analysis": "This contemporary living space exudes a modern aesthetic with its clean lines and minimalist design. The large windows flood the room with natural light, creating an uplifting atmosphere. The plush sofa invites relaxation, while the sleek coffee table provides a chic focal point. The gentle color palette enhances a calming vibe, making it perfect for unwinding or hosting friends. The seamless flow of the space, combined with the stunning urban view, transforms this room into a personal retreat or an ideal spot for entertaining.", "suggested_amenities": ["Comfortable Sofa", "Air Conditioning"], "suggested_activities": ["Relaxing", "Entertaining"]}, {"amenities": ["Large Windows", "Sofa", "Coffee Table", "Dining Table", "Dining Chairs", "Wall-mounted TV", "Decorative Plant", "Art Piece", "Curtains", "Recessed Lighting"], "image_index": 2, "vibe_scores": {"cozy": 5, "urban": 9, "modern": 8, "elegant": 7, "spacious": 7, "luxurious": 6, "minimalist": 9, "natural_light": 8}, "image_highlight": "Contemporary dining area for social gatherings", "detailed_analysis": "This vibrant living space features a contemporary dining area, perfect for hosting intimate gatherings or enjoying meals with family. The sleek marble dining table and stylish chairs create a chic atmosphere, while the wall-mounted TV adds modern convenience. Natural light floods the room through large windows, enhancing the minimalist aesthetic with a bright and airy feel. The plush sofa invites relaxation, making it a versatile area for both social interactions and quiet reading sessions. The overall design merges sophistication with functionality, offering a stylish yet comfortable environment.", "suggested_amenities": ["Dining Table", "Wall-mounted TV"], "suggested_activities": ["Entertaining", "Reading"]}]}', '2026-04-20 01:39:11.169+00', '2026-06-24 15:31:44.469+00', '2026-06-19 03:00:14.175+00', true, '2026-04-20 01:39:14.466268+00', '2026-06-19 03:00:14.196527+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
