	('46c31345-6878-4d12-95d4-86e086fe9260', 'nt130830892', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-ba-dinh-ha-noi/130830892.htm', 'Cozy 1 Bedroom Service Apartment for Rent in Ba Dinh, Hanoi', 'Ccmn ngõ 376 đường Bưởi, Phường Vĩnh Phúc, Quận Ba Đình, Hà Nội', 'ccmn ng 376 ng bi phng vnh phc qun ba nh h ni', 'hanoi', 5500000, '5.5 triệu/tháng', '40 m²', 'This charming 1-bedroom service apartment is located in a quiet alley on Bưởi Street, offering a comfortable living space of 40 m². The apartment is fully furnished with essential amenities including air conditioning, a washing machine, a kitchen cabinet, and WiFi. It features a spacious balcony and two large windows that provide ample natural light and ventilation. The location is convenient, just a 2-minute walk to Vĩnh Phúc Market, Hoàng Hoa Thám School, and 354 Hospital. Additionally, it is situated close to a military base, ensuring a secure environment. Ideal for individuals or couples looking for a cozy home in the heart of Hanoi.', '{"Functional kitchen area with ample cabinetry","Stylish patterned flooring enhances visual appeal","Comfortable sleeping area with personalized decor","Efficient kitchen corner with modern fixtures"}', '{"Air Conditioning","Washing Machine","Kitchen Cabinet",WiFi,Balcony,"Kitchen Sink",Cabinets,"Cooking Range","Dining Chairs","Ceiling Fan","Kitchen Cabinets",Shower,"Bathroom Sink",Toilet,Mirror,"Storage Shelves",Bed,Wardrobe,Flooring,Lighting,"Comfortable Bed",Countertop,Window}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130830892/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130830892/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130830892/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130830892/3.jpg}', 'Cô Nhì', NULL, NULL, '{"cozy": 6, "urban": 5, "colors": ["Warm", "Neutral"], "modern": 5, "rustic": 2, "styles": ["Cozy", "Minimalist"], "elegant": 4, "colorful": 4, "spacious": 5, "luxurious": 3, "activities": ["Cooking meals", "Casual dining", "Refreshing showers", "Morning routines", "Relaxing"], "minimalist": 6, "natural_light": 5, "image_analyses": [{"amenities": ["Kitchen Sink", "Cabinets", "Cooking Range", "Dining Chairs", "Ceiling Fan"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 4, "modern": 5, "elegant": 3, "spacious": 5, "luxurious": 4, "minimalist": 7, "natural_light": 6}, "image_highlight": "Functional kitchen area with ample cabinetry", "detailed_analysis": "This space features a functional kitchen area complete with cabinets, a cooking range, and a kitchen sink, ideal for culinary creativity. The neutral color palette combined with tile flooring and ample natural light creates a bright atmosphere perfect for relaxation. The ceiling fan adds comfort, while the layout promotes a cozy yet spacious feel, making it suitable for casual dining or cooking. The overall design emphasizes practicality without sacrificing style.", "suggested_amenities": ["Kitchen Cabinets", "Ceiling Fan"], "suggested_activities": ["Cooking meals", "Casual dining"]}, {"amenities": ["Shower", "Bathroom Sink", "Toilet", "Mirror", "Storage Shelves"], "image_index": 1, "vibe_scores": {"cozy": 4, "urban": 6, "modern": 5, "elegant": 4, "spacious": 4, "luxurious": 3, "minimalist": 7, "natural_light": 5}, "image_highlight": "Stylish patterned flooring enhances visual appeal", "detailed_analysis": "This bathroom combines functionality with style through its chic patterned flooring and contemporary fixtures. The well-placed mirror and efficient layout create a spacious feel, while the glass shower enclosure adds an element of modern elegance. Ample storage options ensure everything is organized, making daily routines easier. The bright lighting enhances the overall ambiance, creating a welcoming atmosphere that transforms mundane bathroom visits into enjoyable experiences.", "suggested_amenities": ["Shower", "Bathroom Sink"], "suggested_activities": ["Refreshing showers", "Morning routines"]}, {"amenities": ["Bed", "Wardrobe", "Flooring", "Lighting"], "image_index": 2, "vibe_scores": {"cozy": 8, "urban": 3, "modern": 3, "elegant": 3, "spacious": 5, "luxurious": 2, "minimalist": 5, "natural_light": 4}, "image_highlight": "Comfortable sleeping area with personalized decor", "detailed_analysis": "This bedroom offers a comfortable oasis with its cozy bed adorned in a patterned blanket, inviting restful nights. The warm lighting coupled with the natural light enhances the room''s calming atmosphere. A modern wardrobe provides ample storage, ensuring an organized space. The polished flooring complements the overall design, making it feel both spacious and intimate. The room''s layout encourages relaxation and personal expression, making it a perfect retreat for unwinding after a busy day.", "suggested_amenities": ["Comfortable Bed", "Wardrobe"], "suggested_activities": ["Relaxing", "Sleeping"]}, {"amenities": ["Kitchen Sink", "Cabinets", "Ceiling Fan", "Countertop", "Window"], "image_index": 3, "vibe_scores": {"cozy": 5, "urban": 7, "modern": 7, "elegant": 4, "spacious": 5, "luxurious": 4, "minimalist": 6, "natural_light": 6}, "image_highlight": "Efficient kitchen corner with modern fixtures", "detailed_analysis": "This compact kitchen corner blends efficiency with modern design, featuring sleek cabinetry and a stylish countertop. The ceiling fan adds a refreshing touch, while the window invites natural light, creating a bright and airy atmosphere. The arrangement supports practical cooking and dining experiences without sacrificing style. The minimalist aesthetic ensures the space feels open and uncluttered, perfect for quick meal preparations or casual coffee moments.", "suggested_amenities": ["Kitchen Sink", "Ceiling Fan"], "suggested_activities": ["Preparing quick meals", "Enjoying morning coffee"]}]}', '2026-03-28 07:32:09.037+00', '2026-06-24 15:31:44.469+00', '2026-06-13 03:00:08.118+00', true, '2026-03-28 07:32:09.132237+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
