	('80ae3c72-ff15-4b47-88b1-922ade95ce1c', 'nt131787498', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-3-tp-ho-chi-minh/131787498.htm', 'Charming Urban Retreat with Spacious Balcony in Quận 3', 'Đường Ðiện Biên Phủ, Phường 4, Quận 3, Tp Hồ Chí Minh', 'ng in bin ph phng 4 qun 3 tp h ch minh', 'ho_chi_minh', 6000000, '6 triệu/tháng', '40 m²', 'Step into this charming urban retreat, where modern comfort meets a vibrant atmosphere. This spacious 1-bedroom apartment boasts a generous balcony that invites natural light and fresh air, perfect for enjoying your morning coffee or unwinding after a long day. The interior features a harmonious blend of contemporary design and cozy accents, creating a warm and inviting space. The neutral color palette, complemented by tasteful decor, enhances the feeling of tranquility. With ample room for both relaxation and productivity, this apartment is ideal for remote work or hosting friends. Located just minutes from the bustling heart of Quận 1, you''ll have easy access to a variety of dining and entertainment options, while still enjoying the peace of a quiet neighborhood. Experience the best of city living in this delightful apartment.', '{"Stylish glass partition separating living and sleeping areas","Bright natural light through large windows and curtains","Modern kitchen with sleek appliances and bar seating","Cozy bedroom with minimalist decor and sliding doors","Contemporary entertainment unit with wall-mounted TV"}', '{"Air Conditioning",WiFi,Balcony,"Security Camera"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131787498/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131787498/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131787498/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131787498/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131787498/4.jpg}', 'Not provided', '034219 ***', NULL, '{"colors": [], "styles": [], "activities": [], "image_analyses": [{"image_index": 0, "image_highlight": "Stylish glass partition separating living and sleeping areas", "suggested_amenities": ["Glass partition", "Compact furniture"]}, {"image_index": 1, "image_highlight": "Bright natural light through large windows and curtains", "suggested_amenities": ["Large windows", "Light-filtering curtains"]}, {"image_index": 2, "image_highlight": "Modern kitchen with sleek appliances and bar seating", "suggested_amenities": ["Bar stools", "Stainless steel appliances"]}, {"image_index": 3, "image_highlight": "Cozy bedroom with minimalist decor and sliding doors", "suggested_amenities": ["Sliding door", "Minimalist furniture"]}, {"image_index": 4, "image_highlight": "Contemporary entertainment unit with wall-mounted TV", "suggested_amenities": ["Wall-mounted TV", "Entertainment unit"]}]}', '2026-04-13 00:32:29.937+00', '2026-06-24 15:31:44.469+00', '2026-06-23 03:00:04.303+00', true, '2026-04-13 00:32:35.603806+00', '2026-06-23 03:00:04.287427+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('fc98fb7d-8fc7-4cd8-b0d4-75108ce37ef3', 'nt131790061', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-tan-binh-tp-ho-chi-minh/131790061.htm', 'Charming Corner Apartment with Full Furnishings in Tân Bình', '31 - 33, Đường Phan Huy Ích, Phường 15, Quận Tân Bình, Tp Hồ Chí Minh', '31 33 ng phan huy ch phng 15 qun tn bnh tp h ch minh', 'ho_chi_minh', 14000000, '14 triệu/tháng', '132 m²', 'Step into this charming corner apartment that radiates warmth and comfort, perfect for families or groups of friends. With a generous 132 m² layout, this home features three beautifully appointed bedrooms, each designed to be a serene retreat. The open-plan living area is bathed in natural light, creating an inviting atmosphere for morning coffee or evening gatherings. The full furnishings include modern decor and cozy textiles, ensuring a stylish yet comfortable living experience. The kitchen, equipped for culinary adventures, flows seamlessly into the dining space, making it ideal for hosting dinner parties. The three bathrooms add convenience for busy mornings, while the corner location offers additional privacy and views of the bustling street below. This apartment is not just a place to live; it’s a lifestyle choice that balances comfort and functionality in the heart of Tân Bình.', '{"Chic glass table with vibrant orange accent pillow","Large dining table with dark wooden chairs","Blue patterned bedding on a comfortable bed","Large windows providing ample natural light","Wooden wardrobe with multiple storage compartments"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Parking,Elevator,"Security Camera",sofa,"glass table",pillow,curtains,lighting,Wi-Fi,"dining table","wooden chairs","air conditioning","light fixtures","Air conditioning",bed,bedding,desk,chair,window,Desk,television,"coffee table","decorative plant",Television,wardrobe,tiles}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131790061/0.jp