	('0a320335-44e8-4148-857e-636f400d3821', 'nt130897814', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-3-tp-ho-chi-minh/130897814.htm', 'Charming Fully-Furnished Retreat with Spacious Balcony in Quận 3', 'Đường Cách Mạng Tháng Tám, Phường 11, Quận 3, Tp Hồ Chí Minh', 'ng cch mng thng tm phng 11 qun 3 tp h ch minh', 'ho_chi_minh', 11500000, '11,5 triệu/tháng', '45 m²', 'Step into a charming fully-furnished retreat that exudes warmth and comfort in the heart of Quận 3. This 45 m² one-bedroom apartment is designed for modern living, featuring a spacious balcony that invites natural light and offers a refreshing view. The interior is tastefully decorated with a harmonious blend of contemporary and cozy elements, making it the perfect space for unwinding after a busy day. Imagine sipping your morning coffee while basking in the sunlight or hosting friends in the inviting living area. The well-thought-out layout ensures that every corner is utilized efficiently, enhancing your daily rituals. With a fully equipped kitchen, you can easily prepare meals and enjoy them in the dining nook. The building offers convenient amenities such as a secure entrance, ample parking, and a laundry facility, ensuring a hassle-free living experience. This apartment is not just a place to live; it''s a lifestyle choice that balances comfort and convenience.', '{"Bright dining area with balcony access","Bright and airy living space with expansive windows","Culinary creativity hub with sleek finishes","Sleek kitchen with modern appliances and finishes","Compact dining area perfect for intimate meals"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Elevator,"Security Camera","Dining Table",Chairs,"Ceiling Fan","Wall-mounted Shelves","Balcony Access","Kitchen Counter","Blackout Curtains",Sofa,"Large Windows","Natural Light","Modern Furniture",Stove,Refrigerator,"Kitchen Sink","Kitchen Hood","Kitchen Appliances","Wall Cabinets","Range Hood",Countertops,"Modern Kitchen","Wall Art","Storage Shelves"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130897814/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130897814/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130897814/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130897814/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130897814/4.jpg}', 'Nam', '092546***', NULL, '{"cozy": 6, "urban": 7, "colors": ["Warm", "Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 1, "styles": ["Modern", "Minimalist", "Elegant"], "elegant": 7, "colorful": 4, "spacious": 6, "luxurious": 6, "activities": ["Entertaining", "Relaxing", "Cooking"], "minimalist": 8, "natural_light": 8, "image_analyses": [{"amenities": ["Dining Table", "Chairs", "Ceiling Fan", "Wall-mounted Shelves", "Balcony Access", "Kitchen Counter", "Blackout Curtains"], "image_index": 0, "vibe_scores": {"cozy": 7, "urban": 8, "modern": 9, "elegant": 7, "spacious": 6, "luxurious": 6, "minimalist": 8, "natural_light": 9}, "image_highlight": "Bright dining area with balcony access", "detailed_analysis": "This space features a bright dining area with a sleek black tabletop and stylish wooden chairs that invite comfort and conversation. The large windows flood the room with natural light, creating an airy atmosphere, while the ceiling fan adds a touch of modern convenience. Soft curtains enhance privacy, and the wall-mounted shelves provide functional storage without cluttering the aesthetic. The access to a balcony extends the living space, ideal for enjoying morning coffee or evening relaxation, making this area a perfect blend of functionality and leisure.", "suggested_amenities": ["Dining Table", "Ceiling Fan"], "suggested_activities": ["Entertaining", "Relaxing"]}, {"amenities": ["Dining Table", "Sofa", "Wall-mounted Shelves", "Large Windows"], "image_index": 1, "vibe_scores": {"cozy": 5, "urban": 6, "modern": 8, "elegant": 7, "spacious": 5, "luxurious": 6, "minimalist": 7, "natural_light": 8}, "image_highlight": "Bright and airy living space with expansive windows", "detailed_analysis": "This living area exudes a modern charm with its sleek furniture and expansive windows that invite abundant natural light, creating an uplifting atmosphere. The minimalist design is complemented by the warm tones of the sofa, providing a cozy yet stylish seating option. The seamless flow between the dining area and the living space enhances social interaction, making it ideal for entertaining guests. The overall aesthetic is sophisticated, blending comfort with contemporary elegance, which motivates relaxation and social gatherings.", "suggested_amenities": ["Natural Light", "Modern Furniture"], "suggested_activities": ["Relaxing", "Entertaining"]}, {"amenities": ["Stove", "Refrigerator", "Kitchen Sink", "Kitchen Hood", "Dining Table", "Chairs"], "image_index": 2, "vibe_scores": {"cozy": 5, "urban": 7, "modern": 8, "elegant": 8, "spacious": 6, "luxurious": 7, "minimalist": 9, "natural_light": 10}, "image_highlight": "Culinary creativity hub with sleek finishes", "detailed_analysis": "This kitchen space embodies modern culinary creativity with its sleek, minimalist design. The high-quality finishes, including a stylish kitchen hood and a well-integrated stove, create a functional area perfect for cooking enthusiasts. Ample natural light floods through the large windows, enhancing the atmosphere and providing an inviting space for both cooking and dining. The adjacent dining table encourages social interactions, making it ideal for entertaining guests. The overall layout flows seamlessly, balancing practicality with aesthetic appeal, creating a vibrant hub for culinary experiences.", "suggested_amenities": ["Kitchen Appliances", "Dining Table"], "suggested_activities": ["Cooking", "Entertaining"]}, {"amenities": ["Dining Table", "Chairs", "Refrigerator", "Kitchen Sink", "Stove", "Wall Cabinets", "Range Hood", "Ceiling Fan", "Countertops"], "image_index": 3, "vibe_scores": {"cozy": 7, "urban": 8, "modern": 8, "elegant": 7, "spacious": 7, "luxurious": 6, "minimalist": 9, "natural_light": 6}, "image_highlight": "Sleek kitchen with modern appliances and finishes", "detailed_analysis": "This kitchen area is a sleek culinary haven, featuring modern appliances and elegant finishes. The dark marble dining table complements the contemporary design, creating a sophisticated atmosphere ideal for both cooking and entertaining. Ample storage is provided by the wall cabinets, while the open layout enhances the overall spaciousness. The ceiling fan adds a touch of comfort, ensuring a pleasant cooking environment. The seamless integration of functionality and style makes this kitchen a standout feature in the property.", "suggested_amenities": ["Modern Kitchen", "Stove"], "suggested_activities": ["Cooking", "Entertaining"]}, {"amenities": ["Dining Table", "Sofa", "Ceiling Fan", "Wall Art", "Storage Shelves"], "image_index": 4, "vibe_scores": {"cozy": 6, "urban": 6, "modern": 8, "elegant": 7, "spacious": 6, "luxurious": 5, "minimalist": 7, "natural_light": 7}, "image_highlight": "Compact dining area perfect for intimate meals", "detailed_analysis": "This image captures a compact dining area that exudes modernity and comfort. The minimalist design features a sleek dining table paired with stylish chairs, creating an inviting space for intimate gatherings. The warm tones of the sofa enhance the cozy atmosphere, while the ceiling fan adds a practical touch to keep the air circulating. Decorated with tasteful wall art, this area strikes a perfect balance between aesthetic appeal and functionality, making it ideal for both casual dining and relaxation.", "suggested_amenities": ["Dining Table", "Sofa"], "suggested_activities": ["Entertaining", "Relaxing"]}]}', '2026-04-19 05:32:17.13+00', '2026-06-24 15:31:44.469+00', '2026-06-24 03:00:15.687+00', true, '2026-04-19 05:32:20.528102+00', '2026-06-24 03:00:15.699681+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
