	('ce3e111e-aa02-41ec-a32f-7ef158444058', 'nt129827499', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-go-vap-tp-ho-chi-minh/129827499.htm#px=sr-stickyad-[po-1][pl-top]', 'Fully Furnished Apartment for Rent, 63 m2, 2 Bedrooms, 2 Bathrooms', '359, Phạm Văn Chiêu, Phường 14, Quận Gò Vấp, Tp Hồ Chí Minh', '359 phm vn chiu phng 14 qun g vp tp h ch minh', 'ho_chi_minh', 10000000, '10 triệu/tháng', '63 m²', 'Discover this fantastic opportunity to rent a fully furnished apartment in the I-Home 1 project, located at 359 Phạm Văn Chiêu, P.14, Q. Gò Vấp, TP.HCM, directly opposite Thạch Đà church. This spacious apartment boasts 63m² of living space, featuring a wide and airy balcony perfect for relaxation. It includes two comfortable bedrooms and two modern bathrooms, offering ample space for a small family or professionals. The unit comes with beautiful, complete furnishings, ready for immediate move-in. Enjoy the convenience of a prime location in Gò Vấp, with easy access to local amenities and transportation. Don''t miss out on this well-appointed home!', '{"Stylish dining area with modern pendant lighting","Natural light floods this serene personal retreat","Efficient culinary workspace with modern finishes","Inviting workspace with stylish pendant lighting","Stylish breakfast nook with urban views"}', '{"Fully furnished",Balcony,"2 bedrooms","2 bathrooms","Apartment type: Condominium","Legal documents: Sales contract"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt129827499/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt129827499/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt129827499/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt129827499/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt129827499/4.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt129827499/5.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt129827499/6.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt129827499/7.jpg}', 'Chuyên trang BĐS Tín Phát (Tin Phat REAL ESTATE)', '093300 ***', NULL, '{"colors": [], "styles": [], "activities": [], "image_analyses": [{"image_index": 0, "image_highlight": "Stylish dining area with modern pendant lighting", "suggested_amenities": ["Dining Table", "Pendant Lights"]}, {"image_index": 1, "image_highlight": "Natural light floods this serene personal retreat", "suggested_amenities": ["Large Windows", "Built-in Storage"]}, {"image_index": 2, "image_highlight": "Efficient culinary workspace with modern finishes", "suggested_amenities": ["Kitchen Appliances", "Kitchen Island"]}, {"image_index": 3, "image_highlight": "Inviting workspace with stylish pendant lighting", "suggested_amenities": ["Coffee Maker", "Stylish Light Fixtures"]}, {"image_index": 4, "image_highlight": "Stylish breakfast nook with urban views", "suggested_amenities": ["Bar Stools", "Air Conditioning"]}]}', '2026-04-07 13:31:21.879+00', '2026-06-24 15:31:44.469+00', '2026-06-23 03:00:06.198+00', true, '2026-04-07 13:31:21.910948+00', '2026-06-23 03:00:06.178632+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('f0e2fc57-76f1-43b5-bc85-e724cd8361a8', 'nt132047423', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-go-vap-tp-ho-chi-minh/132047423.htm', 'Charming Urban Retreat in Khang Gia Gò Vấp', '45, Phường 14, Quận Gò Vấp, Tp Hồ Chí Minh', '45 phng 14 qun g vp tp h ch minh', 'ho_chi_minh', 7500000, '7,5 triệu/tháng', '77 m²', 'Step into a charming urban retreat in the heart of Khang Gia Gò Vấp, where modern living meets comfort. This spacious 77 m² apartment features an inviting layout that perfectly balances style and functionality. The open-plan living area is bathed in natural light, creating a warm and welcoming atmosphere ideal for both relaxation and entertaining. Imagine sipping your morning coffee on a cozy couch, surrounded by soft neutral tones and contemporary decor that exudes a sense of calm. The well-designed kitchen invites culinary adventures, while the two bedrooms offer peaceful sanctuaries for restful nights. With ample space for your personal touches, this apartment is perfect for young families or professionals seeking a vibrant community. Experience the joy of living in a space that feels like home from the moment you step inside.', '{"Black and white checkered floor tiles visible","Open shelving unit against the wall","Hello Kitty themed wallpaper with colorful designs","Small blue stool next to the sink area"}', '{"Air Conditioning",WiFi,Elevator,"Security Camera",Fan,"Lighting fixtures",Cabinets,Flooring,"Air conditioning","Laundry facilities","shelving unit","kitchen area","checkered floor",Dishwasher,Microwave,wallpaper,"doorway to bathroom",fan,"Wall decor",sink,"open shelving","storage cabinets","blue stool"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132047423/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132047423/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132047423/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132047423/3.jpg}', 'Trần Minh Trí', '093168 ***', NULL, '{"cozy": 5, "urban": 5, "colors": ["Neutral"], "modern": 5, "rustic": 2, "styles": ["Minimalist"], "elegant": 3, "colorful": 3, "spacious": 5, "amenities": ["Fan", "Wall lights", "Kitchen cabinets", "Checkered floor", "shelving unit", "kitchen area", "black and white floor", "Wall fan", "Bathroom fixtures", "sink", "wooden cabinetry", "counter space"], "luxurious": 3, "activities": ["Working", "Reading", "Relaxing", "Cooking", "Entertaining"], "minimalist": 6, "natural_light": 4, "image_analyses": [{"amenities": ["Fan", "Lighting fixtures", "Cabinets", "Flooring"], "image_index": 0, "vibe_scores": {"cozy": 5, "urban": 5, "modern": 6, "elegant": 4, "spacious": 6, "luxurious": 3, "minimalist": 7, "natural_light": 4}, "image_highlight": "Black and white checkered floor tiles visible", "detailed_analysis": "The image shows a hallway leading to an open kitchen area. The floor features distinctive black and white checkered tiles, adding a unique touch. There are light fixtures on the ceiling, and a fan is positioned on the floor. The walls are painted in light colors, contributing to a bright atmosphere. Various items, including a trash bin and some wooden boards, are visible, indicating ongoing setup or renovation.", "suggested_amenities": ["Air conditioning", "Laundry facilities"], "suggested_activities": ["Working", "Reading", "Relaxing"]}, {"amenities": ["shelving unit", "kitchen area", "checkered floor"], "image_index": 1, "vibe_scores": {"cozy": 4, "urban": 5, "modern": 5, "elegant": 3, "spacious": 5, "luxurious": 3, "minimalist": 6, "natural_light": 4}, "image_highlight": "Open shelving unit against the wall", "detailed_analysis": "The image showcases an open shelving unit against a wall, providing storage and display space. The kitchen area is visible, featuring a simple layout with essential appliances. The black and white checkered floor tiles add a stylish touch, contrasting with the light-colored walls. The overall space appears functional and well-organized, suitable for cooking and entertaining guests.", "suggested_amenities": ["Dishwasher", "Microwave"], "suggested_activities": ["Cooking", "Entertaining"]}, {"amenities": ["wallpaper", "doorway to bathroom", "fan"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 5, "modern": 3, "elegant": 3, "spacious": 3, "luxurious": 2, "minimalist": 5, "natural_light": 4}, "image_highlight": "Hello Kitty themed wallpaper with colorful designs", "detailed_analysis": "The image features a room with a Hello Kitty themed wallpaper, adding a playful and colorful touch. A doorway leads to a bathroom, visible in the background. The flooring appears to be a dark wood, contrasting with the light-colored walls. A fan mounted on the wall suggests a need for ventilation. The overall atmosphere feels cozy, suitable for relaxation or casual activities.", "suggested_amenities": ["Air conditioning", "Wall decor"], "suggested_activities": ["Reading", "Relaxing"]}, {"amenities": ["sink", "open shelving", "storage cabinets", "blue stool"], "image_index": 3, "vibe_scores": {"cozy": 6, "urban": 6, "modern": 5, "elegant": 3, "spacious": 5, "luxurious": 2, "minimalist": 4, "natural_light": 4}, "image_highlight": "Small blue stool next to the sink area", "detailed_analysis": "The image showcases a compact kitchen area featuring a black and white checkered floor. A small blue stool is positioned next to the sink, providing a casual seating option. Above the sink, there are open shelving units for storage, while additional cabinets offer space for kitchen essentials. The walls are painted a light color, contributing to a bright and airy feel, despite the limited natural light coming from the adjacent doorway.", "suggested_amenities": ["Dishwasher", "Microwave"], "suggested_activities": ["Cooking", "Relaxing"]}]}', '2026-04