	('fb5f741e-8545-45af-9c9c-c28ec4ce9841', 'pr45437933', 'batdongsan', 'https://batdongsan.com.vn/cho-thue-can-ho-chung-cu-phuong-long-thanh-my-vinhomes-grand-park/pkd-co-full-gio-hang-60-000-1pn-2pn-3pn-gia-tot-nhat-q9-pr45437933', 'Affordable 1 Bedroom Apartment in Vinhomes Grand Park Q9', 'Vinhomes Grand Park, Hồ Chí Minh', 'vinhomes grand park h ch minh', 'other', 4000000, '4 triệu/tháng', '47', 'This 1-bedroom apartment in Vinhomes Grand Park offers a great living experience with a competitive price. The unit is part of a large inventory of apartments available for rent, ensuring a variety of options for potential tenants. The apartment is well-maintained and comes with essential amenities. The location is convenient, with easy access to local services and facilities.', '{"Stylish wall-mounted TV with scenic view","Serene garden view with natural light","Inviting reading nook with natural light","Artistic entryway with sculptural mirror feature"}', '{"Security service","Air conditioning",Parking}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45437933/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45437933/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45437933/2.jpg}', 'PKD Vinhomes', '0384 541 ***', 'Modern', '{"colors": ["Neutral"], "styles": ["Modern"], "amenities": [], "activities": ["Relaxing"], "image_analyses": [{"image_index": 0, "image_highlight": "Stylish wall-mounted TV with scenic view", "suggested_amenities": ["TV", "Indoor Plants"]}, {"image_index": 1, "image_highlight": "Serene garden view with natural light", "suggested_amenities": ["Large Windows", "Garden View"]}, {"image_index": 2, "image_highlight": "Inviting reading nook with natural light", "suggested_amenities": ["Decorative Shelves", "Potted Plant"]}, {"image_index": 3, "image_highlight": "Artistic entryway with sculptural mirror feature", "suggested_amenities": ["Sculptural Mirror", "Writing Desk"]}]}', '2026-04-07 09:00:45.391+00', '2026-06-24 15:31:44.469+00', '2026-06-22 03:00:10.233+00', true, '2026-04-07 09:00:45.393922+00', '2026-06-22 03:00:10.230087+00', 10.8368595, 106.8303842, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('4e759353-5305-4ede-8ea4-04551ed29069', 'nt131757560', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-ba-dinh-ha-noi/131757560.htm#px=sr-stickyad-[po-1][pl-top]', 'Charming Fully-Furnished 2-Bedroom Retreat in the Heart of Ba Dinh', 'Phố Phan Kế Bính, Phường Cống Vị, Quận Ba Đình, Hà Nội', 'ph phan k bnh phng cng v qun ba nh h ni', 'hanoi', 11000000, '11 triệu/tháng', '50 m²', 'Step into this charming fully-furnished 2-bedroom apartment, where modern comfort meets a cozy atmosphere. The spacious 50 m² layout is designed for both relaxation and productivity, making it perfect for morning coffee rituals or hosting friends for dinner. Natural light floods the living area, highlighting the elegant furnishings and warm color palette that create a welcoming ambiance. The well-equipped kitchen features a stylish induction stove and ample storage, ideal for culinary enthusiasts. With high-end amenities like air conditioning and a washing machine, this apartment ensures a hassle-free living experience. Located in the vibrant Ba Dinh district, you’ll enjoy easy access to local cafes, parks, and cultural landmarks, making it a delightful place to call home.', '{"Stylish built-in storage with large windows","Efficient workspace with built-in storage","Efficient workspace with integrated shelving","Spa-like rain shower experience","Sleek modern bathroom with elegant fixtures"}', '{"Air Conditioning","Washing Machine",WiFi,Elevator,"Built-in Storage","Large Windows","Lighting Fixtures",Desk,"Built-in storage","Shelving units","Accent lighting",Shower,"Bathroom Sink",Toilet,"Storage Shelf","Rain Shower","Modern Vanity",Mirror,"Stylish Shower","Contemporary Sink"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131757560/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131757560/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131757560/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131757560/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131757560/4.jpg}', 'Linh Hoàng', '085742***', NULL, '{"cozy": 4, "urban": 6, "colors": ["Neutral", "Cool", "Refined"], "modern": 8, "rustic": 1, "styles": ["Minimalist", "Modern", "Elegant"], "elegant": 7, "colorful": 2, "spacious": 6, "luxurious": 5, "activities": ["Reading", "Relaxing", "Studying", "Working", "Refreshing showers"], "minimalist": 9, "natural_light": 5, "image_analyses": [{"amenities": ["Air Conditioning", "Built-in Storage", "Large Windows", "Lighting Fixtures"], "image_index": 0, "vibe_scores": {"cozy": 5, "urban": 4, "modern": 8, "elegant": 7, "spacious": 7, "luxurious": 6, "minimalist": 9, "natural_light": 6}, "image_highlight": "Stylish built-in storage with large windows", "detailed_analysis": "This contemporary space exudes a minimalist charm with its clean lines and sleek finishes. The built-in storage seamlessly integrates into the design, offering both functionality and style. Large windows flood the room with natural light, creating an inviting atmosphere perfect for relaxation or reading. The neutral color palette enhances the sense of spaciousness, while modern lighting fixtures add a touch of elegance. The layout promotes a free flow, ensuring comfort and practicality in daily activities.", "suggested_amenities": ["Air Conditioning", "Built-in Storage"], "suggested_activities": ["Reading", "Relaxing"]}, {"amenities": ["Air Conditioning", "Built-in Storage", "Large Windows", "Desk"], "image_index": 1, "vibe_scores": {"cozy": 6, "urban": 6, "modern": 8, "elegant": 7, "spacious": 7, "luxurious": 5, "minimalist": 9, "natural_light": 8}, "image_highlight": "Efficient workspace with built-in storage", "detailed_analysis": "This space embodies a modern minimalist aesthetic, featuring sleek lines and a neutral color palette that promotes a sense of calm. The built-in storage and desk create an efficient workspace, perfect for productivity. Natural light floods the area through large windows, enhancing the open feel and energizing the atmosphere. The air conditioning unit ensures comfort, making this room an ideal setting for focused work or study. The layout promotes a seamless flow, fostering a serene yet functional environment.", "suggested_amenities": ["Built-in Storage", "Desk"], "suggested_activities": ["Studying", "Working"]}, {"amenities": ["Built-in storage", "Desk", "Shelving units", "Accent lighting"], "image_index": 2, "vibe_scores": {"cozy": 4, "urban": 7, "modern": 8, "elegant": 6, "spacious": 6, "luxurious": 5, "minimalist": 9, "natural_light": 3}, "image_highlight": "Efficient workspace with integrated shelving", "detailed_analysis": "This image showcases a well-designed workspace that emphasizes efficiency and functionality. The minimalist aesthetic is defined by sleek lines and a neutral color palette, creating a calming atmosphere. Built-in storage and integrated shelving maximize organization while maintaining a clutter-free environment. The accent lighting adds a touch of sophistication, making this area not just practical but also visually appealing. This space flows seamlessly, inviting productivity and focus for daily tasks.", "suggested_amenities": ["Desk", "Built-in storage"], "suggested_activities": ["Studying", "Working"]}, {"amenities": ["Shower", "Bathroom Sink", "Toilet", "Storage Shelf"], "image_index": 3, "vibe_scores": {"cozy": 3, "urban": 5, "modern": 8, "elegant": 8, "spacious": 6, "luxurious": 7, "minimalist": 9, "natural_light": 4}, "image_highlight": "Spa-like rain shower experience", "detailed_analysis": "This bathroom showcases a spa-like atmosphere with its sleek, modern design featuring beautifully tiled walls and a rain shower that promises an invigorating experience. The minimalist white vanity offers a clean aesthetic, while the ample storage shelf enhances functionality without compromising style. The strategic use of lighting creates a bright, inviting space, perfect for unwinding after a long day. The overall feel is one of tranquility and elegance, making daily routines feel like a luxurious escape.", "suggested_amenities": ["Rain Shower", "Modern Vanity"], "suggested_activities": ["Refreshing showers", "Daily grooming routine"]}, {"amenities": ["Shower", "Bathroom Sink", "Toilet", "Mirror", "Storage Shelf"], "image_index": 4, "vibe_scores": {"cozy": 3, "urban": 6, "modern": 8, "elegant": 5, "spacious": 5, "luxurious": 4, "minimalist": 7, "natural_light": 4}, "image_highlight": "Sleek modern bathroom with elegant fixtures", "detailed_analysis": "This modern bathroom features sleek gray tiles that create a clean and sophisticated aesthetic. The large mirror enhances the sense of space while providing functionality. A stylish shower with a rain feature offers a luxurious bathing experience, transforming daily routines into moments of relaxation. The minimalist design is complemented by practical storage solutions, ensuring everything is organized and easily accessible. The overall atmosphere is one of elegance and efficiency, making it a perfect retreat for daily self-care.", "suggested_amenities": ["Stylish Shower", "Contemporary Sink"], "suggested_activities": ["Refreshing showers", "Grooming routines"]}]}', '2026-04-12 00:31:27.462+00', '2026-06-24 15:31:44.469+00', '2026-06-22 03:00:14.333+00', true, '2026-04-12 00:31:27.44253+00', '2026-06-22 03:00:14.347085+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
