	('4bc9b40b-8293-4824-a1a0-1a4cc26edc00', 'nt130249428', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-4-tp-ho-chi-minh/130249428.htm', 'Apartment for rent in H3, 2 bedrooms, fully furnished, ready to move in', 'Hoàng Diệu, Phường 6, Quận 4, Tp Hồ Chí Minh', 'hong diu phng 6 qun 4 tp h ch minh', 'ho_chi_minh', 15000000, '15 triệu/tháng', '76 m²', 'Discover this fantastic apartment for rent in the H3 condominium, located on Hoàng Diệu, Phường 6, Quận 4, Tp Hồ Chí Minh. Spanning a comfortable 76m², this unit features two well-appointed bedrooms and one bathroom, making it ideal for small families or professionals seeking a spacious living environment. The apartment comes fully furnished, ensuring a hassle-free move-in experience. Situated on a high floor, residents will enjoy beautiful views and a refreshing breeze. The property is meticulously maintained and boasts a lovely design, creating a welcoming and comfortable atmosphere. With its prime location and comprehensive amenities, this apartment offers an excellent opportunity for those looking for quality rental accommodation in Quận 4. Don''t miss out on this chance to live in a vibrant area with easy access to city conveniences. Contact Kiệt for a viewing today!', '{"Abundant natural light with city skyline views","Efficient kitchen layout for culinary creativity","Open layout ideal for social gatherings","Contemporary dining area for social gatherings"}', '{"Fully furnished","2 bedrooms","1 bathroom","High floor","Good view","Legal document: Deposit contract",Bed,Wardrobe,"Large Windows",Curtains,Storage,Refrigerator,Microwave,Stove,"Kitchen Cabinets","Kitchen Sink","Counter Space","Dining Table","Kitchen Appliances","Large Screen TV",Sofa,"Coffee Table",Chandelier,"Dining Chairs","Air Conditioning Unit","Ceiling Lights"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130249428/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130249428/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130249428/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt130249428/3.jpg}', 'Lê Anh Kiệt', '034818 ***', NULL, '{"cozy": 5, "urban": 8, "colors": ["Neutral", "Cool", "Bright"], "modern": 7, "rustic": 2, "styles": ["Urban", "Modern", "Minimalist"], "elegant": 5, "colorful": 3, "spacious": 7, "luxurious": 5, "activities": ["Relaxing", "Reading", "Cooking gourmet meals", "Hosting casual brunches", "Entertaining guests"], "minimalist": 7, "natural_light": 7, "image_analyses": [{"amenities": ["Bed", "Wardrobe", "Large Windows", "Curtains", "Storage"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 8, "modern": 7, "elegant": 5, "spacious": 6, "luxurious": 5, "minimalist": 8, "natural_light": 9}, "image_highlight": "Abundant natural light with city skyline views", "detailed_analysis": "This bedroom radiates tranquility with its abundant natural light pouring in through large windows, offering stunning views of the city skyline. The minimalist design, featuring a simple bed and a wardrobe, creates a serene atmosphere perfect for relaxation. The light-colored walls and flooring enhance the spacious feel, while the soft curtains add a cozy touch. This space invites you to unwind and enjoy a restful retreat amidst urban living, making it an ideal sanctuary for city dwellers.", "suggested_amenities": ["Large Windows", "Wardrobe"], "suggested_activities": ["Relaxing", "Reading"]}, {"amenities": ["Refrigerator", "Microwave", "Stove", "Kitchen Cabinets", "Kitchen Sink", "Counter Space", "Dining Table"], "image_index": 1, "vibe_scores": {"cozy": 4, "urban": 10, "modern": 7, "elegant": 6, "spacious": 8, "luxurious": 5, "minimalist": 6, "natural_light": 9}, "image_highlight": "Efficient kitchen layout for culinary creativity", "detailed_analysis": "This kitchen embodies a blend of functionality and style, featuring a streamlined layout that maximizes space while facilitating culinary creativity. The ample cabinetry provides essential storage, and the large windows bathe the area in natural light, enhancing the inviting atmosphere. The clean lines and modern finishes create a chic aesthetic, making it an ideal space for cooking and entertaining. The layout encourages social interaction, whether hosting friends or enjoying a quiet meal, making it a versatile hub for daily life.", "suggested_amenities": ["Kitchen Appliances", "Dining Table"], "suggested_activities": ["Cooking gourmet meals", "Hosting casual brunches"]}, {"amenities": ["Large Screen TV", "Sofa", "Coffee Table", "Dining Table", "Chandelier", "Curtains"], "image_index": 2, "vibe_scores": {"cozy": 5, "urban": 8, "modern": 7, "elegant": 5, "spacious": 7, "luxurious": 6, "minimalist": 8, "natural_light": 6}, "image_highlight": "Open layout ideal for social gatherings", "detailed_analysis": "This inviting living space features an open layout that encourages social interaction and relaxation. The large screen TV is perfect for entertainment, while the stylish chandelier adds a touch of elegance. Ample natural light floods the room through the windows, creating a warm and welcoming atmosphere. The sleek sofa and coffee table provide comfort and functionality, making it a perfect spot for casual gatherings. The overall minimalist design enhances the spacious feel, inviting renters to envision themselves in a vibrant lifestyle.", "suggested_amenities": ["Dining Table", "Sofa"], "suggested_activities": ["Entertaining guests", "Casual dining"]}, {"amenities": ["Sofa", "Coffee Table", "Dining Table", "Dining Chairs", "Refrigerator", "Air Conditioning Unit", "Ceiling Lights"], "image_index": 3, "vibe_scores": {"cozy": 5, "urban": 7, "modern": 7, "elegant": 4, "spacious": 6, "luxurious": 3, "minimalist": 6, "natural_light": 5}, "image_highlight": "Contemporary dining area for social gatherings", "detailed_analysis": "This space features a contemporary dining area, highlighted by a sleek glass table surrounded by stylish black dining chairs, perfect for social gatherings. The black leather sofa invites relaxation, while the air conditioning unit ensures comfort in warm weather. The light-colored tiled flooring and neutral walls contribute to a spacious, airy atmosphere. Decorative elements, such as the chandelier and wall art, add elegance to the inviting ambiance. The layout encourages interaction, making it ideal for hosting friends or family in a modern setting.", "suggested_amenities": ["Dining Table", "Air Conditioning Unit"], "suggested_activities": ["Hosting dinner parties", "Casual family meals"]}]}', '2026-04-07 10:05:00.641+00', '2026-06-24 15:31:44.469+00', '2026-06-14 03:00:10.055+00', true, '2026-04-07 10:05:00.695389+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('5c5adfd6-fae4-4235-968c-9526cfc11159', 'nt131272745', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-binh-thanh-tp-ho-chi-minh/131272745.htm#px=sr-stickyad-[po-1][pl-top]', 'New 100% Duplex Apartment with Spacious Balcony, Affordable, Near District 1, Phu Nhuan, District 2', 'Bùi Đình Tuý Street, Ward 12, Binh Thanh District, Ho Chi Minh City', 'bi nh tu street ward 12 binh thanh district ho chi minh city', 'ho_chi_minh', 7000000, '7 triệu/tháng', '40 m²', 'This brand new duplex apartment offers a spacious 40 m² layout with a bright and airy balcony, perfect for enjoying the fresh air. Located on Bùi Đình Tuý Street, it is conveniently situated near District 1, making it ideal for those who want to be close to the city''s vibrant life. The apartment features high-end furnishings, a modern design, and a comfortable living space with a high ceiling of 2 meters. Security is a priority with a fingerprint access system, and residents enjoy complete privacy with no shared ownership. The area is well-connected to major districts, making commuting easy and convenient. With a rental price of 7 million VND per month, this apartment is a fantastic deal for anyone looking for quality living in Ho Chi Minh City.', '{"Efficient kitchen layout with modern appliances","Natural light-filled workspace with built-in storage","Versatile loft-style workspace with natural light","Smart storage solutions for efficient living","Bright and airy minimalist living area"}', '{"Air Conditioning","High-speed Internet","Fire Safety System","Security System","Fully Furnished","Natural Light","Modern Fixtures","Storage Cabinets","Lighting Fixtures",Refrigerator,"Washing Machine","Kitchen Cabinets","Kitchen Sink",Countertop,"Kitchen Appliances","Laundry Setup","Large Windows","Built-in Storage","Study Desk",Wardrobe,"Built-in Shelving","Open Floor Plan","High Ceilings","Built-in storage","Sliding wardrobe","Shelf units","Desk area","Storage Cabinet"}', '{https://gbgrwjdmytaksrztcyzs.