	('6b92cdde-3b70-431a-a5a8-8cd16a9d159d', 'nt131787403', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-3-tp-ho-chi-minh/131787403.htm', 'Chic Urban Retreat with Abundant Natural Light near Tao Dan Park', 'Đường Nguyễn Đình Chiểu, Phường 5, Quận 3, Tp Hồ Chí Minh', 'ng nguyn nh chiu phng 5 qun 3 tp h ch minh', 'ho_chi_minh', 7000000, '7 triệu/tháng', '40 m²', 'Step into this chic urban retreat, where modern design meets comfort in a vibrant neighborhood. This 1-bedroom apartment boasts a spacious layout flooded with natural light, thanks to large windows and a welcoming balcony that invites the refreshing breeze. The interior is adorned with high-end furnishings, creating a stylish yet cozy atmosphere perfect for unwinding after a long day. Imagine sipping your morning coffee on the balcony, basking in the sunlight, or hosting friends in the open living space that seamlessly blends relaxation and functionality. The well-equipped kitchen, complete with a refrigerator and convenient washing machine, ensures that daily routines are effortless. Nestled in a secure and peaceful area, this apartment is ideal for professionals or young couples seeking a serene living experience while being just moments away from the lively energy of the city.', '{"Stylish glass wardrobe complements the wooden bed frame.","Neutral tones create a calming atmosphere in the room.","Open kitchen layout with modern appliances enhances convenience.","Large windows provide abundant natural light throughout the space.","Round dining table adds a cozy touch to the kitchen area."}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Refrigerator,Kitchen}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131787403/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131787403/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131787403/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131787403/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131787403/4.jpg}', 'Bảo', '092632***', NULL, '{"colors": [], "styles": [], "activities": [], "image_analyses": [{"image_index": 0, "image_highlight": "Stylish glass wardrobe complements the wooden bed frame.", "suggested_amenities": ["Wardrobe organizers"]}, {"image_index": 1, "image_highlight": "Neutral tones create a calming atmosphere in the room.", "suggested_amenities": ["Soft lighting fixtures"]}, {"image_index": 2, "image_highlight": "Open kitchen layout with modern appliances enhances convenience.", "suggested_amenities": ["Microwave and coffee maker"]}, {"image_index": 3, "image_highlight": "Large windows provide abundant natural light throughout the space.", "suggested_amenities": ["Blackout curtains"]}, {"image_index": 4, "image_highlight": "Round dining table adds a cozy touch to the kitchen area.", "suggested_amenities": ["Tableware and utensils"]}]}', '2026-04-13 00:32:36.117+00', '2026-06-24 15:31:44.469+00', '2026-06-23 03:00:03.097+00', true, '2026-04-13 00:32:42.093887+00', '2026-06-23 03:00:03.091083+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
