	('8a173b74-d4ff-4e14-8bf7-9fe6e6aea625', 'nt131968968', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-3-tp-ho-chi-minh/131968968.htm', 'Charming 1-Bedroom Retreat with Balcony in the Heart of District 3', '413, Đường Lê Văn Sỹ, Phường 14, Quận 3, Tp Hồ Chí Minh', '413 ng l vn s phng 14 qun 3 tp h ch minh', 'ho_chi_minh', 8000000, '8 triệu/tháng', '40 m²', 'Step into this charming 1-bedroom apartment that perfectly blends comfort and style in the vibrant heart of District 3. Bathed in natural light, the space features a cozy layout that includes a private balcony, ideal for sipping morning coffee or unwinding after a long day. The high-end furnishings create a warm and inviting atmosphere, while the thoughtful design ensures that every corner is utilized efficiently. The apartment is equipped with modern amenities, including a washing machine, making it perfect for both short and long stays. Located just steps away from local markets and eateries, this retreat offers a unique opportunity to experience the dynamic lifestyle of Ho Chi Minh City. With security features and easy access to public transport, this apartment is not just a place to live, but a sanctuary to thrive.', '{"Natural light flooding the spacious living area","Inviting lounge area for relaxation and comfort","Inviting lounging area for comfort and conversation","Culinary creativity hub with modern finishes","Inviting balcony with urban city views"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Elevator,"Security Camera",Sofa,Wardrobe,"Large Windows","Coffee Table","Queen Bed","Accent Wall",Bed,Flooring,Curtains,Refrigerator,"Dining Table",Chairs,"Kitchen Cabinets",Stove,Microwave,"Kitchen Appliances","Dining Area","Decorative Ottoman"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131968968/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131968968/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131968968/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131968968/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131968968/4.jpg}', 'Đoàn Vũ Hifriendz', '032526 ***', NULL, '{"cozy": 6, "urban": 6, "colors": ["Warm", "Neutral", "Cool", "Bright", "Refined"], "modern": 7, "rustic": 2, "styles": ["Minimalist", "Modern", "Spacious"], "elegant": 6, "colorful": 3, "spacious": 7, "luxurious": 6, "activities": ["Relaxing", "Reading", "Entertaining", "Cooking"], "minimalist": 8, "natural_light": 7, "image_analyses": [{"amenities": ["Sofa", "Wardrobe", "Air Conditioning", "Balcony", "Large Windows"], "image_index": 0, "vibe_scores": {"cozy": 7, "urban": 7, "modern": 5, "elegant": 4, "spacious": 6, "luxurious": 6, "minimalist": 8, "natural_light": 8}, "image_highlight": "Natural light flooding the spacious living area", "detailed_analysis": "This spacious living area features large windows that flood the room with natural light, creating a bright and airy atmosphere. The modern sofa provides a cozy spot for relaxation, while the sleek wardrobe ensures ample storage without compromising on style. The minimalist design enhances the overall aesthetic, making it an ideal space for unwinding or enjoying leisure activities. The connection to the outside balcony further blurs the lines between indoor and outdoor living, promoting an invigorating lifestyle.", "suggested_amenities": ["Air Conditioning", "Sofa"], "suggested_activities": ["Relaxing", "Reading"]}, {"amenities": ["Sofa", "Coffee Table", "Queen Bed", "Accent Wall"], "image_index": 1, "vibe_scores": {"cozy": 6, "urban": 5, "modern": 7, "elegant": 7, "spacious": 9, "luxurious": 5, "minimalist": 8, "natural_light": 6}, "image_highlight": "Inviting lounge area for relaxation and comfort", "detailed_analysis": "This spacious room features a modern design with minimalistic elements that create a serene atmosphere. The light-colored walls and warm wooden flooring enhance the sense of openness, while the large sofa and coffee table invite comfort and relaxation. The accent wall adds a sophisticated touch, making the space feel unique. The layout encourages easy flow between lounging and resting, making it ideal for those seeking a peaceful retreat. Ample natural light further elevates the mood, creating a welcoming sanctuary.", "suggested_amenities": ["Sofa", "Accent Wall"], "suggested_activities": ["Relaxing"]}, {"amenities": ["Sofa", "Coffee Table", "Bed", "Flooring", "Curtains"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 6, "modern": 8, "elegant": 7, "spacious": 8, "luxurious": 7, "minimalist": 9, "natural_light": 9}, "image_highlight": "Inviting lounging area for comfort and conversation", "detailed_analysis": "This living space exudes a modern yet cozy vibe, featuring a minimalist design with clean lines and a calming color palette. The ample natural light pours in through large windows, enhancing the sense of openness and tranquility. The combination of a spacious bed and a stylish sofa creates an ideal environment for both relaxation and social interaction. The warm wood flooring adds a touch of elegance, while the thoughtfully arranged furniture promotes easy movement and flow, making it perfect for hosting friends or unwinding after a long day.", "suggested_amenities": ["Sofa", "Coffee Table"], "suggested_activities": ["Relaxing", "Entertaining"]}, {"amenities": ["Refrigerator", "Dining Table", "Chairs", "Kitchen Cabinets", "Stove", "Microwave"], "image_index": 3, "vibe_scores": {"cozy": 6, "urban": 7, "modern": 8, "elegant": 6, "spacious": 8, "luxurious": 7, "minimalist": 9, "natural_light": 5}, "image_highlight": "Culinary creativity hub with modern finishes", "detailed_analysis": "This space features a modern kitchen that seamlessly integrates with the dining area, encouraging a culinary creativity hub. The sleek cabinetry and contemporary finishes create a stylish atmosphere, while the ample counter space invites meal prep and entertaining. The open layout enhances flow, allowing for social interactions, and the natural light adds warmth to the inviting ambiance. The dining table, paired with comfortable chairs, fosters shared meals and gatherings, making it a perfect spot for hosting friends or family.", "suggested_amenities": ["Kitchen Appliances", "Dining Area"], "suggested_activities": ["Cooking", "Entertaining"]}, {"amenities": ["Sofa", "Coffee Table", "Balcony", "Large Windows", "Decorative Ottoman"], "image_index": 4, "vibe_scores": {"cozy": 6, "urban": 7, "modern": 7, "elegant": 6, "spacious": 6, "luxurious": 5, "minimalist": 8, "natural_light": 8}, "image_highlight": "Inviting balcony with urban city views", "detailed_analysis": "The image captures a stylish living area featuring a cozy sofa and a chic coffee table. Natural light streams through large windows, enhancing the inviting atmosphere. The adjoining balcony offers stunning urban views, making it a perfect spot for relaxation or entertaining guests. The minimalist decor complements the modern aesthetic, while the warm wooden flooring adds a touch of comfort. This space seamlessly blends functionality with aesthetics, creating a welcoming environment for both unwinding and hosting.", "suggested_amenities": ["Balcony", "Sofa"], "suggested_activities": ["Relaxing", "Entertaining"]}]}', '2026-04-22 00:32:12.519+00', '2026-06-24 15:31:44.469+00', '2026-06-24 03:00:13.196+00', true, '2026-04-22 00:32:19.555466+00', '2026-06-24 03:00:13.209394+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('9b997fb6-0071-4b0a-81d3-08bf78d12f25', 'nt131123241', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-cau-giay-ha-noi/131123241.htm#px=sr-special_display_ad-[po-1][pl-default]', 'Mini Apartment for Rent at 139 Nguyen Ngoc Vu', '18 Alley 139, Nguyen Ngoc Vu Street, Trung Hoa Ward, Cau Giay District, Hanoi', '18 alley 139 nguyen ngoc vu street trung hoa ward cau giay district hanoi', 'hanoi', 6000000, '6 triệu/tháng', '35 m²', 'This newly built mini apartment is located in the heart of Hanoi, specifically in the bustling Cau Giay district. With a spacious area of approximately 35 m², this studio apartment is perfect for individuals or couples looking for a cozy living space. The apartment is fully furnished with modern amenities including air conditioning, a refrigerator, and a water heater. Each room is equipped with an integrated kitchen, allowing for a comfortable living experience without the hassle of sharing facilities. The building offers excellent security features such as fingerprint access, fire alarms, and a spacious parking area. Its prime location provides easy access to major roads, local markets, schools, and supermarkets, making it an ideal choice for working professionals. The rental price is very competitive at just 6 million VND per month, and the owner manages the property directly, ensuring a hassle-free rental process.', '{"Inviting dining nook with natural light","Sleek walk-in shower for rejuvenating experiences","Sleek minimalist kitchen with ample storage"}', '{"Air Conditioning",Refrigerator,"Water Heater","Integrated Kitchen","Fire Safety Systems","Fingerprint Access",WiFi,CCTV,"Free Parking"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131123241/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131123241/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt13