	('495c7d2d-4e67-4942-a303-c68144c81338', 'pr43234157', 'batdongsan', 'https://batdongsan.com.vn/cho-thue-can-ho-chung-cu-vinhomes-central-park-phuong-thanh-my-tay-tp-ho-chi-minh/cho-ch-3pn-120m2-28-trieu-tai-binh-hcm-hot-pr43234157', 'Spacious Urban Retreat with Panoramic Views in Vinhomes Central Park', 'Vinhomes Central Park, Đường Điện Biên Phủ, Phường Thạnh Mỹ Tây, Hồ Chí Minh', 'vinhomes central park ng in bin ph phng thnh m ty h ch minh', 'other', 30000000, '30 triệu/tháng', '120 m²', 'Discover a vibrant urban lifestyle in this spacious 3-bedroom apartment at Vinhomes Central Park. Bathed in natural light, this home offers a serene escape from the city''s hustle while keeping you connected to its pulse. The interior boasts a modern aesthetic with a full range of furnishings, creating a comfortable and stylish living environment. Imagine starting your day with a cup of coffee on the south-facing balcony, enjoying the gentle morning breeze and city views. The generous 120m² layout provides ample space for both relaxation and entertaining, with distinct areas that flow seamlessly, perfect for hosting friends or enjoying quiet family evenings. Residents benefit from exclusive access to a wealth of amenities, including a refreshing outdoor swimming pool, lush green spaces, and a state-of-the-art gym. The secure environment, coupled with the convenience of on-site facilities like Vinschool and Vinmec hospital, ensures a life of ease and comfort. This apartment is more than just a place to live; it''s a canvas for your ideal urban life.', '{"Chic living area with stunning chandelier","Premium living space feature","Breathtaking skyline views from expansive windows","Gourmet kitchen with sleek modern finishes","Sophisticated wine display and storage area"}', '{"Fully Furnished",Parking,"Outdoor Pool","Green Spaces","Commercial Area","Riverside Park",Marina,Gym,Lounge,"Sports Courts",Vinschool,"Vinmec Hospital","24/7 Security","Security Camera","Air Conditioning","Natural Light","Modern Fixtures","Storage Cabinets","Lighting Fixtures"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43234157/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43234157/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43234157/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43234157/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43234157/4.jpg}', 'Thành Phạm Vincentral', '0909638***', NULL, '{"cozy": 6, "urban": 5, "colors": ["Warm", "Cool", "Bright", "Refined"], "modern": 6, "rustic": 4, "styles": ["Modern", "Cozy", "Spacious"], "elegant": 6, "colorful": 5, "spacious": 6, "luxurious": 5, "activities": ["Relaxing", "Living"], "minimalist": 5, "natural_light": 7, "image_analyses": [{"image_index": 0, "image_highlight": "Chic living area with stunning chandelier", "suggested_amenities": ["Chandelier", "Large Screen TV"]}, {"image_index": 1, "image_highlight": "Premium living space feature", "suggested_amenities": ["Air Conditioning", "Natural Light", "Modern Fixtures", "Storage Cabinets", "Lighting Fixtures"]}, {"image_index": 2, "image_highlight": "Breathtaking skyline views from expansive windows", "suggested_amenities": ["Large Windows", "Ceiling Fan"]}, {"image_index": 3, "image_highlight": "Gourmet kitchen with sleek modern finishes", "suggested_amenities": ["Built-in Oven", "Dishwasher"]}, {"image_index": 4, "image_highlight": "Sophisticated wine display and storage area", "suggested_amenities": ["Wine rack", "Storage cabinets"]}]}', '2026-04-14 01:30:42.665+00', '2026-06-24 15:31:44.469+00', '2026-06-23 03:00:13.78+00', true, '2026-04-14 01:30:46.737617+00', '2026-06-23 03:00:13.756801+00', NULL, NULL, '3 Bedrooms', 0, 'alive', NULL, NULL, 0, '