	('c7a6574b-0f3c-47b4-9b52-cf20b4147896', 'nt131022688', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-3-tp-ho-chi-minh/131022688.htm', 'Sunny Urban Retreat Near Hoàng Sa River', 'Đường Hoàng Sa, Phường 11, Quận 3, Tp Hồ Chí Minh', 'ng hong sa phng 11 qun 3 tp h ch minh', 'ho_chi_minh', 5900000, '5,9 triệu/tháng', '25m²', 'Step into this charming studio apartment that bathes in natural light, creating a warm and inviting atmosphere perfect for urban living. The space is thoughtfully designed with a modern aesthetic, featuring soft neutral tones that enhance the feeling of openness. The layout is ideal for both relaxation and productivity, with a cozy nook perfect for morning coffee or a quiet workspace. The large windows not only flood the room with sunlight but also offer a glimpse of the vibrant neighborhood outside. With a full range of amenities, including a well-equipped kitchen and comfortable furnishings, this apartment is perfect for hosting friends or enjoying a peaceful evening at home. Located near the picturesque Hoàng Sa River, you’ll find yourself surrounded by local cafes and shops, making it easy to embrace the lively spirit of Quận 3.', '{"Bright natural light fills the cozy living space.","Minimalist design with a light-colored bed frame.","Compact kitchen area with modern appliances visible.","Sleek cabinetry complements the clean layout.","Open layout enhances the sense of space."}', '{Elevator,"Air Conditioning",WiFi,"Security Camera"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131022688/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131022688/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131022688/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131022688/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131022688/4.jpg}', 'Đồng', '038832 ***', NULL, '{"colors": [], "styles": [], "activities": [], "image_analyses": [{"image_index": 0, "image_highlight": "Bright natural light fills the cozy living space.", "suggested_amenities": ["Large windows", "Comfortable seating"]}, {"image_index": 1, "image_highlight": "Minimalist design with a light-colored bed frame.", "suggested_amenities": ["Bedside table", "Decorative pillows"]}, {"image_index": 2, "image_highlight": "Compact kitchen area with modern appliances visible.", "suggested_amenities": ["Microwave", "Cooking utensils"]}, {"image_index": 3, "image_highlight": "Sleek cabinetry complements the clean layout.", "suggested_amenities": ["Storage solutions", "Countertop appliances"]}, {"image_index": 4, "image_highlight": "Open layout enhances the sense of space.", "suggested_amenities": ["Bar stools", "Decorative plants"]}]}', '2026-04-13 00:32:14.598+00', '2026-06-24 15:31:44.469+00', '2026-06-23 03:00:05.431+00', true, '2026-04-13 00:32:18.183046+00', '2026-06-23 03:00:05.41055+00', NULL, NULL, 'Studio', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
