	('1c98bbe9-70f0-482d-848b-a8d4d475db00', 'nt131633508', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-dong-da-ha-noi/131633508.htm#px=sr-stickyad-[po-1][pl-top]', 'Charming Urban Retreat in the Heart of Đống Đa', '505 E1, Khu TT Văn Chương, Phường Văn Chương, Quận Đống Đa, Hà Nội', '505 e1 khu tt vn chng phng vn chng qun ng a h ni', 'hanoi', 6000000, '6 triệu/tháng', '45 m²', 'Step into this charming urban retreat, where modern comfort meets a vibrant atmosphere in the heart of Đống Đa. This beautifully designed apartment features two cozy bedrooms, perfect for unwinding after a long day. The space is bathed in natural light, creating a warm and inviting ambiance that is ideal for both relaxation and productivity. The open layout seamlessly connects the living area with a well-equipped kitchen, making it easy to host friends or enjoy a quiet morning coffee on the south-facing balcony. With thoughtful touches like air conditioning and ample storage, this apartment is designed for a hassle-free lifestyle. Located just 50 meters from Hồ Linh Quang, you can enjoy leisurely strolls by the water or take advantage of nearby amenities, including schools and local markets. Experience the perfect blend of comfort and convenience in this delightful home.', '{"Expansive wooden wardrobe for organized living","Inviting hallway with classic wooden doors","Warm wooden cabinetry with charming design elements","Functional bathroom with efficient layout"}', '{"Air Conditioning","Hot Water",Balcony,Wardrobe,"Kitchen Cabinet","24/7 Motorcycle Parking","Wooden Flooring",Curtains,Doors,Windows,"Light Fixtures",Flooring,"Wall Decor","Classic Doors","Natural Light","Wooden Cabinets","Kitchen Sink","Wall-mounted Rack","Kitchen Cabinets","Storage Space","Bathroom Sink",Shower,Toilet,"Storage Cabinets"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131633508/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131633508/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131633508/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131633508/3.jpg}', 'Owner', '091309****', NULL, '{"cozy": 6, "urban": 4, "colors": ["Warm", "Neutral"], "modern": 3, "rustic": 4, "styles": ["Cozy", "Minimalist"], "elegant": 4, "colorful": 3, "spacious": 5, "luxurious": 3, "activities": ["Relaxing", "Entertaining", "Cooking"], "minimalist": 6, "natural_light": 4, "image_analyses": [{"amenities": ["Wardrobe", "Wooden Flooring", "Curtains"], "image_index": 0, "vibe_scores": {"cozy": 7, "urban": 4, "modern": 3, "elegant": 4, "spacious": 4, "luxurious": 2, "minimalist": 5, "natural_light": 5}, "image_highlight": "Expansive wooden wardrobe for organized living", "detailed_analysis": "This space features an expansive wooden wardrobe that provides ample storage, enhancing organization and decluttering. The warm wood tones create a cozy atmosphere, complemented by natural light streaming through the window. The flooring adds a touch of elegance, while the layout promotes a sense of tranquility. The soft curtains enhance privacy while allowing light to filter in, making it a serene retreat for relaxation or reflection. Overall, this room is designed for both functionality and comfort, making it an ideal personal sanctuary.", "suggested_amenities": ["Wardrobe", "Wooden Flooring"], "suggested_activities": ["Relaxing"]}, {"amenities": ["Doors", "Windows", "Light Fixtures", "Flooring", "Wall Decor"], "image_index": 1, "vibe_scores": {"cozy": 6, "urban": 4, "modern": 3, "elegant": 3, "spacious": 5, "luxurious": 4, "minimalist": 7, "natural_light": 5}, "image_highlight": "Inviting hallway with classic wooden doors", "detailed_analysis": "This inviting hallway features classic wooden doors with glass insets, creating a warm and welcoming atmosphere. The patterned wallpaper adds a touch of charm, while the well-placed light fixtures ensure the space is bright and cheerful. The layout encourages flow between rooms, enhancing connectivity and making it an ideal setting for casual gatherings. The combination of natural light and cozy decor sets a serene mood, perfect for unwinding or welcoming guests.", "suggested_amenities": ["Classic Doors", "Natural Light"], "suggested_activities": ["Relaxing", "Entertaining"]}, {"amenities": ["Wooden Cabinets", "Kitchen Sink", "Wall-mounted Rack"], "image_index": 2, "vibe_scores": {"cozy": 7, "urban": 4, "modern": 3, "elegant": 5, "spacious": 5, "luxurious": 4, "minimalist": 6, "natural_light": 3}, "image_highlight": "Warm wooden cabinetry with charming design elements", "detailed_analysis": "This kitchen features warm wooden cabinetry that exudes a cozy charm, perfectly blending functionality with aesthetics. The intricate glass designs on the cabinet doors add a touch of elegance, while the practical layout encourages culinary creativity. Ample storage solutions, including a wall-mounted rack for utensils, enhance efficiency. The vibrant wall decor, depicting bottles and fruits, injects personality into the space, creating an inviting atmosphere. This kitchen not only serves as a cooking haven but also as a welcoming space for entertaining guests.", "suggested_amenities": ["Kitchen Cabinets", "Storage Space"], "suggested_activities": ["Cooking", "Entertaining"]}, {"amenities": ["Bathroom Sink", "Shower", "Toilet", "Storage Cabinets"], "image_index": 3, "vibe_scores": {"cozy": 5, "urban": 3, "modern": 3, "elegant": 2, "spacious": 4, "luxurious": 2, "minimalist": 6, "natural_light": 4}, "image_highlight": "Functional bathroom with efficient layout", "detailed_analysis": "This bathroom showcases an efficient layout, with a functional shower and a well-placed bathroom sink. The subtle use of storage cabinets maximizes space, making it ideal for organized living. The light-colored tiles enhance the feeling of brightness and cleanliness, creating an inviting atmosphere. The combination of practicality and simplicity makes this bathroom a refreshing personal retreat, allowing for quick morning routines or evening unwinding moments.", "suggested_amenities": ["Bathroom Sink", "Storage Cabinets"], "suggested_activities": ["Relaxing"]}]}', '2026-04-20 03:02:28.673+00', '2026-06-24 15:31:44.469+00', '2026-06-24 03:00:08.588+00', true, '2026-04-20 03:02:32.553058+00', '2026-06-24 03:00:08.608555+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
