	('b9113797-59fb-4872-89d7-a9de1a437eba', 'nt131684845', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-go-vap-tp-ho-chi-minh/131684845.htm#px=sr-special_display_ad-[po-1][pl-default]', 'Charming Mini Apartment with Modern Touches in Gò Vấp', '172, Đường Huỳnh Văn Nghệ, Phường 12, Quận Gò Vấp, Tp Hồ Chí Minh', '172 ng hunh vn ngh phng 12 qun g vp tp h ch minh', 'ho_chi_minh', 5500000, '5,5 triệu/tháng', '30m²', 'Step into this charming mini apartment that perfectly balances modern aesthetics with cozy living. The space is bathed in natural light, creating a warm and inviting atmosphere ideal for both relaxation and productivity. With a stylishly designed living area that features a brand-new sofa, this apartment is perfect for hosting friends or enjoying a quiet evening at home. The layout includes a well-appointed bedroom that offers a peaceful retreat after a long day. Enjoy your morning coffee in the comfort of your own space, and take advantage of the convenient washing machine to keep your laundry hassle-free. Located on the bustling Huỳnh Văn Nghệ street, you''ll have easy access to local amenities while enjoying the tranquility of your own private oasis.', '{"Bright, airy living space with modern decor","Inviting lounge area with artistic decor","Efficient culinary workspace with modern appliances","Efficient workspace for productivity and focus","Sleek modern bathroom with elegant finishes"}', '{"Washing Machine",Sofa,Parking,"Air Conditioning",Bed,"Coffee Table","Dining Table",Chairs,Artwork,Curtains,"Wall Art","Comfortable Sofa",Refrigerator,"Kitchen Cabinets",Stove,"Kitchen Hood","Kitchen Appliances","Dining Space",Wardrobe,Desk,Chair,"Storage Cabinet",Toilet,"Bathroom Sink","Wall Mirror",Cabinet}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131684845/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131684845/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131684845/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131684845/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131684845/4.jpg}', 'Phạm Văn Dũng', '093182 ***', NULL, '{"cozy": 6, "urban": 6, "colors": ["Warm", "Neutral", "Cool", "Refined"], "modern": 7, "rustic": 2, "styles": ["Minimalist", "Modern", "Cozy"], "elegant": 6, "colorful": 4, "spacious": 5, "luxurious": 5, "activities": ["Relaxing", "Entertaining", "Reading", "Cooking meals", "Gathering for meals"], "minimalist": 8, "natural_light": 6, "image_analyses": [{"amenities": ["Air Conditioning", "Bed", "Sofa", "Coffee Table", "Dining Table", "Chairs", "Artwork", "Curtains"], "image_index": 0, "vibe_scores": {"cozy": 7, "urban": 7, "modern": 8, "elegant": 5, "spacious": 5, "luxurious": 4, "minimalist": 9, "natural_light": 6}, "image_highlight": "Bright, airy living space with modern decor", "detailed_analysis": "This living space exudes a bright and airy atmosphere, enhanced by modern decor and a minimalist aesthetic. The combination of natural light streaming through the window and the soft color palette creates a serene environment perfect for both relaxation and social gatherings. The cozy sofa and stylish coffee table invite casual conversations, while the dining area offers functionality for meals or work. Subtle artwork adds personality, making the space feel inviting and personal.", "suggested_amenities": ["Air Conditioning", "Artwork"], "suggested_activities": ["Relaxing", "Entertaining"]}, {"amenities": ["Sofa", "Coffee Table", "Wall Art"], "image_index": 1, "vibe_scores": {"cozy": 8, "urban": 7, "modern": 7, "elegant": 6, "spacious": 6, "luxurious": 5, "minimalist": 9, "natural_light": 6}, "image_highlight": "Inviting lounge area with artistic decor", "detailed_analysis": "This inviting lounge are