	('f4d44268-d4b1-4c34-b21e-88c69160df9e', 'nt131465804', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-7-tp-ho-chi-minh/131465804.htm', 'Mini Studio Apartment with Loft in District 7, Ho Chi Minh City', 'Hẻm 39 Bùi Văn Ba, Phường Tân Thuận Đông, Quận 7, Tp Hồ Chí Minh', 'hm 39 bi vn ba phng tn thun ng qun 7 tp h ch minh', 'ho_chi_minh', 3800000, '3.8 triệu/tháng', '28 m²', 'This charming mini studio apartment is located in the heart of District 7, Ho Chi Minh City. With a size of 28 m², it features a loft area, making it perfect for those looking for a cozy yet functional living space. The apartment is newly renovated and comes fully furnished with essential amenities including a brand new air conditioning unit, a kitchen with a sink, and a separate clean toilet. The apartment is ready for immediate move-in, providing a hassle-free experience for tenants. The surrounding area is vibrant and offers easy access to local shops and public transport.', '{"Lofted sleeping area for maximizing space","Multifunctional space for efficient living","Functional hallway with smart security features"}', '{"Air Conditioning","Fully Furnished",Kitchen,"Private Toilet"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131465804/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131465804/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131465804/2.jpg}', 'Le Thuan', NULL, NULL, '{"colors": [], "styles": [], "activities": [], "image_analyses": [{"image_index": 0, "image_highlight": "Lofted sleeping area for maximizing space", "suggested_amenities": ["Air Conditioning", "Loft Area"]}, {"image_index": 1, "image_highlight": "Multifunctional space for efficient living", "suggested_amenities": ["Kitchen Sink", "Storage Shelves"]}, {"image_index": 2, "image_highlight": "Functional hallway with smart security feat