	('7c286c6b-0e91-43eb-ace8-2a77b215aa6b', 'pr45592067', 'batdongsan', 'https://batdongsan.com.vn/cho-thue-can-ho-chung-cu-xa-song-tu-tay/cho-cc-300m2-gia-thoa-thuan-o-truong-sa-1-pr45592067', 'For Rent: Spacious 300m² Apartment in Song Tử Tây, Trường Sa', 'Song Tử Tây, Trường Sa, Khánh Hòa', 'song t ty trng sa khnh ha', 'other', 0, 'Giá thỏa thuận', '300 m²', 'This spacious 300m² apartment located in Song Tử Tây, Trường Sa, Khánh Hòa is available for rent at a negotiable price. The apartment offers a wide and airy living space, making it an ideal choice for families or individuals looking for comfort. Contact for more details and to arrange a viewing.', '{"Bright and airy open-concept living space","Bright and spacious open kitchen layout","Vibrant workspace with ample storage solutions","Minimalist design with integrated storage solutions"}', '{"Air Conditioning",Parking,Balcony,Security}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45592067/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45592067/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45592067/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45592067/3.jpg}', 'BDS VN', '0368 061 ***', NULL, '{"cozy": 4, "urban": 6, "colors": ["Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 1, "styles": ["Modern", "Minimalist", "Spacious"], "elegant": 6, "colorful": 3, "spacious": 7, "luxurious": 5, "activities": ["Relaxing", "Entertaining", "Cooking", "Working", "Reading"], "minimalist": 8, "natural_light": 8, "image_analyses": [{"amenities": ["Air Conditioning", "Kitchen Island", "Large Windows", "Refrigerator", "Storage Cabinets"], "image_index": 0, "vibe_scores": {"cozy": 3, "urban": 7, "modern": 7, "elegant": 8, "spacious": 8, "luxurious": 6, "minimalist": 8, "natural_light": 9}, "image_highlight": "Bright and airy open-concept living space", "detailed_analysis": "This spacious open-concept living area exudes modern elegance with its sleek design and abundant natural light streaming through large windows. The air conditioning ensures comfort while the kitchen island serves as a perfect centerpiece for culinary creativity and social gatherings. High ceilings contribute to an airy atmosphere, making it an ideal retreat for relaxation or entertaining guests. The neutral color palette enhances the serene ambiance, creating a versatile backdrop for any lifestyle.", "suggested_amenities": ["Kitchen Island", "Storage Cabinets"], "suggested_activities": ["Relaxing", "Entertaining"]}, {"amenities": ["Air Conditioning", "Refrigerator", "Large Windows", "Kitchen Island", "Ceiling Lights"], "image_index": 1, "vibe_scores": {"cozy": 3, "urban": 8, "modern": 8, "elegant": 8, "spacious": 9, "luxurious": 7, "minimalist": 9, "natural_light": 10}, "image_highlight": "Bright and spacious open kitchen layout", "detailed_analysis": "This open kitchen layout exudes a bright and airy atmosphere, enhanced by large windows that flood the space with natural light. The modern design features a sleek kitchen island, promoting both functionality and social interaction, perfect for cooking or entertaining. The neutral color palette and polished floors create a sophisticated yet welcoming environment. The air conditioning unit ensures comfort, making this space ideal for culinary exploration or casual gatherings, all while maintaining a contemporary urban vibe.", "suggested_amenities": ["Kitchen Island", "Air Conditioning"], "suggested_activities": ["Cooking"]}, {"amenities": ["Air Conditioning", "Storage Cabinets", "Desk"], "image_index": 2, "vibe_scores": {"cozy": 5, "urban": 5, "modern": 8, "elegant": 3, "spacious": 4, "luxurious": 2, "minimalist": 6, "natural_light": 6}, "image_highlight": "Vibrant workspace with ample storage solutions", "detailed_analysis": "This vibrant workspace is designed for productivity, featuring bright blue and yellow cabinetry that adds a cheerful touch. The desk area is well-defined, providing an ideal spot for focused work. Ample storage cabinets offer organization solutions, ensuring a clutter-free environment. Natural light floods in, enhancing the uplifting atmosphere while the air conditioning unit ensures comfort year-round. The combination of modern design and functional layout creates an inspiring setting for daily tasks.", "suggested_amenities": ["Home Office Setup", "Storage Space"], "suggested_activities": ["Working"]}, {"amenities": ["Bed with storage drawers", "Window with blinds", "Wood flooring", "Wall-mounted shelf"], "image_index": 3, "vibe_scores": {"cozy": 5, "urban": 3, "modern": 8, "elegant": 5, "spacious": 6, "luxurious": 4, "minimalist": 9, "natural_light": 7}, "image_highlight": "Minimalist design with integrated storage solutions", "detailed_analysis": "This serene bedroom showcases a minimalist design that emphasizes simplicity and functionality. The integrated storage drawers beneath the bed provide clever organization, while the wall-mounted shelf adds a touch of modern elegance. The large window allows natural light to flood the space, creating a bright and airy atmosphere. The warm wood flooring enhances the cozy vibe, making it an inviting retreat for rest and relaxation. The subtle color palette promotes a calming environment, ideal for unwinding after a busy day.", "suggested_amenities": ["Bed with storage drawers", "Wall-mounted shelf"], "suggested_activities": ["Relaxing", "Reading"]}]}', '2026-04-21 00:01:48.217+00', '2026-06-24 15:31:44.469+00', '2026-06-24 03:00:05.124+00', true, '2026-04-21 00:01:51.261975+00', '2026-06-24 03:00:05.148425+00', NULL, NULL, '4+ Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
