	('d29ea910-6db1-48b7-9d74-f6679c2d01b3', 'nt131457791', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-cau-giay-ha-noi/131457791.htm', 'Luxury 2-Bedroom Apartment for Rent in Trung Hoa Area', 'Trung Hoa Street, Yen Hoa Ward, Cau Giay District, Hanoi', 'trung hoa street yen hoa ward cau giay district hanoi', 'hanoi', 8000000, '8 triệu/tháng', '60 m²', 'This luxurious 2-bedroom apartment is located in the desirable Trung Hoa area of Hanoi, offering a spacious 60 m² of living space. The apartment is fully furnished with high-end interiors, ensuring a comfortable and stylish living experience. Surrounded by a vibrant community with high-quality amenities, this apartment is perfect for families or groups looking for a modern living space. The rental price is 8 million VND per month, providing excellent value for such a prime location. Don''t miss the opportunity to make this beautiful apartment your new home!', '{"Abundant natural light and serene urban views","Sleek modern bathroom with elegant fixtures","Efficient built-in storage solutions for organization","Inviting dining area for social gatherings"}', '{"Fully Furnished","High-End Interiors","Nearby Amenities","Large windows","Wooden bed platform","Built-in storage unit",Curtains,"Air conditioning unit","Indoor plants","Bathroom Sink","Modern Toilet",Shower,"Water Heater","Storage Cabinet","Built-in storage cabinets","Large bed frame","Floor-to-ceiling windows","Wooden flooring","Recessed lighting","Storage cabinets","Dining Table",Sofa,"Wall Art","Kitchen Cabinets",Mirror}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131457791/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131457791/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131457791/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131457791/3.jpg}', 'Mr. Chung', NULL, NULL, '{"cozy": 6, "urban": 6, "colors": ["Warm", "Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 2, "styles": ["Minimalist", "Modern", "Elegant"], "elegant": 7, "colorful": 3, "spacious": 6, "luxurious": 6, "activities": ["Morning yoga sessions", "Reading by the window", "Refreshing shower", "Grooming routine", "Organizing personal belongings"], "minimalist": 9, "natural_light": 7, "image_analyses": [{"amenities": ["Large windows", "Wooden bed platform", "Built-in storage unit", "Curtains", "Air conditioning unit", "Indoor plants"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 5, "modern": 8, "elegant": 7, "spacious": 6, "luxurious": 7, "minimalist": 9, "natural_light": 9}, "image_highlight": "Abundant natural light and serene urban views", "detailed_analysis": "This bedroom features a minimalist design with a wooden bed platform and built-in storage, creating a contemporary and spacious feel. The large windows flood the room with natural light, enhancing the tranquil atmosphere and offering serene urban views. Soft curtains add a touch of warmth, while indoor plants contribute to a refreshing ambiance. The overall layout promotes a sense of openness and comfort, ideal for relaxation and rejuvenation.", "suggested_amenities": ["Large windows", "Air conditioning unit"], "suggested_activities": ["Morning yoga sessions", "Reading by the window"]}, {"amenities": ["Bathroom Sink", "Modern Toilet", "Shower", "Water Heater", "Storage Cabinet"], "image_index": 1, "vibe_scores": {"cozy": 4, "urban": 4, "modern": 7, "elegant": 6, "spacious": 6, "luxurious": 5, "minimalist": 8, "natural_light": 5}, "image_highlight": "Sleek modern bathroom with elegant fixtures", "detailed_analysis": "This bathroom showcases a sleek, modern design with elegant fixtures that promote relaxation and functionality. The spacious layout is complemented by a stylish storage cabinet, providing ample space for essentials. The contemporary shower setup and elegant sink create a refreshing daily retreat, while the neutral tones enhance the calming atmosphere. The well-placed lighting adds a touch of sophistication, making it an ideal space for self-care and grooming routines.", "suggested_amenities": ["Shower", "Storage Cabinet"], "suggested_activities": ["Refreshing shower", "Grooming routine"]}, {"amenities": ["Built-in storage cabinets", "Large bed frame", "Floor-to-ceiling windows", "Wooden flooring", "Recessed lighting"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 5, "modern": 8, "elegant": 7, "spacious": 7, "luxurious": 4, "minimalist": 9, "natural_light": 6}, "image_highlight": "Efficient built-in storage solutions for organization", "detailed_analysis": "This space showcases a sleek and modern design, featuring efficient built-in storage that maximizes functionality while maintaining a minimalist aesthetic. The wooden flooring adds warmth, complemented by abundant natural light streaming through the large floor-to-ceiling windows. The recessed lighting enhances the overall ambiance, creating a tranquil atmosphere perfect for relaxation. The layout emphasizes open space, making the room feel larger and more inviting, ideal for both restful retreats and organized living.", "suggested_amenities": ["Storage cabinets", "Large bed frame"], "suggested_activities": ["Organizing personal belongings", "Resting comfortably"]}, {"amenities": ["Dining Table", "Sofa", "Wall Art", "Kitchen Cabinets", "Mirror"], "image_index": 3, "vibe_scores": {"cozy": 7, "urban": 8, "modern": 8, "elegant": 8, "spacious": 6, "luxurious": 6, "minimalist": 9, "natural_light": 7}, "image_highlight": "Inviting dining area for social gatherings", "detailed_analysis": "This image showcases a stylish dining area that seamlessly blends modern design with comfort. The elegant dining table invites shared meals and lively conversations, while the plush sofa provides a cozy corner for relaxation. The warm wooden flooring and soft lighting create an inviting atmosphere, enhancing the overall appeal. Decorative elements like wall art and vibrant floral arrangements add character and warmth, making this space perfect for both entertaining and unwinding. The open layout promotes easy flow between areas, fostering a sense of community and connection.", "suggested_amenities": ["Dining Table", "Sofa"], "suggested_activities": ["Hosting dinner parties", "Casual dining"]}]}', '2026-03-28 09:01:38.84+00', '2026-06-24 15:31:44.469+00', '2026-06-16 03:00:06.303+00', true, '2026-03-28 09:01:38.867697+00', '2026-06-16 03:00:06.283612+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
