	('c834a846-cafd-4f38-9fd2-17347c490a01', 'nt131416728', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-phu-nhuan-tp-ho-chi-minh/131416728.htm', 'Luxury 3-Bedroom Apartment for Rent in Orchard Park View, Phu Nhuan', '130-132 Hồng Hà, Phường 9, Quận Phú Nhuận, Tp Hồ Chí Minh', '130132 hng h phng 9 qun ph nhun tp h ch minh', 'ho_chi_minh', 18000000, '18 triệu/tháng', '90 m²', 'This luxurious apartment in Orchard Park View offers a spacious living area of 90 m², featuring 3 bedrooms and 2 bathrooms. The apartment is well-equipped with modern amenities including air conditioning, a kitchen, and curtains. Enjoy a refreshing breeze from the balcony, and take advantage of the proximity to Tan Son Nhat Airport. The complex provides free amenities such as an infinity pool, gym, and BBQ area, making it an ideal choice for families or professionals seeking comfort and convenience. The property is managed by Novaland, ensuring high-quality living standards.', '{"Bright open layout with stunning city views","Culinary creativity hub with vibrant accents","Elevated urban views from expansive windows","Versatile space for effortless entertaining and gatherings","Spa-inspired shower experience with modern fixtures"}', '{"Air Conditioning",Kitchen,Balcony,"Infinity Pool",Gym,"BBQ Area","Kitchen Sink",Cabinets,Refrigerator,"Large Windows","Natural Light","Kitchen Cabinets",Stove,Countertop,"Exhaust Fan","Modern Kitchen","Kitchen Appliances",TV,Curtains,Oven,"Washing Machine",Dryer,"Dining Table","Lighting Fixtures",Shower,"Bathroom Sink",Toilet,Mirror,"Luxury Shower","Modern Bathroom Fixtures"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131416728/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131416728/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131416728/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131416728/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131416728/4.jpg}', 'Owner', NULL, NULL, '{"cozy": 4, "urban": 7, "colors": ["Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 1, "styles": ["Minimalist", "Modern", "Urban"], "elegant": 6, "colorful": 3, "spacious": 6, "luxurious": 6, "activities": ["Relaxing with a view", "Casual dining", "Cooking gourmet meals", "Entertaining guests", "Relaxing"], "minimalist": 9, "natural_light": 7, "image_analyses": [{"amenities": ["Air Conditioning", "Kitchen Sink", "Cabinets", "Refrigerator", "Large Windows"], "image_index": 0, "vibe_scores": {"cozy": 5, "urban": 6, "modern": 8, "elegant": 7, "spacious": 8, "luxurious": 7, "minimalist": 9, "natural_light": 9}, "image_highlight": "Bright open layout with stunning city views", "detailed_analysis": "This modern space exudes a bright and airy atmosphere, enhanced by large windows that invite ample natural light. The open layout promotes a seamless transition between living and kitchen areas, making it ideal for casual gatherings. The sleek cabinetry and minimalist design create a sophisticated yet functional environment, perfect for urban living. The elegant tile flooring adds a touch of luxury, while the air conditioning ensures comfort throughout. This space is designed to elevate daily living with both style and practicality.", "suggested_amenities": ["Natural Light", "Air Conditioning"], "suggested_activities": ["Relaxing with a view", "Casual dining"]}, {"amenities": ["Kitchen Cabinets", "Kitchen Sink", "Stove", "Countertop", "Exhaust Fan"], "image_index": 1, "vibe_scores": {"cozy": 5, "urban": 8, "modern": 8, "elegant": 7, "spacious": 5, "luxurious": 6, "minimalist": 9, "natural_light": 6}, "image_highlight": "Culinary creativity hub with vibrant accents", "detailed_analysis": "This kitchen space is a modern culinary creativity hub, featuring sleek cabinetry and a vibrant blue backsplash that energizes the atmosphere. The integration of a stove and sink in a spacious layout offers both functionality and style, making meal preparation a joy. The minimalist design with subtle wood accents provides a warm yet contemporary feel, ideal for both casual cooking and hosting. The efficient use of space ensures that everything is within reach, creating a seamless flow for culinary adventures.", "suggested_amenities": ["Modern Kitchen", "Kitchen Appliances"], "suggested_activities": ["Cooking gourmet meals", "Entertaining guests"]}, {"amenities": ["TV", "Large Windows", "Curtains"], "image_index": 2, "vibe_scores": {"cozy": 4, "urban": 9, "modern": 7, "elegant": 6, "spacious": 6, "luxurious": 5, "minimalist": 8, "natural_light": 8}, "image_highlight": "Elevated urban views from expansive windows", "detailed_analysis": "This space features expansive windows that flood the room with natural light, creating a vibrant and uplifting atmosphere. The sleek, modern design is complemented by dark flooring and minimalist decor, offering a blank canvas for personalization. The room''s layout provides a sense of openness and flow, making it ideal for relaxation or light social gatherings. The urban views serve as an inspiring backdrop, enhancing the overall aesthetic appeal and lifestyle experience.", "suggested_amenities": ["Large Windows", "TV"], "suggested_activities": ["Relaxing", "Enjoying city views"]}, {"amenities": ["Air Conditioning", "Refrigerator", "Oven", "Stove", "Kitchen Cabinets", "Washing Machine", "Dryer", "Dining Table", "Lighting Fixtures"], "image_index": 3, "vibe_scores": {"cozy": 4, "urban": 8, "modern": 8, "elegant": 6, "spacious": 7, "luxurious": 5, "minimalist": 9, "natural_light": 6}, "image_highlight": "Versatile space for effortless entertaining and gatherings", "detailed_analysis": "This versatile living area boasts a bright and airy atmosphere, accentuated by sleek, modern finishes and a minimalist design. The spacious layout allows for seamless flow between entertaining and daily activities, making it an ideal backdrop for gatherings. The combination of natural light and contemporary lighting fixtures creates a warm ambiance, while the integrated kitchen elements like the stove and refrigerator ensure convenience. The neutral color palette enhances the sense of space, contributing to a chic yet inviting vibe.", "suggested_amenities": ["Dining Table", "Air Conditioning"], "suggested_activities": ["Hosting dinner parties", "Casual game nights"]}, {"amenities": ["Shower", "Bathroom Sink", "Toilet", "Mirror"], "image_index": 4, "vibe_scores": {"cozy": 4, "urban": 3, "modern": 7, "elegant": 6, "spacious": 6, "luxurious": 5, "minimalist": 8, "natural_light": 5}, "image_highlight": "Spa-inspired shower experience with modern fixtures", "detailed_analysis": "This bathroom embodies a spa-like atmosphere with its sleek, modern design and high-quality finishes. The spacious shower area, equipped with contemporary fixtures, invites relaxation and rejuvenation. The neutral tones of the tiles create a calming effect, while the well-placed lighting enhances the ambiance. The minimalist layout ensures functionality without clutter, making it an ideal space for daily self-care routines. Overall, this bathroom provides a tranquil escape, elevating the everyday experience into a luxurious ritual.", "suggested_amenities": ["Luxury Shower", "Modern Bathroom Fixtures"], "suggested_activities": ["Refreshing shower", "Self-care routine"]}]}', '2026-03-28 05:31:59.203+00', '2026-06-24 15:31:44.469+00', '2026-06-14 03:00:11.545+00', true, '2026-03-28 05:31:59.317449+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '3 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
