	('0a283481-b937-4f7f-ab76-0e2813be7027', 'nt131978989', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-7-tp-ho-chi-minh/131978989.htm#px=sr-stickyad-[po-1][pl-top]', 'Chic Urban Retreat in Sunshine Sky City with Modern Elegance', '23 Phú Thuận, Phường Tân Phú, Quận 7, Tp Hồ Chí Minh', '23 ph thun phng tn ph qun 7 tp h ch minh', 'ho_chi_minh', 12000000, '12 triệu/tháng', '75 m²', 'Step into a chic urban retreat at Sunshine Sky City, where modern elegance meets comfort. This stylish 2-bedroom apartment boasts a spacious 75 m² layout, designed to enhance your living experience. Natural light floods the open-plan living area, creating a warm and inviting atmosphere perfect for morning coffee or hosting friends. The contemporary design features a soothing color palette with high-end furnishings, ensuring a luxurious feel throughout. Enjoy the convenience of a well-equipped kitchen and cozy bedrooms that promise restful nights. With easy access to local amenities and vibrant city life, this apartment is not just a place to live, but a lifestyle to embrace.', '{"Elegant dining area with luxurious marble flooring","Stunning city view through expansive glass windows","Sleek glass wardrobe enhancing organization and style","Culinary creativity hub with sleek modern finishes"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Parking,Pool,Gym,Elevator,"Security Camera",Refrigerator,"Dining Chairs","Dining Table",Sofa,"Light Fixtures","Marble Flooring","Window Treatments","Large Windows","Wood Paneling",Bed,Nightstand,"Lighting Fixtures",Wardrobe,Lighting,"Wood Flooring","Green Accent Wall","Storage Solutions",Stove,"Kitchen Cabinets",Sink,Microwave}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131978989/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131978989/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131978989/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131978989/3.jpg}', 'Thái Học Jimmy', '070878 ***', NULL, '{"cozy": 5, "urban": 7, "colors": ["Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 1, "styles": ["Modern", "Luxurious", "Elegant"], "elegant": 8, "colorful": 3, "spacious": 6, "luxurious": 8, "activities": ["Entertaining", "Relaxing", "Reading", "Working", "Cooking"], "minimalist": 6, "natural_light": 7, "image_analyses": [{"amenities": ["Refrigerator", "Dining Chairs", "Dining Table", "Sofa", "Light Fixtures", "Marble Flooring", "Window Treatments"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 6, "modern": 8, "elegant": 9, "spacious": 8, "luxurious": 9, "minimalist": 7, "natural_light": 7}, "image_highlight": "Elegant dining area with luxurious marble flooring", "detailed_analysis": "The image showcases an elegantly designed space that combines modern aesthetics with functionality. The luxurious marble flooring reflects light beautifully, enhancing the natural brightness from the large windows. A stylish dining table pairs seamlessly with chic chairs, making it perfect for entertaining. The warm wood accents and contemporary light fixtures create a sophisticated atmosphere, while the open layout encourages effortless flow between areas. This space embodies a stylish yet comfortable environment, ideal for both relaxation and social gatherings.", "suggested_amenities": ["Dining Table", "Marble Flooring"], "suggested_activities": ["Entertaining", "Relaxing"]}, {"amenities": ["Large Windows", "Wood Paneling", "Bed", "Nightstand", "Lighting Fixtures"], "image_index": 1, "vibe_scores": {"cozy": 7, "urban": 6, "modern": 8, "elegant": 7, "spacious": 5, "luxurious": 6, "minimalist": 5, "natural_light": 9}, "image_highlight": "Stunning city view through expansive glass windows", "detailed_analysis": "This bedroom exudes a tranquil urban retreat vibe, featuring expansive glass windows that provide a stunning city view and an abundance of natural light. The modern design is complemented by wood paneling, creating a warm yet sophisticated atmosphere. The plush bed invites relaxation, while the cozy nightstand enhances functionality. The combination of soft lighting and sleek materials fosters a serene ambiance, perfect for unwinding after a long day. The flow of the space promotes a sense of calm, elevating daily living into a restorative experience.", "suggested_amenities": ["Large Windows", "Lighting Fixtures"], "suggested_activities": ["Relaxing", "Reading"]}, {"amenities": ["Wardrobe", "Lighting", "Wood Flooring", "Green Accent Wall", "Storage Solutions"], "image_index": 2, "vibe_scores": {"cozy": 5, "urban": 8, "modern": 8, "elegant": 7, "spacious": 4, "luxurious": 7, "minimalist": 6, "natural_light": 6}, "image_highlight": "Sleek glass wardrobe enhancing organization and style", "detailed_analysis": "This image showcases a sleek glass wardrobe, seamlessly blending modern design with functionality. The wardrobe features ample storage space, ideal for keeping clothing and accessories organized. The green accent wall adds a vibrant touch, infusing energy into the space. Soft lighting enhances the atmosphere, creating a warm, inviting feel. The wood flooring complements the contemporary aesthetic, making this area both stylish and practical. This wardrobe area promotes an organized lifestyle, making daily routines easier and more efficient.", "suggested_amenities": ["Wardrobe", "Lighting"], "suggested_activities": ["Working", "Reading"]}, {"amenities": ["Refrigerator", "Stove", "Kitchen Cabinets", "Sink", "Microwave"], "image_index": 3, "vibe_scores": {"cozy": 3, "urban": 8, "modern": 9, "elegant": 7, "spacious": 6, "luxurious": 8, "minimalist": 7, "natural_light": 5}, "image_highlight": "Culinary creativity hub with sleek modern finishes", "detailed_analysis": "This kitchen epitomizes modern elegance with its sleek cabinetry, polished marble flooring, and high-end appliances. The combination of dark wood and glossy white finishes creates a striking contrast, enhancing the aesthetic appeal. Ample storage solutions ensure efficient organization, while the open layout fosters a seamless cooking experience. The well-lit space, complemented by modern fixtures, encourages creativity and culinary exploration, making it a perfect environment for both novice cooks and seasoned chefs. It''s an inviting atmosphere that transforms daily cooking into a delightful experience.", "suggested_amenities": ["Kitchen Cabinets", "Stove"], "suggested_activities": ["Cooking"]}]}', '2026-04-23 00:05:05.565+00', '2026-06-24 15:31:44.469+00', '2026-06-09 03:00:04.764+00', true, '2026-04-23 00:05:09.041548+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
