nities": ["sofa", "staircase", "fan", "TV stand"], "luxurious": 3, "minimalist": 6, "image_index": 4, "natural_light": 4, "image_highlight": "Red sofa with wooden staircase in background", "detailed_analysis": "The image shows a cozy living area featuring a red sofa and a wooden staircase leading to an upper level. A simple wooden TV stand is positioned against the wall, and a small fan is placed on top. The wooden flooring complements the warm tones of the room, creating an inviting atmosphere. The layout suggests a compact yet functional space, suitable for relaxation or casual gatherings.", "suggested_amenities": ["Air conditioning", "Television"], "suggested_activities": ["Relaxing", "Entertaining"]}]}', '2026-04-26 01:39:20.574+00', '2026-06-24 15:31:44.469+00', '2026-06-09 03:00:13.926+00', true, '2026-04-26 01:39:25.095474+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '3 Bedrooms', 0, 'alive', NULL, NULL, 0, 'complete', false, NULL),
