	('05b43c74-25e5-435d-b082-571a399c869a', 'nt131906014', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-3-tp-ho-chi-minh/131906014.htm#px=sr-stickyad-[po-1][pl-top]', 'Charming Duplex Retreat with Spacious Balcony for Pet Lovers', 'Đường Cách Mạng Tháng 8, Phường 4, Quận 3, Tp Hồ Chí Minh', 'ng cch mng thng 8 phng 4 qun 3 tp h ch minh', 'ho_chi_minh', 6700000, '6,7 triệu/tháng', '45 m²', 'Step into this charming duplex retreat, where spaciousness meets comfort, perfect for pet lovers. The generous balcony invites natural light to flood the living space, creating a warm and inviting atmosphere. The design aesthetic is modern yet cozy, featuring soft color palettes and textures that make you feel right at home. Imagine sipping your morning coffee on the balcony, enjoying the fresh air, or hosting friends in the open living area. The layout is thoughtfully designed to support your daily rituals, whether it’s working from home or unwinding after a long day. With a dedicated washing machine and free parking, this space combines practicality with style, ensuring a delightful living experience in the heart of Quận 3.', '{"Lofted sleeping area with stylish ladder access","Charming dining nook with natural light","Stylish ladder leading to lofted space"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine","Free Parking",Refrigerator,"Dining Table","Ladder to Loft","Lofted Bed","Dining Area",Chairs,"Storage Cabinet","Wall Mirror","Ladder Access","Stylish ladder access","Dining table","Open layout","Stylish Ladder"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131906014/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131906014/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131906014/2.jpg}', 'Huỳnh Kỳ Đức', '070379 ***', NULL, '{"cozy": 6, "urban": 7, "colors": ["Warm", "Neutral", "Cool"], "modern": 7, "rustic": 2, "styles": ["Minimalist", "Modern", "Urban"], "elegant": 5, "colorful": 2, "spacious": 5, "luxurious": 4, "activities": ["Relaxing", "Entertaining", "Reading", "Working"], "minimalist": 8, "natural_light": 6, "image_analyses": [{"amenities": ["Air Conditioning", "Refrigerator", "Dining Table", "Ladder to Loft"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 7, "modern": 7, "elegant": 5, "spacious": 6, "luxurious": 4, "minimalist": 8, "natural_light": 5}, "image_highlight": "Lofted sleeping area with stylish ladder access", "detailed_analysis": "This modern space features a unique lofted sleeping area accessed by a chic ladder, maximizing vertical space and creating a cozy retreat. The sleek air conditioning unit ensures comfort, while the minimalist design promotes an uncluttered lifestyle. Natural light floods the area, enhancing the airy atmosphere. A compact dining table invites social gatherings or cozy meals, making it versatile for both relaxation and entertainment. The overall aesthetic balances modern elegance with functionality, providing a perfect urban sanctuary.", "suggested_amenities": ["Lofted Bed", "Dining Area"], "suggested_activities": ["Relaxing", "Entertaining"]}, {"amenities": ["Dining Table", "Chairs", "Storage Cabinet", "Wall Mirror", "Ladder Access"], "image_index": 1, "vibe_scores": {"cozy": 6, "urban": 7, "modern": 7, "elegant": 5, "spacious": 5, "luxurious": 4, "minimalist": 8, "natural_light": 6}, "image_highlight": "Charming dining nook with natural light", "detailed_analysis": "This inviting space features a charming dining nook with a natural light source, perfect for casual meals or reading. The use of light wood tones on the furniture and flooring creates a warm atmosphere, while the sleek storage cabinet ensures organization without sacrificing style. A minimalist design approach allows for effortless flow, making it ideal for small gatherings or quiet moments. The decorative ladder adds a unique touch, enhancing the urban aesthetic. Overall, this area is a blend of functionality and charm, making it an excellent spot for daily use.", "suggested_amenities": ["Dining Table", "Wall Mirror"], "suggested_activities": ["Entertaining", "Reading"]}, {"amenities": ["Stylish ladder access", "Dining table", "Chairs", "Open layout"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 7, "modern": 8, "elegant": 5, "spacious": 5, "luxurious": 4, "minimalist": 7, "natural_light": 6}, "image_highlight": "Stylish ladder leading to lofted space", "detailed_analysis": "This space exudes a modern, minimalist aesthetic with its sleek lines and open layout. The stylish ladder provides access to a lofted sleeping area, making efficient use of vertical space. Natural light filters in, creating a bright and uplifting atmosphere. The dining nook, with its simple wooden table and chairs, invites cozy meals or focused work sessions. The muted tones and polished flooring enhance the sense of tranquility, while the overall design promotes an effortless flow between areas, making it perfect for both relaxation and productivity.", "suggested_amenities": ["Dining Table", "Stylish Ladder"], "suggested_activities": ["Working", "Reading"]}]}', '2026-04-19 05:32:14.384+00', '2026-06-24 15:31:44.469+00', '2026-06-10 03:00:07.92+00', true, '2026-04-19 05:32:16.625573+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
