": [], "image_analyses": [{"image_index": 0, "image_highlight": "Efficient kitchenette with modern appliances", "suggested_amenities": ["Kitchen Appliances", "Workspace"]}, {"image_index": 1, "image_highlight": "Functional workspace with natural light access", "suggested_amenities": ["Desk", "Air Conditioning"]}, {"image_index": 2, "image_highlight": "Efficient space for personal retreats", "suggested_amenities": ["Comfortable Bed", "Compact Refrigerator"]}, {"image_index": 3, "image_highlight": "Secure parking for effortless commuting and convenience", "suggested_amenities": ["Secure Parking", "Motorcycle Storage"]}]}', '2026-03-28 11:01:48.666+00', '2026-06-24 15:31:44.469+00', '2026-06-14 03:00:04.265+00', true, '2026-03-28 11:01:48.653326+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
