	('d947bcc2-f80b-4925-8c5b-c89775d49e6d', 'nt131511474', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-binh-thanh-tp-ho-chi-minh/131511474.htm#px=sr-stickyad-[po-1][pl-top]', '1 Bedroom Apartment with Full Furnishings - 1km from Hutech University', 'Ung Van Khiem Street, Ward 25, Binh Thanh District, Ho Chi Minh City', 'ung van khiem street ward 25 binh thanh district ho chi minh city', 'ho_chi_minh', 7800000, '7.8 triệu/tháng', '40 m²', 'This charming 1-bedroom apartment is located in Binh Thanh District, just 1km from Hutech University, making it an ideal choice for students or young professionals. The apartment spans 40 square meters and comes fully furnished with high-quality furniture, allowing you to move in with just your suitcase. The corner unit is bright and airy, featuring a balcony that invites natural light and fresh air throughout the day. Security is a priority, with fingerprint access and 24/7 surveillance cameras ensuring your safety. Enjoy the freedom of living without shared ownership, providing you with privacy and comfort. Rent is competitively priced at 7.8 million VND per month, with a deposit of the same amount required. This apartment offers a perfect blend of convenience and comfort in a vibrant neighborhood.', '{"Contemporary dining area with stylish furniture","Minimalist bedroom with natural light and air conditioning","Minimalist design with functional storage solutions","Inviting minimalist bedroom with natural decor","Air-conditioned retreat for restful nights"}', '{"High-end furniture",Balcony,"Fingerprint access","24/7 security cameras","Air Conditioning","Natural Light","Modern Fixtures","Storage Cabinets","Lighting Fixtures"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131511474/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131511474/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131511474/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131511474/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131511474/4.jpg}', 'Anh Kiệt', '036686****', NULL, '{"cozy": 6, "urban": 5, "colors": ["Warm", "Cool", "Bright", "Refined"], "modern": 6, "rustic": 4, "styles": ["Modern", "Cozy", "Spacious"], "elegant": 6, "colorful": 5, "spacious": 6, "luxurious": 5, "activities": ["Relaxing", "Living"], "minimalist": 5, "natural_light": 7, "image_analyses": [{"image_index": 0, "image_highlight": "Contemporary dining area with stylish furniture", "suggested_amenities": ["Stylish Dining Furniture", "Modern Kitchen Appliances"]}, {"image_index": 1, "image_highlight": "Minimalist bedroom with natural light and air conditioning", "suggested_amenities": ["Air Conditioning", "Decorative Plant"]}, {"image_index": 2, "image_highlight": "Minimalist design with functional storage solutions", "suggested_amenities": ["Wardrobe", "Air Conditioning"]}, {"image_index": 3, "image_highlight": "Inviting minimalist bedroom with natural decor", "suggested_amenities": ["Bed", "Indoor Plant"]}, {"image_index": 4, "image_highlight": "Air-conditioned retreat for restful nights", "suggested_amenities": ["Air Conditioning", "Wardrobe"]}]}', '2026-03-30 05:34:44.148+00', '2026-06-24 15:31:44.469+00', '2026-06-16 03:00:12.992+00', true, '2026-03-30 05:34:44.234642+00', '2026-06-16 03:00:12.97151+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('2b2c4d1d-7a57-4825-aa69-2db9e74fe149', 'nt131667933', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-4-tp-ho-chi-minh/131667933.htm', 'Chic Urban Retreat in Grand Riverside with Full Amenities', '278 – 283, Bến Vân Đồn, Phường 2, Quận 4, Tp Hồ Chí Minh', '278 283 bn vn n phng 2 qun 4 tp h ch minh', 'ho_chi_minh', 13000000, '13 triệu/tháng', '50m²', 'Step into a chic urban retreat at Grand Riverside, where modern design meets comfort. This 1-bedroom apartment boasts a spacious 50m² layout, flooded with natural light that dances across the stylish furnishings. The open-plan living area is perfect for morning coffee rituals or cozy evenings with friends, featuring a harmonious blend of contemporary decor and warm textures. The fully equipped kitchen invites culinary adventures, while the inviting bedroom offers a serene escape at the end of the day. With its vibrant location in Quận 4, you''ll enjoy easy access to local cafes and shops, making this space not just a home, but a lifestyle. Experience the perfect balance of relaxation and urban excitement in this beautifully appointed apartment.', '{"Natural light floods the serene bedroom space","Culinary creativity hub with modern finishes","Bright and airy living space with modern furnishings","Functional dining area for shared meals","Sleek modern bathroom with elegant fixtures"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Elevator,"Security Camera","Natural Light","Modern Fixtures","Storage Cabinets","Lighting Fixtures"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131667933/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131667933/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131667933/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131667933/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131667933/4.jpg}', 'Căn hộ giá tốt Quận 4', '096821***', NULL, '{"cozy": 6, "urban": 5, "colors": ["Warm", "Cool", "Bright", "Refined"], "modern": 6, "rustic": 4, "styles": ["Modern", "Cozy", "Spacious"], "elegant": 6, "colorful": 5, "spacious": 6, "luxurious": 5, "activities": ["Relaxing"], "minimalist": 5, "natural_light": 7, "image_analyses": [{"image_index": 0, "image_highlight": "Natural light floods the serene bedroom space", "suggested_amenities": ["Natural Light", "Cozy Bed"]}, {"image_index": 1, "image_highlight": "Culinary creativity hub with modern finishes", "suggested_amenities": ["Modern Kitchen", "Kitchen Appliances"]}, {"image_index": 2, "image_highlight": "Bright and airy living space with modern furnishings", "suggested_amenities": ["Modern Furnishings", "Air Conditioning"]}, {"image_index": 3, "image_highlight": "Functional dining area for shared meals", "suggested_amenities": ["Dining Table", "Air Conditioner"]}, {"image_index": 4, "image_highlight": "Sleek modern bathroom with elegant fixtures", "suggested_amenities": ["Luxury Bathroom", "Modern Fixtures"]}]}', '2026-04-22 01:02:21.619+00', '2026-06-24 15:31:44.469+00', '2026-06-24 03:00:14.024+00', true, '2026-04-22 01:02:26.285506+00', '2026-06-24 03:00:14.063103+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('27762e62-8dd1-4ea0-80fb-0f7417a8d387', 'nt131914591', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-go-vap-tp-ho-chi-minh/131914591.htm#px=sr-stickyad-[po-1][pl-top]', 'Charming Modern Studio with Cozy Ambiance in Gò Vấp', 'Đường số 8, Phường 8, Quận Gò Vấp, Tp Hồ Chí Minh', 'ng s 8 phng 8 qun g vp tp h ch minh', 'ho_chi_minh', 4000000, '4 triệu/tháng', '20 m²', 'Step into this charming modern studio that perfectly balances style and comfort in the heart of Gò Vấp. With a smart layout that maximizes every inch of its 20 m², this space is designed for both relaxation and productivity. The interior features a soothing color palette with warm tones, complemented by high-end furnishings that invite you to unwind after a long day. Natural light floods through the windows, creating a bright and airy atmosphere ideal for morning coffee rituals or cozy evenings with a book. The well-equipped kitchenette allows for easy meal prep, while the dedicated workspace is perfect for remote work or study sessions. Enjoy the freedom of a private bathroom and the convenience of nearby amenities, including local markets and the serene Chùa Nghệ Sĩ. This studio is not just a place to live; it''s a lifestyle choice that embraces comfort, security, and modern living.', '{"Comfortable space with modern amenities and decor","Compact workspace for productivity and focus","Invigorating rain shower for daily rejuvenation","Bright, airy workspace with natural light","Convenient kitchenette for effortless meal prep"}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Parking,"Security Camera",Television,Refrigerator,Bed,"Dining Table","Storage Shelf",Chairs,"Wall Mirror",Desk,"Rain Shower","Bathroom Sink","Modern Toilet",Mirror,"Towel Rack","Luxury Bathroom","Modern Fixtures","Storage Cabinet","Smart TV","Kitchen Sink","Built-in Storage",Kitchenette}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131914591/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131914591/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131914591/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131914591/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131914591/4.jpg}', 'Lê Hữu Kiên', '097434***', NULL, '{"cozy": 5, "urban": 7, "colors": ["Neutral", "Cool"], "modern": 7, "rustic": 2, "styles": ["Modern", "Minimalist", "Urban"], "elegant": 5, "colorful": 4, "spacious": 5, "luxurious": 4, "activities": ["Relaxing", "Working", "Reading", "Cooking"], "minimalist": 7, "natural_light": 5, "image_analyses": [{"amenities": ["Air Conditioning", "Television", "Refrigerator", "Bed", "Dining Table", "Storage Shelf"], "image_index": 0, "vibe_scores": {"cozy": 5, "urban": 7, "modern": 7, "elegant": 4, "spacious": 5, "luxurious": 3, "minimalist": 8, "natural_light": 6}, "image_highlight": "Comfortable space with modern amenities and decor", "detailed_analysis": "This compact living space offers a blend of modern amenities and a cozy atmosphere. The light color palette and the use of wood accents create a calming environment. Features like the air conditioning unit and television enhance comfort, while the neatly arranged bed and dining table promote efficient use of space. The large window allows natural light to flood in, further brightening the area. Overall, this room serves as a practical sanctuary for relaxation or focused work.", "suggested_amenities": ["Air Conditioning", "Television"], "suggested_activities": ["Relaxing", "Working"]}, {"amenities": ["Air Conditioning", "Television", "Dining Table", "Chairs", "Wall Mirror"], "image_index": 1, "vibe_scores": {"cozy": 7, "urban": 7, "modern": 8, "elegant": 4, "spacious": 6, "luxurious": 4, "minimalist": 9, "natural_light": 5}, "image_highlight": "Compact workspace for productivity and focus", "detailed_analysis": "This contemporary space features a minimalist design with a focus on functionality. The air conditioning ensures comfort, while the compact dining table and chairs create an inviting nook for work or study. The wall mirror adds depth and light, enhancing the sense of space. Neutral tones and modern furnishings promote an atmosphere of calm and clarity, making it an ideal setting for productivity. The layout flows smoothly, providing a seamless transition between relaxation and work.", "suggested_amenities": ["Desk", "Air Conditioning"], "suggested_activities": ["Working", "Reading"]}, {"amenities": ["Rain Shower", "Bathroom Sink", "Modern Toilet", "Mirror", "Towel Rack"], "image_index": 2, "vibe_scores": {"cozy": 3, "urban": 5, "modern": 7, "elegant": 7, "spacious": 4, "luxurious": 5, "minimalist": 8, "natural_light": 6}, "image_highlight": "Invigorating rain shower for daily rejuvenation", "detailed_analysis": "This bathroom features a sleek design with a refreshing rain shower, offering an invigorating experience that transforms daily routines into a spa-like retreat. The modern fixtures, including a stylish round mirror and well-placed towel rack, enhance functionality while maintaining a minimalist aesthetic. Large windows bring in natural light, creating a bright atmosphere that uplifts the mood. The use of neutral tones in the tiles further contributes to a calming environment, making this space perfect for moments of relaxation and self-care.", "suggested_amenities": ["Luxury Bathroom", "Modern Fixtures"], "suggested_activities": ["Relaxing", "Reading"]}, {"amenities": ["Air Conditioning", "Television", "Refrigerator", "Storage Cabinet", "Dining Table", "Chairs"], "image_index": 3, "vibe_scores": {"cozy": 5, "urban": 7, "modern": 7, "elegant": 5, "spacious": 5, "luxurious": 4, "minimalist": 6, "natural_light": 8}, "image_highlight": "Bright, airy workspace with natural light", "detailed_analysis": "This bright and airy workspace is designed for productivity, featuring large windows that invite abundant natural light. The modern air conditioning unit ensures comfort, while the minimalist decor keeps distractions at bay. A small dining table paired with sleek chairs creates an inviting nook for casual meals or brainstorming sessions. The warm wooden accents of the storage cabinet add a touch of warmth to the space, making it feel more personal. Overall, the layout flows well, catering to both work and relaxation needs.", "suggested_amenities": ["Air Conditioning", "Dining Table"], "suggested_activities": ["Working", "Reading"]}, {"amenities": ["Air Conditioning", "Smart TV", "Refrigerator", "Kitchen Sink", "Built-in Storage"], "image_index": 4, "vibe_scores": {"cozy": 4, "urban": 7, "modern": 8, "elegant": 4, "spacious": 5, "luxurious": 3, "minimalist": 6, "natural_light": 2}, "image_highlight": "Convenient kitchenette for effortless meal prep", "detailed_analysis": "This compact kitchenette showcases modern functionality, featuring a sleek countertop and essential appliances for everyday cooking. The smart TV mounted on the wall adds entertainment convenience, creating an inviting atmosphere for relaxation. Clean lines and neutral colors enhance the minimalist aesthetic, while the air conditioning unit ensures comfort year-round. The layout promotes efficient use of space, making it ideal for quick meal preparations or casual dining experiences, making this area a practical hub for culinary creativity.", "suggested_amenities": ["Kitchenette", "Air Conditioning"], "suggested_activities": ["Cooking"]}]}', '2026-04-20 01:32:21.571+00', '2026-06-24 15:31:44.469+00', '2026-06-11 03:00:08.643+00', true, '2026-04-20 01:32:25.696296+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, 'Studio', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
