7, "colors": ["Warm", "Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 1, "styles": ["Modern", "Elegant", "Luxurious"], "elegant": 8, "colorful": 3, "spacious": 6, "luxurious": 7, "activities": ["Relaxing", "Entertaining", "Getting ready", "Working from home", "Hosting movie nights"], "minimalist": 7, "natural_light": 8, "image_analyses": [{"amenities": ["Large Screen TV", "Air Conditioning", "Sofa", "Coffee Table", "Dining Table", "Curtains", "Natural Light", "Storage Cabinet"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 7, "modern": 8, "elegant": 8, "spacious": 6, "luxurious": 7, "minimalist": 5, "natural_light": 9}, "image_highlight": "Expansive glass doors for natural light infusion", "detailed_analysis": "This contemporary living space features a stylish brown leather sofa, complemented by a sleek black coffee table that enhances its modern aesthetic. Expansive glass doors allow abundant natural light to flood the room, creating a bright and inviting atmosphere. The elegant decor, including wall-mounted lighting and soft curtains, adds a touch of sophistication. The open layout seamlessly connects the living area to the dining space, making it ideal for relaxation and social gatherings. The warm wood flooring contributes to a cozy yet upscale environment.", "suggested_amenities": ["Large Screen TV", "Air Conditioning"], "suggested_activities": ["Relaxing", "Entertaining"]}, {"amenities": ["Built-in Wardrobe", "Desk with Mirror", "Wall-mounted Lighting", "Blackout Curtains"], "image_index": 1, "vibe_scores": {"cozy": 6, "urban": 6, "modern": 8, "elegant": 8, "spacious": 5, "luxurious": 7, "minimalist": 9, "natural_light": 4}, "image_highlight": "Sleek vanity setup with illuminated mirror", "detailed_analysis": "This space embodies a modern minimalist aesthetic with its sleek built-in wardrobe and desk combination. The illuminated mirror adds a touch of elegance, creating a perfect vanity spot for daily routines. The black and gray color scheme exudes sophistication, while the functional layout maximizes space efficiency. The room is designed for comfort and productivity, making it ideal for both relaxation and work. The subtle lighting enhances the atmosphere, making it feel inviting and stylish.", "suggested_amenities": ["Desk with Mirror", "Built-in Wardrobe"], "suggested_activities": ["Getting ready", "Working from home"]}, {"amenities": ["Smart TV", "Entertainment Center", "Coffee Table", "Large Windows", "Curtains"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 9, "modern": 8, "elegant": 9, "spacious": 8, "luxurious": 9, "minimalist": 7, "natural_light": 10}, "image_highlight": "Seamless indoor-outdoor living experience", "detailed_analysis": "This living space showcases a modern design with large floor-to-ceiling windows that invite natural light and present stunning outdoor views, creating a vibrant atmosphere. The sleek, contemporary furnishings, including a minimalist coffee table and plush seating, enhance both comfort and style. The integrated Smart TV acts as a focal point for entertainment, perfect for social gatherings or relaxing evenings. The flow of the space promotes a seamless indoor-outdoor lifestyle, making it ideal for both relaxation and entertaining guests.", "suggested_amenities": ["Smart TV", "Large Windows"], "suggested_activities": ["Hosting movie nights", "Relaxing with panoramic views"]}, {"amenities": ["Refrigerator", "Built-in Oven", "Stove", "Dishwasher", "Kitchen Island", "Kitchen Sink", "Countertop", "Lighting Fixtures"], "image_index": 3, "vibe_scores": {"cozy": 4, "urban": 6, "modern": 8, "elegant": 8, "spacious": 7, "luxurious": 7, "minimalist": 6, "natural_light": 5}, "image_highlight": "Sleek kitchen island with modern finishes", "detailed_analysis": "This kitchen stands out with its sleek island featuring modern finishes and a sophisticated color palette. The black refrigerator and built-in appliances complement the elegant cabinetry and stylish countertop, creating a visually appealing culinary workspace. Ample storage above and below enhances functionality, while the clean lines and minimalist design evoke a sense of order and efficiency. The combination of practical layout and aesthetic appeal fosters an environment perfect for culinary exploration and social gatherings, making it a true chef''s paradise.", "suggested_amenities": ["Kitchen Appliances", "Modern Countertops"], "suggested_activities": ["Cooking gourmet meals", "Entertaining guests"]}, {"amenities": ["Large Windows", "Built-in Storage", "Queen Bed", "Natural Light"], "image_index": 4, "vibe_scores": {"cozy": 6, "urban": 8, "modern": 8, "elegant": 7, "spacious": 5, "luxurious": 7, "minimalist": 9, "natural_light": 10}, "image_highlight": "Inviting natural light-filled bedroom sanctuary", "detailed_analysis": "This bedroom emanates tranquility and sophistication with its expansive windows that invite abundant natural light, creating an uplifting ambiance. The minimalist design features a sleek built-in storage unit, maximizing functionality while maintaining an uncluttered aesthetic. The warm wooden flooring adds a touch of coziness, enhancing the serene atmosphere. This space is perfect for unwinding after a long day or starting mornings with invigorating light, offering a sense of calm and rejuvenation.", "suggested_amenities": ["Natural Light", "Built-in Storage"], "suggested_activities": ["Reading", "Morning yoga"]}]}', '2026-04-07 10:30:36.696+00', '2026-06-24 15:31:44.469+00', '2026-06-13 03:00:05.121+00', true, '2026-04-07 10:30:36.675351+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
