	('53686c1f-bd8e-4dce-a158-f35665d92be2', 'pr43749339', 'batdongsan', 'https://batdongsan.com.vn/cho-thue-nha-rieng-duong-bach-dang-phuong-bach-mai-4/cho-xay-theo-kieu-biet-thu-san-vuon-pr43749339', 'Charming Garden Villa for Rent in Bạch Mai', '39 ngõ 402 phố Bạch Mai, Hai Bà Trưng, Hà Nội', '39 ng 402 ph bch mai hai b trng h ni', 'hanoi', 20000000, '20 triệu/tháng', '84', 'This stunning garden villa is available for rent, located in a peaceful area near the National Economics University. The villa features 5 bedrooms, a spacious living area, and a beautiful garden. Ideal for families looking for a serene living environment.', '{"Stylish security gate with elegant design","Inviting entryway with natural light infusion","Natural light-filled versatile living space"}', '{Garden,Balcony,Parking,"Security Gate","Outdoor Lighting",Fencing,Entrance,Staircase,"Checkered Floor","Large Windows",Bathroom,"AC Unit","Wood Flooring","Natural Light"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43749339/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43749339/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43749339/2.jpg}', 'Hiền Nguyễn', '0943 160 ***', NULL, '{"cozy": 4, "urban": 4, "colors": ["Neutral", "Warm"], "modern": 3, "rustic": 1, "styles": ["Spacious"], "elegant": 3, "colorful": 1, "spacious": 6, "luxurious": 3, "activities": ["Relaxing", "Entertaining", "Reading"], "minimalist": 5, "natural_light": 5, "image_analyses": [{"amenities": ["Security Gate", "Outdoor Lighting", "Fencing", "Entrance"], "image_index": 0, "vibe_scores": {"cozy": 5, "urban": 5, "modern": 3, "elegant": 3, "spacious": 6, "luxurious": 4, "minimalist": 2, "natural_light": 2}, "image_highlight": "Stylish security gate with elegant design", "detailed_analysis": "The entrance features a stylish security gate that combines elegance with functionality, creating a welcoming aesthetic. The intricate designs and sturdy construction offer both security and visual appeal. The surrounding light fixtures enhance the ambiance, ensuring safety and charm during evening hours. The blend of materials and colors adds to the overall urban feel, making it a distinctive entry point that stands out from typical entrances.", "suggested_amenities": ["Security Gate", "Outdoor Lighting"], "suggested_activities": ["Relaxing"]}, {"amenities": ["Staircase", "Checkered Floor", "Large Windows", "Bathroom"], "image_index": 1, "vibe_scores": {"cozy": 2, "urban": 3, "modern": 3, "elegant": 4, "spacious": 6, "luxurious": 2, "minimalist": 4, "natural_light": 5}, "image_highlight": "Inviting entryway with natural light infusion", "detailed_analysis": "This entryway features a spacious layout with a stylish checkered floor that combines elegance with a modern flair. The large windows invite an abundance of natural light, creating an uplifting atmosphere perfect for welcoming guests. The clean lines of the staircase add a sense of sophistication, while the warm wall colors contribute to a cozy yet refined feel. This space serves as an ideal transition point, setting the tone for relaxation or entertaining, with a seamless flow into connected areas.", "suggested_amenities": ["Large Windows", "Checkered Floor"], "suggested_activities": ["Relaxing", "Entertaining"]}, {"amenities": ["AC Unit", "Large Windows", "Wood Flooring"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 4, "modern": 3, "elegant": 2, "spacious": 5, "luxurious": 2, "minimalist": 8, "natural_light": 7}, "image_highlight": "Natural light-filled versatile living space", "detailed_analysis": "This versatile living space is bathed in natural light, creating a warm and inviting atmosphere. The wood flooring adds a touch of coziness, while the large windows allow for a seamless connection with the outside world. The minimalist design encourages creativity and personalization, making it an ideal backdrop for relaxation or focused reading. The layout is open and adaptable, providing various possibilities for furniture arrangement, catering to both comfort and style. This room embodies a tranquil sanctuary where daily life can unfold with ease.", "suggested_amenities": ["Natural Light", "Wood Flooring"], "suggested_activities": ["Relaxing", "Reading"]}]}', '2026-04-20 00:02:21.122+00', '2026-06-24 15:31:44.469+00', '2026-06-23 03:00:15.828+00', true, '2026-04-20 00:02:24.388162+00', '2026-06-23 03:00:15.796586+00', NULL, NULL, '5 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('b4fd398d-3b46-4ebe-a45e-2c1527d9f1eb', 'nt131657412', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-hai-ba-trung-ha-noi/131657412.htm', 'Apartment for rent in Lo Duc, Hai Ba Trung, Hanoi, near Trang Tien Grand Theater', 'Phố Lò Đúc, Phường Phạm Đình Hổ, Quận Hai Bà Trưng, Hà Nội', 'ph l c phng phm nh h qun hai b trng h ni', 'hanoi', 9000000, '9 triệu/tháng', '35 m²', 'Discover this charming 1-bedroom apartment for rent on Lo Duc Street, Hai Ba Trung District, Hanoi. Spanning 35 m², this self-contained apartment offers a comfortable living space with a single bedroom and is fully furnished, ready for immediate occupancy. The building features an elevator for convenience. Its prime location places it in the heart of Hanoi''s Old Quarter, providing easy access to various schools, office buildings, and cultural landmarks like the Trang Tien Grand Theater. This apartment is ideal for individuals or couples seeking a well-equipped home in a vibrant and central area. The legal status is a private pink book (Sổ hồng riêng), ensuring clear ownership. With full interior furnishings, you can move in hassle-free. The deposit amount is 1 VND/month, and it is also a corner unit, potentially offering more natural light and privacy. Interested tenants are invited to contact for further details and price negotiation. Please note that advertising and brokerage inquiries are not welcome.', '{"Natural light streaming through elegant curtains","Tranquil sleep sanctuary with plush bedding","Sleek glass shower with modern fixtures"}', '{"1 bedroom","Service apartment, mini apartment","35 m²","Private pink book (Sổ hồng riêng)","1 bathroom","Fully furnished","Deposit: 1 VND/month","Corner unit",Elevator}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131657412/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131657412/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase