	('7aeafe6d-5506-4d0d-92d4-363c5b42a90a', 'nt131331050', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-10-tp-ho-chi-minh/131331050.htm', '1 Bedroom Apartment for Rent in Kingdom 101, District 10, Ho Chi Minh City', '334 Tô Hiến Thành, Phường 14, Quận 10, Ho Chi Minh City', '334 t hin thnh phng 14 qun 10 ho chi minh city', 'ho_chi_minh', 16500000, '16.5 triệu/tháng', '60 m²', 'This beautifully furnished 1-bedroom apartment in the Kingdom 101 project offers a spacious living area of 60 m². Located in District 10, Ho Chi Minh City, it is perfect for those seeking comfort and convenience. The apartment comes fully equipped with modern furniture, ensuring a cozy living experience. The property is situated in a vibrant neighborhood with easy access to local amenities, making it an ideal choice for both individuals and couples. Enjoy the luxury of living in a well-designed space that combines style and functionality. The rental price is 16.5 million VND per month, which includes all necessary amenities for a comfortable lifestyle.', '{"Panoramic views through expansive floor-to-ceiling windows","Culinary creativity hub for gourmet experiences","Inviting dining area with stunning city views","Contemporary design with minimalist elegance","Efficient built-in storage for seamless organization"}', '{"Fully Furnished","Air Conditioning",Elevator,"24/7 Security","Parking Space",TV,"Coffee Table",Sofa,"Wall Clock",Curtains,"Storage Cabinet","Indoor Plant","Large Windows","Comfortable Sofa","Dining Table",Chairs,"Kitchen Cabinets","Kitchen Sink",Refrigerator,Stove,Microwave,"Pendant Light","Kitchen Appliances","Hanging Light Fixture","Floor-to-ceiling Windows",Bed,Nightstand,Mirror,Flooring,Wardrobe,"Built-in Storage",Lighting}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131331050/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131331050/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131331050/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131331050/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131331050/4.jpg}', 'Huỳnh Ba', NULL, NULL, '{"cozy": 6, "urban": 7, "colors": ["Warm", "Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 2, "styles": ["Modern", "Minimalist", "Elegant"], "elegant": 7, "colorful": 3, "spacious": 5, "luxurious": 5, "activities": ["Relaxing with a view", "Entertaining guests", "Cooking gourmet meals", "Enjoying intimate dinners", "Dining"], "minimalist": 8, "natural_light": 7, "image_analyses": [{"amenities": ["TV", "Coffee Table", "Sofa", "Wall Clock", "Curtains", "Storage Cabinet", "Indoor Plant", "Large Windows"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 8, "modern": 8, "elegant": 5, "spacious": 5, "luxurious": 5, "minimalist": 7, "natural_light": 7}, "image_highlight": "Panoramic views through expansive floor-to-ceiling windows", "detailed_analysis": "The living space exudes a modern aesthetic with its sleek furniture and elegant design elements. A plush blue sofa invites relaxation, while the stylish coffee table adds functionality. Natural light floods in through the expansive floor-to-ceiling windows, enhancing the open feel. The subtle decor, including a wall clock and indoor plants, creates a tranquil atmosphere. The layout promotes a seamless flow, making it an ideal spot for both unwinding and socializing, showcasing a vibrant urban lifestyle.", "suggested_amenities": ["Large Windows", "Comfortable Sofa"], "suggested_activities": ["Relaxing with a view", "Entertaining guests"]}, {"amenities": ["Dining Table", "Chairs", "Kitchen Cabinets", "Kitchen Sink", "Refrigerator", "Stove", "Microwave", "Pendant Light"], "image_index": 1, "vibe_scores": {"cozy": 6, "urban": 7, "modern": 8, "