ht": 7, "image_analyses": [{"amenities": ["Washing Machine", "Kitchen Sink", "Refrigerator", "Kitchen Cabinets", "Countertop", "Smart TV", "Storage Cabinet"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 6, "modern": 8, "elegant": 6, "spacious": 5, "luxurious": 5, "minimalist": 7, "natural_light": 7}, "image_highlight": "Efficiently designed kitchen with modern appliances", "detailed_analysis": "This compact kitchen area showcases a seamless blend of functionality and modern aesthetics. The sleek cabinets and polished countertop create an inviting culinary space, while the integrated washing machine adds convenience for daily chores. Large windows allow natural light to flood the area, enhancing the overall ambiance. The thoughtful layout maximizes comfort, making it an ideal spot for both cooking and laundry tasks, thereby elevating daily living experiences. The clean lines and contemporary finishes contribute to a sophisticated yet cozy atmosphere.", "suggested_amenities": ["Kitchen Appliances", "In-unit Laundry"], "suggested_activities": ["Cooking", "Laundry"]}, {"amenities": ["Washing Machine", "Refrigerator", "Stove", "Kitchen Cabinets", "Sink", "Countertop", "Window Treatments"], "image_index": 1, "vibe_scores": {"cozy": 6, "urban": 8, "modern": 8, "elegant": 7, "spacious": 6, "luxurious": 5, "minimalist": 9, "natural_light": 7}, "image_highlight": "Efficient laundry and kitchen integration", "detailed_analysis": "This space features a thoughtfully integrated laundry setup, with a modern washing machine seamlessly incorporated into the kitchen area. The warm wood flooring and neutral color palette create a welcoming atmosphere, while the large window allows for abundant natural light, enhancing the sense of openness. The kitchen’s practical design, including a stove and ample cabinetry, encourages culinary creativity. Overall, the layout promotes efficient use of space, making daily chores more manageable and enjoyable.", "suggested_amenities": ["Washing Machine", "Refrigerator"], "suggested_activities": ["Doing laundry", "Meal prep"]}, {"amenities": ["Bed", "Wardrobe", "Large Windows", "Artwork", "Curtains"], "image_index": 2, "vibe_scores": {"cozy": 6, "urban": 5, "modern": 7, "elegant": 6, "spacious": 6, "luxurious": 5, "minimalist": 8, "natural_light": 7}, "image_highlight": "Natural light streaming through large windows", "detailed_analysis": "This serene bedroom exudes a calming atmosphere with its large windows allowing natural light to flood the space, creating a bright and inviting environment. The minimalist design is enhanced by soft colors and elegant artwork that adds a touch of sophistication. The plush bed promises comfort, while the built-in wardrobe provides ample storage, ensuring an organized and clutter-free experience. Overall, the space feels like a personal retreat, ideal for unwinding after a long day.", "suggested_amenities": ["Large Windows", "Wardrobe"], "suggested_activities": ["Reading", "Relaxing"]}, {"amenities": ["Queen Bed", "Nightstand", "Artwork", "Curtains", "Full-length Mirror"], "image_index": 3, "vibe_scores": {"cozy": 8, "urban": 7, "modern": 7, "elegant": 7, "spacious": 5, "luxurious": 6, "minimalist": 9, "natural_light": 8}, "image_highlight": "Chic design with plush headboard and stylish decor", "detailed_analysis": "This elegantly designed bedroom exudes a sense of relaxation and comfort. The plush headboard and minimalist furniture create a cozy retreat, while the large windows allow natural light to flood the space, enhancing its warm ambiance. Thoughtfully placed artwork adds a personal touch, making it inviting and stylish. The layout promotes a sense of serenity, ideal for restful nights or leisurely reading, making it an essential personal sanctuary in urban living.", "suggested_amenities": ["Nightstand", "Artwork"], "suggested_activities": ["Resting", "Reading"]}, {"amenities": ["Wardrobe", "Bed", "Nightstand", "Curtains", "Wood Flooring"], "image_index": 4, "vibe_scores": {"cozy": 8, "urban": 7, "modern": 7, "elegant": 6, "spacious": 6, "luxurious": 5, "minimalist": 9, "natural_light": 8}, "image_highlight": "Inviting natural light through elegant curtains", "detailed_analysis": "This serene bedroom offers a tranquil retreat with its inviting natural light flooding through large windows. The minimalist design and soft color palette create a calming atmosphere, perfect for relaxation or focus. Elegant curtains frame the windows, adding a touch of sophistication, while the wooden flooring enhances warmth. The well-integrated wardrobe provides ample storage without compromising space, ensuring a clutter-free environment. The overall flow of the room promotes a sense of peace, making it an ideal sanctuary for restful nights and rejuvenating mornings.", "suggested_amenities": ["Natural Lighting", "Wardrobe"], "suggested_activities": ["Reading", "Morning yoga"]}]}', '2026-04-07 12:05:32.905+00', '2026-06-24 15:31:44.469+00', '2026-06-13 03:00:08.906+00', true, '2026-04-07 12:05:33.034619+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, 'Studio', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('59dd654c-51c6-42ef-b9d8-edb3ed4b5122', 'nt131097065', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-cau-giay-ha-noi/131097065.htm#px=sr-stickyad-[po-1][pl-top]', 'Fully Furnished Service Apartment for Rent in Xuân Thủy, Cầu Giấy', 'Xuân Thủy Street, Dịch Vọng Hậu Ward, Cầu Giấy District, Hanoi', 'xun thy street dch vng hu ward cu giy district hanoi', 'hanoi', 4800000, '4.8 triệu/tháng', '30 m²', 'This charming service apartment is located on Xuân Thủy Street in the bustling Cầu Giấy district of Hanoi. Spanning 30 m², it features a cozy bedroom and is fully furnished with essential amenities including a television, refrigerator, air conditioner, water purifier, bed, and bedding. The apartment is situated in a secure area with 24/7 security, ensuring peace of mind for residents. The building offers convenient access to nearby markets, supermarkets, pharmacies, and gyms, making it an ideal choice for students and working professionals. With its modern furnishings and strategic location, this apartment provides a comfortable living experience in one of Hanoi''s most vibrant neighborhoods.', '{"Warm wooden tones complement the sleek kitchen area.","Large windows provide natural light and city views.","Cozy bedding with a checkered pattern adds charm.","Elegant hallway with marble flooring and decorative lighting.","Functional layout with ample storage and modern finishes."}', '{"Air Conditioning",WiFi,Television,Refrigerator,"Water Purifier","Bed and Bedding","Security Service"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131097065/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131097065/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131097065/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131097065/3.jpg,https://gbgrwjdm