	('80338d86-08bd-407f-ac73-d6c6e8b770dc', 'nt132038702', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-go-vap-tp-ho-chi-minh/132038702.htm#px=sr-stickyad-[po-1][pl-top]', 'Chic Penthouse Retreat with Expansive Balcony and Million-Dollar Views', 'Đường Dương Quảng Hàm, Phường 6, Quận Gò Vấp, Tp Hồ Chí Minh', 'ng dng qung hm phng 6 qun g vp tp h ch minh', 'ho_chi_minh', 9500000, '9,5 triệu/tháng', '65 m²', 'Step into a world of elegance and comfort in this chic penthouse retreat, where modern design meets breathtaking views. Spanning 65 square meters, this stylish abode features an expansive balcony that invites you to soak in the stunning scenery, perfect for morning coffees or evening gatherings. The interior boasts high-end furnishings, including air conditioning for those warm days, and a well-appointed kitchen that makes entertaining a breeze. The spacious bedroom and inviting living area create a harmonious flow, allowing for both relaxation and productivity. With ample natural light flooding through large windows, the atmosphere is bright and uplifting, making it an ideal sanctuary for those seeking a blend of luxury and practicality. Whether you''re hosting friends or enjoying a quiet night in, this penthouse offers a lifestyle of sophistication and ease.', '{"Stylish dining area with modern chairs and table","Wood paneling adds warmth to the dining area","Bright kitchen with sleek cabinetry and appliances","Large windows providing ample natural light","Sleek green cabinetry with stylish countertop"}', '{"Air Conditioning","Washing Machine",Balcony,"High-end Furniture","kitchen cabinets",sink,"washing machine","dining table",chairs,refrigerator,Dishwasher,"Air conditioning",Refrigerator,"Dining Table",Chairs,stove,"wood paneling","large windows",door,Storage,"kitchen cabinetry",countertop,appliances,windows,Microwave}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132038702/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132038702/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132038702/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132038702/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt132038702/4.jpg}', 'Công Định EZHouse', '038215 ***', NULL, '{"cozy": 7, "urban": 7, "colors": ["Warm", "Neutral", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 3, "styles": ["Modern", "Cozy", "Minimalist"], "elegant": 6, "colorful": 4, "spacious": 6, "amenities": ["kitchen cabinets", "sink", "washing machine", "dining table", "chairs", "Dining table", "Chairs", "Pendant light", "Refrigerator", "Washing machine", "stove", "refrigerator", "wooden bench", "large windows", "pendant light", "kitchen sink", "washer"], "luxurious": 5, "activities": ["Cooking", "Entertaining", "Relaxing", "Reading", "Working"], "minimalist": 7, "natural_light": 8, "image_analyses": [{"amenities": ["kitchen cabinets", "sink", "washing machine", "dining table", "chairs", "refrigerator"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 7, "modern": 8, "elegant": 6, "spacious": 6, "luxurious": 5, "minimalist": 7, "natural_light": 4}, "image_highlight": "Stylish dining area with modern chairs and table", "detailed_analysis": "This image showcases a modern kitchen and dining area. The kitchen features sleek blue cabinets, a stainless steel sink, and a washing machine. Adjacent to the kitchen is a stylish dining area with a marble table and contemporary chairs. The space is well-lit with recessed lighting, creating a bright and inviting atmosphere. The wooden accent wall adds warmth and a touch of elegance to the overall design.", "suggested_amenities": ["Dishwasher", "Air conditioning"], "suggested_activities": ["Cooking", "Entertaining", "Relaxing"]}, 