	('6ce91084-2d69-40d5-8522-cad608ebac3c', 'nt131761949', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-3-tp-ho-chi-minh/131761949.htm', 'Charming Duplex Retreat with Private Washing Machine Near Bàn Cờ Market', 'Đường Nguyễn Thiện Thuật, Phường 2, Quận 3, Tp Hồ Chí Minh', 'ng nguyn thin thut phng 2 qun 3 tp h ch minh', 'ho_chi_minh', 5500000, '5,5 triệu/tháng', '30 m²', 'Step into this charming duplex retreat that perfectly balances modern comfort with a cozy atmosphere. Bathed in natural light, the space features a fresh and inviting design, with a soothing color palette that enhances relaxation. The open layout allows for seamless transitions between living, dining, and working areas, making it ideal for both quiet evenings and lively gatherings with friends. Enjoy your morning coffee by the window or unwind after a long day in this thoughtfully designed sanctuary. With a private washing machine and ample storage, daily routines are made effortless. Located near Bàn Cờ Market and NowZone, you’ll have easy access to vibrant local amenities and a variety of dining options, ensuring a lifestyle filled with convenience and charm.', '{"Lofted sleeping area with stylish wooden railing","Bright space with large windows for natural light","Compact kitchen with modern cabinetry and appliances","Functional layout featuring a tall storage cabinet","Sleek countertop paired with stylish cabinetry"}', '{"Washing Machine","Air Conditioning",WiFi,Parking}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131761949/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131761949/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131761949/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131761949/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131761949/4.jpg}', 'Đồng', '038832***', NULL, '{"colors": [], "styles": [], "activities": [], "image_analyses": [{"image_index": 0, "image_highlight": "Lofted sleeping area with stylish wooden railing", "suggested_amenities": ["Loft bed", "Reading nook"]}, {"image_index": 1, "image_highlight": "Bright space with large windows for natural light", "suggested_amenities": ["Window treatments", "Indoor plants"]}, {"image_index": 2, "image_highlight": "Compact kitchen with modern cabinetry and appliances", "suggested_amenities": ["Microwave", "Coffee maker"]}, {"image_index": 3, "image_highlight": "Functional layout featuring a tall storage cabinet", "suggested_amenities": ["Storage solutions", "Organizational tools"]}, {"image_index": 4, "image_highlight": "Sleek countertop paired with stylish cabinetry", "suggested_amenities": ["Bar stools", "Decorative items"]}]}', '2026-04-13 00:32:23.433+00', '2026-06-24 15:31:44.469+00', '2026-06-23 03:00:06.287+00', true, '2026-04-13 00:32:29.428104+00', '2026-06-23 03:00:06.262809+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('25d1dbcf-bbac-4123-99b8-a83cc306a0ed', 'pr45078162', 'batdongsan', 'https://batdongsan.com.vn/cho-thue-can-ho-chung-cu-mini-duong-song-hanh-phuong-an-phu-khu-do-thi-lakeview-city/cho-dv-don-vao-o-ngay-day-du-noi-that-chi-tu-6-5-trieu-thang-pr45078162', 'Lakeview City Service Apartment for Rent - Fully Furnished, Move-in Ready from 6 Million VND/Month', 'Lakeview City Urban Area, Song Hanh Street, An Phu Ward, District 2, Ho Chi Minh City', 'lakeview city urban area song hanh street an phu ward district 2 ho chi minh city', 'ho_chi_minh', 6000000, '6 triệu/tháng', '40 m²', 'This stunning service apartment located in the prestigious Lakeview City Urban Area offers a perfect blend of comfort and style. With a generous area of 40 m², this fully furnished 1-bedroom apartment is ready for you to move in immediately. The apartment features modern decor and is equipped with all essential amenities to ensure a comfortable living experience. Enjoy the convenience of nearby shopping, dining, and recreational facilities, making it an ideal choice for both individuals and couples. The vibrant community and lush green surroundings provide a serene environment, perfect for relaxation after a busy day. Don''t miss out on this fantastic opportunity to live in one of Ho Chi Minh City''s most sought-after neighborhoods at an affordable price.', '{"Bright and airy living space with modern design","Inviting workspace with natural light","Functional dining area with natural light","Inviting workspace for focused productivity","Inviting space with contemporary design elements"}', '{"Air Conditioning",WiFi,Refrigerator,Television,"Washing Machine","24/7 Security","Parking Space",Bed,Desk,Chair,Curtains,"Large Windows","Modern Desk",TV,Window,Nightstand,"Dining Table","Kitchen Cabinets",Sofa,Wardrobe,"Ceiling Light","Comfortable Bed","Modern Lighting"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr45078162/0.jpg,https://gbgrwj