	('bd118fdf-b7a7-4cd6-be3a-f8780636a8f4', 'pr43894304', 'batdongsan', 'https://batdongsan.com.vn/cho-thue-can-ho-chung-cu-vinhomes-central-park-phuong-thanh-my-tay-tp-ho-chi-minh/chuyen-cho-gia-tu-1pn-16tr-2pn-19tr-3pn-28tr-4pn-50tr-pr43894304', 'Affordable Apartment Rental at Vinhomes Central Park', 'Vinhomes Central Park, Hồ Chí Minh', 'vinhomes central park h ch minh', 'other', 19000000, '19 triệu/tháng', '89', 'This rental apartment in Vinhomes Central Park offers great value with prices starting from 16 million VND per month. The 2-bedroom unit spans 89m² and is perfect for families or professionals seeking a modern living environment. The building features various amenities and is located near shopping areas, making it a convenient choice for residents.', '{"Opulent dining area with elegant chandeliers","Gourmet kitchen with elegant marble countertops","Natural light-filled urban retreat","Elegant king bed with luxurious bedding accents","Breathtaking views from expansive floor-to-ceiling windows"}', '{"Modern design","Close to shopping"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43894304/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43894304/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43894304/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43894304/3.jpg}', 'Thành Phạm Vincentral', '0909 638 ***', NULL, '{"cozy": 6, "urban": 7, "colors": ["Warm", "Cool", "Bright", "Refined"], "modern": 8, "rustic": 1, "styles": ["Luxurious", "Elegant", "Modern"], "elegant": 9, "colorful": 5, "spacious": 7, "luxurious": 9, "activities": ["Hosting dinner parties", "Enjoying family meals", "Cooking", "Entertaining guests", "Resting"], "minimalist": 5, "natural_light": 9, "image_analyses": [{"amenities": ["Dining Table", "Chairs", "Chandeliers", "Television", "Coffee Table", "Decorative Plants", "Wall Art", "Marble Flooring"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 7, "modern": 8, "elegant": 10, "spacious": 7, "luxurious": 10, "minimalist": 5, "natural_light": 8}, "image_highlight": "Opulent dining area with elegant chandeliers", "detailed_analysis": "This stunning open-concept space features a chic dining area, highlighted by elegant chandeliers that create a warm ambiance. The glossy marble flooring adds a touch of luxury, reflecting natural light pouring in through large windows. The contemporary furniture, including plush chairs and a stylish coffee table, invites relaxation. An eye-catching television set against a marble backdrop enhances the entertainment experience. This space exudes sophistication while accommodating social gatherings seamlessly.", "suggested_amenities": ["Chandeliers", "Dining Table"], "suggested_activities": ["Hosting dinner parties", "Enjoying family meals"]}, {"amenities": ["Chandelier", "Refrigerator", "Oven", "Stove", "Kitchen Sink", "Kitchen Cabinets", "Coffee Table", "Sofa", "Floor-to-ceiling Windows"], "image_index": 1, "vibe_scores": {"cozy": 4, "urban": 7, "modern": 8, "elegant": 9, "spacious": 6, "luxurious": 9, "minimalist": 5, "natural_light": 8}, "image_highlight": "Gourmet kitchen with elegant marble countertops", "detailed_analysis": "This open-plan living space seamlessly integrates luxury and functionality. The gourmet kitchen features elegant marble countertops and state-of-the-art appliances, fostering culinary creativity. The plush sofa and chic coffee table create an inviting atmosphere, perfect for entertaining. Ample natural light floods the room through floor-to-ceiling windows, enhancing the overall ambiance and offering stunning views. The decor is a blend of modern sophistication and comfort, making this space ideal for both relaxation and social gatherings.", "suggested_amenities": ["Marble Countertops", "Kitchen Appliances"], "suggested_activities": ["Cooking", "Entertaining guests"]}, {"amenities": ["Queen Bed", "Large Windows", "Wall Lighting", "Closet"], "image_index": 2, "vibe_scores": {"cozy": 7, "urban": 7, "modern": 8, "elegant": 8, "spacious": 6, "luxurious": 6, "minimalist": 9, "natural_light": 9}, "image_highlight": "Natural light-filled urban retreat", "detailed_analysis": "This bedroom is a serene urban retreat, featuring large windows that bathe the space in natural light, creating a bright and uplifting atmosphere. The minimalist design, accentuated by the soft wall lighting and elegant decor, lends a sense of sophistication. The warm wood flooring adds a cozy touch, while the layout promotes a seamless flow. This sanctuary offers a perfect blend of comfort and modern aesthetics, ideal for restful nights and rejuvenating mornings.", "suggested_amenities": ["Large Windows", "Wall Lighting"], "suggested_activities": ["Resting", "Morning reflection"]}, {"amenities": ["King Bed", "Nightstand", "Table Lamp", "Wall Art", "Large Windows", "Luxury Bedding"], "image_index": 3, "vibe_scores": {"cozy": 7, "urban": 7, "modern": 8, "elegant": 9, "spacious": 6, "luxurious": 9, "minimalist": 5, "natural_light": 8}, "image_highlight": "Elegant king bed with luxurious bedding accents", "detailed_analysis": "This chic bedroom exudes modern elegance with its plush king bed featuring luxurious bedding and a sophisticated color palette of whites and purples. The elegant headboard design and stylish nightstands enhance the luxurious atmosphere, complemented by warm lighting from the table lamps. Large windows invite ample natural light, creating a bright, uplifting environment perfect for relaxation or reading. The unique marble accent wall adds a touch of sophistication, while the warm wood flooring underfoot contributes to a cozy, inviting feel.", "suggested_amenities": ["Nightstand", "Table Lamp"], "suggested_activities": ["Resting", "Reading"]}, {"amenities": ["Chandeliers", "Large Screen TV", "Dining Table", "Dining Chairs", "Sofa", "Coffee Table", "Kitchen Appliances", "Floor-to-ceiling Windows", "Marble Floors"], "image_index": 4, "vibe_scores": {"cozy": 4, "urban": 9, "modern": 9, "elegant": 10, "spacious": 8, "luxurious": 10, "minimalist": 3, "natural_light": 10}, "image_highlight": "Breathtaking views from expansive floor-to-ceiling windows", "detailed_analysis": "This sophisticated living space exudes luxury with its opulent design and stunning city views. The expansive floor-to-ceiling windows bathe the room in natural light, creating an uplifting atmosphere. Elegant chandeliers add a touch of glam, while the marble flooring enhances the contemporary aesthetic. The open layout seamlessly connects dining and living areas, perfect for both relaxation and entertaining. The plush sofa and stylish dining table invite guests to enjoy memorable evenings, making this space a true urban retreat.", "suggested_amenities": ["Large Screen TV", "Chandeliers"], "suggested_activities": ["Relaxing with a view", "Entertaining guests"]}]}', '2026-04-12 00:02:40.05+00', '2026-06-24 15:31:44.469+00', '2026-06-22 03:00:13.144+00', true, '2026-04-12 00:02:40.115842+00', '2026-06-22 03:00:13.145752+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
