	('892b3b9b-8c85-489c-b556-14afa9d30f8b', 'nt121634058', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-3-tp-ho-chi-minh/121634058.htm', 'Fully Furnished 2 Bedroom Apartment for Rent in Hai Ba Trung - District 3', 'Hai Ba Trung Street, Vo Thi Sau Ward, District 3, Ho Chi Minh City', 'hai ba trung street vo thi sau ward district 3 ho chi minh city', 'ho_chi_minh', 13500000, '13.5 triệu/tháng', '75 m²', 'This spacious 75 m² apartment features 2 bedrooms and is fully furnished, making it perfect for anyone looking for a comfortable living space in the heart of Ho Chi Minh City. Located on Hai Ba Trung Street in District 3, the apartment boasts a wide balcony with a pleasant view, ensuring plenty of natural light and fresh air. The building offers a range of amenities including a large parking area, 24/7 security, and an elevator for easy access. Weekly cleaning services are provided, and residents enjoy flexible access with fingerprint entry for enhanced security. The apartment is situated near the Kieu Bridge, providing easy access to local shops and restaurants. Contact Nam for more information and to receive a special discount when signing the lease this month.', '{"Indoor-outdoor living with lush greenery","Inviting relaxation corner with abundant natural light","Sleek kitchen island for culinary creativity","Inviting breakfast bar for casual dining","Inviting breakfast bar for casual social gatherings"}', '{"Full Furnishings","Large Balcony","24/7 Security",Elevator,"Weekly Cleaning Service","Fingerprint Access"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt121634058/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt121634058/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt121634058/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt121634058/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt121634058/4.jpg}', 'Nam', NULL, NULL, '{"colors": [], "styles": [], "activities": [], "image_analyses": [{"image_index": 0, "image_highlight": "Indoor-outdoor living with lush greenery", "suggested_amenities": ["Sofa", "Plants"]}, {"image_index": 1, "image_highlight": "Inviting relaxation corner with abundant natural light", "suggested_amenities": ["Sofa", "Large Screen TV"]}, {"image_index": 2, "image_highlight": "Sleek kitchen island for culinary creativity", "suggested_amenities": ["Kitchen Island", "Refrigerator"]}, {"image_index": 3, "image_highlight": "Inviting breakfast bar for casual dining", "suggested_amenities": ["Kitchen Counter", "Microwave"]}, {"image_index": 4, "image_highlight": "Inviting breakfast bar for casual social gatherings", "suggested_amenities": ["Breakfast Bar", "Kitchen Appliances"]}]}', '2026-03-30 04:03:03.099+00', '2026-06-24 15:31:44.469+00', '2026-06-15 03:00:27.857+00', true, '2026-03-30 04:03:03.167092+00', '2026-06-15 03:00:27.829838+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('02fc7f7f-b1f9-4e49-a5a8-173800f8f4cc', 'nt131804468', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-dong-da-ha-noi/131804468.htm#px=sr-stickyad-[po-1][pl-top]', 'Spacious and Serene 1-Bedroom Retreat with Modern Comforts in Historic Đống Đa', 'Lương Sử C, Phường Quốc Tử Giám, Quận Đống Đa, Hà Nội', 'lng s c phng quc t gim qun ng a h ni', 'hanoi', 8600000, '8,6 triệu/tháng', '45 m²', 'Discover a brand-new, exceptionally spacious 1-bedroom apartment designed for modern living, nestled in the vibrant heart of Đống Đa. This apartment offers a unique layout with a distinct living room and bedroom, providing ample space for both relaxation and entertaining. The interior boasts a fresh, clean aesthetic with full furnishings, ensuring a seamless move-in experience. Imagine waking up in a beautifully appointed bedroom, then enjoying your morning coffee in a bright, airy living space. The convenience of a private washing machine adds to the ease of daily life. Located on Lương Sử C, you''re just moments away from the historic Văn Miếu, with quick access to Ba Đình, Cầu Giấy, and Tôn Đức Thắng. The neighborhood thrives with local markets, supermarkets, and eateries, offering a true taste of Hanoi. The building provides excellent security with 24/7 cameras and the rare luxury of car parking right at the doorstep. This quiet and secure environment is perfect for professionals or couples seeking a peaceful yet connected urban sanctuary. Experience the comfort and convenience of a new home where every detail is thoughtfully considered.', '{"Sleek kitchen with integrated appliances","Natural light streaming through expansive windows","Efficient storage solutions for urban living","Sleek walk-in shower with modern fixtures","Seamless indoor-outdoor flow with balcony access"}', '{"Washing Machine","Full Interior Furnishing","Car Parking","Security Camera","Air Conditioning","Natural Light","Modern Fixtures","Storage Cabinets","Lighting Fixtures"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131804468/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131804468/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131804468/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131804468/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131804468/4.jpg}', 'Thái Nguyễn', '038539***', NULL, '{"cozy": 6, "urban": 5, "colors": ["Warm", "Cool", "Bright", "Refined"], "modern": 6, "rustic": 4, "styles": ["Modern", "Cozy", "Spacious"], "elegant": 6, "colorful": 5, "spacious": 6, "luxurious": 5, "activities": ["Relaxing", "Living"], "minimalist": 5, "natural_light": 7, "image_analyses": [{"image_index": 0, "image_highlight": "Sleek kitchen with integrated appliances", "suggested_amenities": ["Kitchen Appliances", "Laundry Facilities"]}, {"image_index": 1, "image_highlight": "Natural light streaming through expansive windows", "suggested_amenities": ["Large Windows", "Air Conditioning"]}, {"image_index": 2, "image_highlight": "Efficient storage solutions for urban living", "suggested_amenities": ["Storage Cabinets", "Bed"]}, {"image_index": 3, "image_highlight": "Sleek walk-in shower with modern fixtures", "suggested_amenities": ["Walk-in Shower", "Modern Toilet"]}, {"image_index": 4, "image_highlight": "Seamless indoor-outdoor flow with balcony access", "suggested_amenities": ["Sofa", "Air Conditioning"]}]}', '2026-04-14 02:00:53.497+00', '2026-06-24 15:31:44.469+00', '2026-06-22 03:00:14.317+00', true, '2026-04-14 02:00:57.19601+00', '2026-06-22 03:00:14.322387+00', NULL, NULL, '1 Bedroom', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
	('2014f84c-c825-4928-8680-0c6577ae331c', 'pr43516158', 'batdongsan', 'https://batdongsan.com.vn/cho-thue-can-ho-chung-cu-duong-3-2-2-phuong-12-5-hado-centrosa-garden/cap-nhat-gia-moi-nhat-xem-nha-sau-30-phut-lien-he-san-suat-xe-o-to-hotline-pr43516158', 'Chic Urban Retreat in HaDo Centrosa Garden', '118 - 200 3/2, Phường 12, Quận 10, Hồ Chí Minh', '118 200 32 phng 12 qun 10 h ch minh', 'ho_chi_minh', 25000000, '25 triệu/tháng', '87 m²', 'Step into a chic urban retreat at HaDo Centrosa Garden, where modern design meets comfort. This spacious 2-bedroom apartment boasts an open layout that invites natural light to dance across the sleek surfaces. The contemporary aesthetic is complemented by a soothing color palette of soft neutrals, creating a serene atmosphere perfect for unwinding after a busy day. Imagine sipping your morning coffee on the balcony, basking in the gentle morning sun, or hosting friends in the stylish living area that seamlessly flows into the dining space. With high-quality furnishings and essential amenities, this apartment is designed for both relaxation and productivity. Whether you''re working from home or enjoying a cozy evening in, this space supports your daily rituals with ease. Experience the vibrant lifestyle of Quận 10, with everything you need just a stone''s throw away.', '{"Stylish TV setup with decorative wall shelving.","Bright space with large windows and floral decor.","Cozy bedroom with mountain artwork and soft lighting.","Minimalist bedroom featuring a sleek gray bed frame.","Open layout connecting living and dining areas seamlessly."}', '{"Air Conditioning",WiFi,Balcony,"Washing Machine",Parking,Pool,Gym,Elevator,"Security Camera"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43516158/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr43516158/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object