	('5acc6731-4ef0-47d8-859e-6f1326484dcf', 'nt131985856', 'nhatot', 'https://www.nhatot.com/thue-can-ho-chung-cu-quan-phu-nhuan-tp-ho-chi-minh/131985856.htm#px=sr-stickyad-[po-1][pl-top]', 'Charming 1-Bedroom Retreat with Serene River Views', 'Đường Trường Sa, Phường 13, Quận Phú Nhuận, Tp Hồ Chí Minh', 'ng trng sa phng 13 qun ph nhun tp h ch minh', 'ho_chi_minh', 8500000, '8,5 triệu/tháng', '50 m²', 'Step into this charming 1-bedroom apartment that offers a perfect blend of comfort and style. Spanning 50 square meters, the space is designed to provide a cozy yet spacious atmosphere, ideal for both relaxation and entertaining. The apartment features a separate bedroom and a distinct kitchen area, allowing for a seamless flow between living and dining. Large windows invite natural light, creating a warm and inviting ambiance throughout the day. Imagine sipping your morning coffee on the balcony, enjoying the gentle breeze from the nearby river. The interior is adorned with brand new furnishings, including a plush bed, ample storage, and essential appliances like air conditioning and a washing machine, ensuring a hassle-free living experience. Located right by the Trường Sa riverbank, you’ll find yourself just minutes away from vibrant cafes and restaurants, making it easy to explore the local culture. This newly opened gem is perfect for those seeking a stylish retreat in the heart of Quận Phú Nhuận.', '{"Elegant tufted headboard complements the cozy decor.","Stylish coffee table paired with a neutral sofa.","Large windows provide ample natural light.","Minimalist cabinetry enhances the spacious feel.","Rich color contrasts with soft lighting ambiance."}', '{"Air Conditioning","Washing Machine",Refrigerator,Balcony,WiFi,Bed,Sofa,"Coffee Table",Nightstand,Lamp,"Decorative Plants",Artwork,"Large Mirror","Elegant Bed","Floor Lamp","Wall Art","Decorative Plant","Comfortable Sofa","Decorative Lighting","Decorative Wall Art","Potted Plant","Built-in Storage","Large Windows",Wardrobe,Lighting,"Indoor Plant","Storage Solutions","Natural Light","Modern Fixtures","Storage Cabinets","Lighting Fixtures"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131985856/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131985856/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131985856/2.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131985856/3.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/nhatot-nt131985856/4.jpg}', 'Bằng', '039297 ***', NULL, '{"cozy": 6, "urban": 5, "colors": ["Warm", "Neutral", "Cool", "Bright", "Refined"], "modern": 7, "rustic": 2, "styles": ["Modern", "Luxurious", "Minimalist"], "elegant": 7, "colorful": 4, "spacious": 7, "luxurious": 7, "activities": ["Relaxing", "Reading", "Working"], "minimalist": 7, "natural_light": 8, "image_analyses": [{"image_index": 0, "image_highlight": "Elegant tufted headboard complements the cozy decor.", "suggested_amenities": ["King-sized bed", "Accent lighting"]}, {"image_index": 1, "image_highlight": "Stylish coffee table paired with a neutral sofa.", "suggested_amenities": ["Decorative plants", "Artistic wall decor"]}, {"image_index": 2, "image_highlight": "Large windows provide ample natural light.", "suggested_amenities": ["Window treatments", "Indoor greenery"]}, {"image_index": 3, "image_highlight": "Minimalist cabinetry enhances the spacious feel.", "suggested_amenities": ["Storage solutions", "Compact appliances"]}, {"image_index": 4, "image_highlight": "Rich color contrasts with soft lighting ambiance.", "suggested_amenities": ["Mood lighting", "Textured rugs"]}]}', '2026-04-23 01:02:07.497+00', '2026-06-24 15:31:44.469+00', '2026-06-10 03:00:08.722+00', true, '2026-04-23 01:02:10.927573+00', '2026-06-14 15:31:45.8