	('e125b1f4-97e8-4583-898a-a0271f18d1f8', 'pr38177579', 'batdongsan', 'https://batdongsan.com.vn/cho-thue-can-ho-chung-cu-masteri-thao-dien-phuong-thao-dien-quan-2/2pn-full-noi-that-tang-cao-view-song-pr38177579', 'Apartment for rent in Masteri Thao Dien, District 2, 2 bedrooms, fully furnished, high floor, river view', 'Masteri Thảo Điền, Phường Thảo Điền, Quận 2, Hồ Chí Minh', 'masteri tho in phng tho in qun 2 h ch minh', 'ho_chi_minh', 20000000, '20 triệu/tháng', '75', 'This 2-bedroom apartment in Masteri Thao Dien offers a comfortable living space with modern furnishings. Located on a high floor, it provides stunning river views. The apartment is fully equipped, making it ready for immediate occupancy. Masteri Thao Dien is a popular residential area in District 2, known for its convenient location and upscale amenities, including swimming pools, gyms, and shopping centers. This is an excellent opportunity for individuals or small families seeking a premium rental experience in Ho Chi Minh City.', '{"Sleek dining area with elegant decor elements","Stylish entertainment area with ambient lighting","Sophisticated entertainment area with stylish decor"}', '{"Fully furnished","River view","High floor","Dining Table",Sofa,"Bar Stools","Kitchen Appliances","Decorative Elements","Coffee Table",Television,"Floor-to-ceiling Windows","Marble Countertops","Decorative Artwork",Plant,"Lighting Fixtures","TV Stand","Smart TV",Chandelier,"Decorative Plants","Dining Chairs"}', '{https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr38177579/0.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr38177579/1.jpg,https://gbgrwjdmytaksrztcyzs.supabase.co/storage/v1/object/public/external-property-images/batdongsan-pr38177579/2.jpg}', NULL, NULL, NULL, '{"cozy": 6, "urban": 8, "colors": ["Warm", "Neutral", "Cool", "Refined"], "modern": 8, "rustic": 2, "styles": ["Elegant", "Modern", "Urban"], "elegant": 9, "colorful": 4, "spacious": 6, "luxurious": 7, "activities": ["Dining", "Entertaining", "Hosting movie nights", "Relaxing with friends", "Hosting friends"], "minimalist": 7, "natural_light": 6, "image_analyses": [{"amenities": ["Dining Table", "Sofa", "Bar Stools", "Kitchen Appliances", "Decorative Elements"], "image_index": 0, "vibe_scores": {"cozy": 6, "urban": 8, "modern": 8, "elegant": 9, "spacious": 6, "luxurious": 9, "minimalist": 7, "natural_light": 5}, "image_highlight": "Sleek dining area with elegant decor elements", "detailed_analysis": "The image showcases an elegant dining area seamlessly integrated with a modern kitchen space. The sleek, dark cabinetry contrasts beautifully with the light-colored dining furniture, creating a striking visual appeal. Textured elements and decorative accents add sophistication, while the layout promotes effortless entertaining. The natural light enhances the ambiance, making it an inviting space for gatherings. This area exemplifies a contemporary lifestyle, merging functionality with aesthetic charm.", "suggested_amenities": ["Dining Table", "Kitchen Appliances"], "suggested_activities": ["Dining", "Entertaining"]}, {"amenities": ["Sofa", "Coffee Table", "Television", "Floor-to-ceiling Windows", "Marble Countertops", "Decorative Artwork", "Plant", "Lighting Fixtures"], "image_index": 1, "vibe_scores": {"cozy": 5, "urban": 8, "modern": 8, "elegant": 9, "spacious": 7, "luxurious": 7, "minimalist": 6, "natural_light": 5}, "image_highlight": "Stylish entertainment area with ambient lighting", "detailed_analysis": "This elegantly designed living space features a stylish sofa paired with a chic coffee table, creating an inviting entertainment area perfect for both relaxation and social gatherings. The ambient lighting enhances the modern aesthetic, while the floor-to-ceiling windows invite natural light, fostering an uplifting atmosphere. Decorative artwork adds a touch of sophistication, making this space ideal for hosting or unwinding after a long day. The seamless flow between the living area and kitchen promotes a connected lifestyle.", "suggested_amenities": ["Television", "Sofa"], "suggested_activities": ["Hosting movie nights", "Relaxing with friends"]}, {"amenities": ["Sofa", "Coffee Table", "TV Stand", "Smart TV", "Chandelier", "Decorative Plants", "Dining Table", "Dining Chairs"], "image_index": 2, "vibe_scores": {"cozy": 7, "urban": 7, "modern": 8, "elegant": 8, "spacious": 6, "luxurious": 6, "minimalist": 9, "natural_light": 8}, "image_highlight": "Sophisticated entertainment area with stylish decor", "detailed_analysis": "This sophisticated entertainment area blends modern elegance with cozy comfort. The plush sofa invites relaxation, while the stylish coffee table and smart TV create an inviting space for movie nights. Ambient chandelier lighting enhances the atmosphere, complemented by decorative plants that add a touch of nature. The well-placed dining area fosters social gatherings, ensuring a seamless flow between relaxation and entertainment. The palette of soft colors and textures adds warmth, making this space a perfect backdrop for both intimate moments and lively gatherings.", "suggested_amenities": ["Smart TV", "Chandelier"], "suggested_activities": ["Hosting friends", "Relaxing with a movie"]}]}', '2026-04-07 11:30:33.52+00', '2026-06-24 15:31:44.469+00', '2026-06-13 03:00:03.637+00', true, '2026-04-07 11:30:33.629219+00', '2026-06-14 15:31:45.804769+00', NULL, NULL, '2 Bedrooms', 0, 'alive', NULL, NULL, 0, 'pending', false, NULL),
